export type cloneref = (target: Instance) -> Instance

export type Window = {
    Name: string,
    Keybind: string | Enum.KeyCode,
    Logo: string,
    Scale: UDim2,
    TextSize: number
}

export type ConfigManager = {
    Directory: string,
    Config: string,
}

export type WriteConfig = {
    Name: string,
    Author: string,
}

export type WindowUpdate = {
    Username: string,
    ExpireDate: string,
    Logo: string,
    WindowName: string,
    UserProfile: string
}

export type ConfigFunctions = {
    Directory: string,
    WriteConfig: (self: ConfigFunctions, Config: WriteConfig) -> any?,
    ReadInfo: (self: ConfigFunctions, ConfigName: string) -> any?,
    DeleteConfig: (self: ConfigFunctions, ConfigName: string) -> any?,
    LoadConfig: (self: ConfigFunctions, ConfigName: string) -> any?,
    GetConfigs: (self: ConfigFunctions, ConfigName: string) -> {string},
    GetConfigCount: (self: ConfigFunctions) -> number,
    GetFullConfigs: (self: ConfigFunctions, ConfigName: string) -> {
        {
            Name: string,
            Info: {
                Type: string,
                Author: string,
                Name: string,
                CreatedDate: string,
            }
        }
    },
}

export type KeybindSettings = {
    Key: string,
    On: boolean | number,
    Off: boolean | number,
    Mode: number,
    Name: string,
}

export type SecurityConfig = {
    BlurEnabled: boolean,
    ImageScale: number,
}

export type Notify = {
    Icon: string,
    Title: string,
    Content: string,
    Duration: number
}

export type NotifyPayback = {
    SetProgress: (self: Notify, time: number) -> any?,
    Content: (self: Notify, str: string) -> any?,
    Title: (self: Notify, str: string) -> any?,
    Close: () -> any?,
}

export type Watermark = {
    Icon: string,
    Text: string
}

export type TabConfig = {
    Name: string,
    Icon: string,
    Type: string,
    EnableScrolling: boolean
}

export type TabConfigManager = {
    Name: string,
    Icon: string,
    Config: ConfigFunctions
}

export type ContainerTab = {
    Name: string,
    Icon: string,
    EnableScrolling: boolean
}

export type Category = {
    Name: string
}

export type Section = {
    Name: string,
    Position: string
}

export type Toggle = {
    Name: string,
    Default: boolean,
    Flag: string | nil,
    Risky: boolean,
    Callback: (Value: boolean) -> any?
}

export type MiniToggle = {
    Default: boolean,
    Flag: string | nil,
    Callback: (Value: boolean) -> any?
}

export type TextBoxConfig = {
    Name: string,
    Default: string,
    Placeholder: string,
    Flag: string | nil,
    Numeric: boolean,
    Callback: (Text: string) -> any?
}

export type ColorPicker = {
    Name: string,
    Default: Color3,
    Flag: string | nil,
    Transparency: number,
    Callback: (Value: Color3, Trans: number) -> any?
}

export type MiniColorPicker = {
    Default: Color3,
    Transparency: number,
    Flag: string | nil,
    Callback: (Value: Color3, Trans: number) -> any?
}

export type Slider = {
    Name: string,
    Min: number,
    Max: number,
    Default: number,
    Type: string,
    Round: number,
    Callback: (Value: number) -> any?
}

export type Dropdown = {
    Name: string,
    Default: string | {string},
    Values: {string},
    Multi: boolean,
    Callback: (Value: string | {[string]: boolean}) -> any?
}

export type Button = {
    Name: string,
    Callback: () -> any?
}

export type Keybind = {
    Name: string,
    Default: string | Enum.KeyCode,
    Callback: (Value: string) -> any,
    Blacklist: {string | Enum.KeyCode}
}

export type MiniKeybind = {
    Default: string | Enum.KeyCode,
    Callback: (Value: string) -> any,
    Blacklist: {string | Enum.KeyCode}
}

export type Helper = {
    Text: string
}

export type Paragraph = {
    Title: string,
    Content: string
}

