function Atramenta:OptimizeMode(v)
    Atramenta.PerformanceMode = v
end

function Atramenta:IsStudio()
    return RunService:IsStudio()
end

function Atramenta:CustomIconHighlight()
    Atramenta.CustomHighlightMode = true
end

function Atramenta:_SetNilP(Ins: Instance, Parent: Instance)
    Atramenta.WindowsNil = Atramenta.WindowsNil or {}
    Atramenta.NilFolder = Atramenta.NilFolder or Instance.new('Folder')

    if not Atramenta.WindowsNil[Ins] then
        local win = Atramenta:_GetWindowFromElement(Ins)

        Atramenta.WindowsNil[Ins] = win
    end

    Ins.Parent = Parent or Atramenta.NilFolder
end

function Atramenta:SetAllText(flags: {[string]: string})
    if not flags then
        for i, v in next, Atramenta.Flags do
            if v.SetText then
                v:SetText(nil)
            end
        end

        return
    end

    flags = flags or {}

    for i, v in next, flags do
        if Atramenta.Flags[i] and Atramenta.Flags[i].SetText then
            Atramenta.Flags[i]:SetText(v)
        end
    end
end

function Atramenta:_GetIcon(name: string, font_aws): string
    if Atramenta.SecureMode then
        local AssetId

        if font_aws then
            AssetId = Atramenta.FontAwesome[name] or name
        else
            AssetId = Atramenta.Lucide['lucide-'..tostring(name)] or Atramenta.Lucide[name] or Atramenta.Lucide[tostring(name)] or Atramenta.FontAwesome[name] or name
        end

        if AssetId and AssetId ~= nil then
            local asset = Atramenta:CacheImage(AssetId)

            return asset
        end

        return ""
    end

    if font_aws then
        return Atramenta.FontAwesome[name] or name
    end

    return Atramenta.Lucide['lucide-'..tostring(name)] or Atramenta.Lucide[name] or Atramenta.Lucide[tostring(name)] or Atramenta.FontAwesome[name] or name
end

function Atramenta:_RandomString(): string
    return "CK="..string.char(math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102),math.random(64,102))
end

function Atramenta:_IsMouseOverFrame(Frame: Frame): boolean
    if not Frame then
        return
    end

    local AbsPos: Vector2, AbsSize: Vector2 = Frame.AbsolutePosition, Frame.AbsoluteSize

    if Mouse.X >= AbsPos.X and Mouse.X <= AbsPos.X + AbsSize.X and Mouse.Y >= AbsPos.Y and Mouse.Y <= AbsPos.Y + AbsSize.Y then
        return true
    end
end

function Atramenta:_Rounding(num: number, numDecimalPlaces: number): number
    local mult: number = 10 ^ (numDecimalPlaces or 0)
    return math.floor(num * mult + 0.5) / mult
end

function Atramenta:_Animation(Self: Instance, Info: TweenInfo, Property :{[K]: V})
    local Tween = TweenService:Create(Self, Info or TweenInfo.new(0.25), Property)

    Tween:Play()

    return Tween
end

function Atramenta:_Input(Frame: Frame, Callback: () -> ()): TextButton
    local Button = Instance.new('TextButton',Frame)

    Button.ZIndex = Frame.ZIndex + 10
    Button.Size = UDim2.fromScale(1, 1)
    Button.BackgroundTransparency = 1
    Button.TextTransparency = 1

    if Callback then
        Button.MouseButton1Click:Connect(Callback)
    end

    return Button
end

function Atramenta:GetCalculatePosition(planePos: number, planeNormal: number, rayOrigin: number, rayDirection: number): number
    local n = planeNormal
    local d = rayDirection
    local v = rayOrigin - planePos

    local num = (n.x * v.x) + (n.y * v.y) + (n.z * v.z)
    local den = (n.x * d.x) + (n.y * d.y) + (n.z * d.z)
    local a = -num / den

    return rayOrigin + (a * rayDirection)
end

function Atramenta:_Blur(element: Frame, WindowRemote): RBXScriptSignal
    if Atramenta.SecureMode and not Atramenta.SecurityConfig.BlurEnabled then
        return game.Changed:Connect(function() end)
    end

    local Part = Instance.new('Part',Atramenta.ArcylicParent)
    local DepthOfField = Instance.new('DepthOfFieldEffect',cloneref(game:GetService('Lighting')))
    local BlockMesh = Instance.new("BlockMesh")
    local userSettings = UserSettings():GetService("UserGameSettings")

    BlockMesh.Parent = Part

    Part.Material = Enum.Material.Glass
    Part.Transparency = 1
    Part.Reflectance = 1
    Part.CastShadow = false
    Part.Anchored = true
    Part.CanCollide = false
    Part.CanQuery = false
    Part.CollisionGroup = Atramenta:_RandomString()
    Part.Size = Vector3.new(1, 1, 1) * 0.01
    Part.Color = Color3.fromRGB(0, 0, 0)

    DepthOfField.Enabled = true
    DepthOfField.FarIntensity = 0
    DepthOfField.FocusDistance = 0
    DepthOfField.InFocusRadius = 1000
    DepthOfField.NearIntensity = 1
    DepthOfField.Name = Atramenta:_RandomString()

    Part.Name = Atramenta:_RandomString()

    local disconnect

    local UpdateFunction = function()
        if Atramenta.SecureMode then
            if Part then
                Part:Destroy()
                Part = nil
            end

            if DepthOfField then
                DepthOfField:Destroy()
                DepthOfField = nil
            end

            if BlockMesh then
                BlockMesh:Destroy()
                BlockMesh = nil
            end

            if disconnect then
                disconnect()
                disconnect = nil
            end

            return
        end

        local IsWindowActive = WindowRemote:GetValue()

        if IsWindowActive then

            Atramenta:_Animation(DepthOfField, TweenInfo.new(0.1), {
                NearIntensity = 1
            })

            Atramenta:_Animation(Part, TweenInfo.new(0.1), {
                Transparency = 0.97,
                Size = Vector3.new(1, 1, 1) * 0.01
            })
        else
            Atramenta:_Animation(DepthOfField, TweenInfo.new(0.1), {
                NearIntensity = 0
            })

            Atramenta:_Animation(Part, TweenInfo.new(0.1), {
                Size = Vector3.zero,
                Transparency = 1.5,
            })

            return false
        end

        if IsWindowActive then
            local corner0 = element.AbsolutePosition
            local corner1 = corner0 + element.AbsoluteSize

            local ray0 = CurrentCamera.ScreenPointToRay(CurrentCamera, corner0.X, corner0.Y, 1)
            local ray1 = CurrentCamera.ScreenPointToRay(CurrentCamera, corner1.X, corner1.Y, 1)

            local planeOrigin = CurrentCamera.CFrame.Position + CurrentCamera.CFrame.LookVector * (0.05 - CurrentCamera.NearPlaneZ)

            local planeNormal = CurrentCamera.CFrame.LookVector

            local pos0 = Atramenta:GetCalculatePosition(planeOrigin, planeNormal, ray0.Origin, ray0.Direction)
            local pos1 = Atramenta:GetCalculatePosition(planeOrigin, planeNormal, ray1.Origin, ray1.Direction)

            pos0 = CurrentCamera.CFrame:PointToObjectSpace(pos0)
            pos1 = CurrentCamera.CFrame:PointToObjectSpace(pos1)

            local size = pos1 - pos0
            local center = (pos0 + pos1) / 2

            BlockMesh.Offset = center
            BlockMesh.Scale = size / 0.0101
            Part.CFrame = CurrentCamera.CFrame
        end
    end

    local rbxsignal = CurrentCamera:GetPropertyChangedSignal('CFrame'):Connect(UpdateFunction)
    local loopThread = UserInputService.InputChanged:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
            pcall(UpdateFunction)
        end
    end)

    local THREAD = task.spawn(function()
        while true do task.wait(0.1)
            pcall(UpdateFunction)
        end
    end)

    disconnect = function()
        rbxsignal:Disconnect()
        loopThread:Disconnect()
        task.cancel(THREAD)
        Part:Destroy()
        DepthOfField:Destroy()
    end

    element.Destroying:Connect(disconnect)

    return rbxsignal
end

function Atramenta:_AddDragBlacklist(Frame: Frame)
    local IsAdded = false
    local BASE_TIME = 0.01

    local SET_BLACKLIST = function(value)
        local index = table.find(Atramenta.DragBlacklist, Frame)

        if value and not Atramenta.IS_DRAG_MOVE then
            if not index then
                table.insert(Atramenta.DragBlacklist, Frame)
            end
        else
            if index then
                table.remove(Atramenta.DragBlacklist, index)
            end
        end
    end

    Frame.InputBegan:Connect(function(input)
        if Atramenta:_IsMouseOverFrame(Frame) then
            SET_BLACKLIST(true)
        end
    end)

    Frame.InputEnded:Connect(function(input)
        SET_BLACKLIST(false)
    end)

    UserInputService.InputChanged:Connect(function()
        if not Atramenta:_IsMouseOverFrame(Frame) then
            SET_BLACKLIST(false)
        end
    end)
end

function Atramenta:_GetWindowFromElement(Element)
    if Atramenta.WindowsNil[Element] then
        return Atramenta.WindowsNil[Element]
    end

    for i, v: ScreenGui in next, Atramenta.Windows do
        if v and Element:IsDescendantOf(v) then
            return v
        end
    end

    for Frame, Window in next, Atramenta.WindowsNil do
        if Element:IsDescendantOf(Frame) or Frame == Element then
            return Window
        end
    end
end

function Atramenta.__SIGNAL(default)
    local Bindable = Instance.new('BindableEvent')

    Bindable.Name = string.sub(tostring({}), 7)

    Bindable:SetAttribute('Value',default)

    local Binds = {
        __signals = {}
    }

    function Binds:Connect(event)
        event(Bindable:GetAttribute("Value"))

        local signal = Bindable.Event:Connect(event)

        table.insert(Binds.__signals, signal)

        return signal
    end

    function Binds:Fire(value)
        local IsSame = Bindable:GetAttribute("Value") == value

        Bindable:SetAttribute('Value',value)

        if not IsSame then
            Bindable:Fire(value)
        end
    end

    function Binds:GetValue()
        return Bindable:GetAttribute("Value")
    end

    return Binds
end

function Atramenta:_Hover(Frame: Frame, OnHover: () -> any?, Release: () -> any?)
    Frame.MouseEnter:Connect(OnHover)

    Frame.MouseLeave:Connect(Release)
end

function Atramenta.__CONFIG(config, default)
    config = config or {}

    for i, v in next, default do
        if config[i] == nil then
            config[i] = v
        end
    end

    return config
end

function Atramenta:Drag(InputFrame: Frame, MoveFrame: Frame, Speed: number)
    local dragToggle: boolean = false
    local dragStart: Vector3 = nil
    local startPos: UDim2 = nil
    local Tween = TweenInfo.new(Speed)

    local updateInput = function(input)
        local delta = input.Position - dragStart
        local position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X,
            startPos.Y.Scale, startPos.Y.Offset + delta.Y)

        Atramenta:_Animation(MoveFrame, Tween, {
            Position = position
        })
    end

    InputFrame.InputBegan:Connect(function(input)
        if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) and #Atramenta.DragBlacklist <= 0 then
            dragToggle = true
            dragStart = input.Position
            startPos = MoveFrame.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragToggle = false
                    Atramenta.IS_DRAG_MOVE = false
                end
            end)
        end

        if not Atramenta.IsDrage and dragToggle then
            Atramenta.LastDrag = tick()
        end

        Atramenta.IaDrag = dragToggle
    end)

    UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch and #Atramenta.DragBlacklist <= 0 then
            if dragToggle then
                Atramenta.IS_DRAG_MOVE = true
                updateInput(input)
            else
                Atramenta.IS_DRAG_MOVE = false
            end
        else
            if #Atramenta.DragBlacklist > 0 then
                dragToggle = false
                Atramenta.IS_DRAG_MOVE = false
            end
        end

        Atramenta.IaDrag = dragToggle
    end)
end

function Atramenta:_IsMobile()
    return UserInputService.TouchEnabled
end

function Atramenta:_AddLinkValue(Name, Default, GlobalBlock, LinkValues, rep, Signal)
    if Name == "Toggle" then
        local Toggle = Instance.new("Frame")
        local UICorner = Instance.new("UICorner")
        local UIStroke = Instance.new("UIStroke")
        local ToggleValue = Instance.new("Frame")
        local UICorner_2 = Instance.new("UICorner")

        Toggle.Name = Atramenta:_RandomString()
        Toggle.Parent = LinkValues
        Toggle.BackgroundColor3 = Atramenta.Colors.DropColor
        Toggle.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Toggle.BorderSizePixel = 0
        Toggle.Size = UDim2.new(0, 30, 0, 16)
        Toggle.ZIndex = GlobalBlock.ZIndex + 1
        Toggle.LayoutOrder = -#LinkValues:GetChildren()

        table.insert(Atramenta.Elements.DropColor, {
            Element = Toggle,
            Property = "BackgroundColor3"
        })

        UICorner.CornerRadius = UDim.new(1, 0)
        UICorner.Parent = Toggle

        UIStroke.Color = Atramenta.Colors.HighStrokeColor
        UIStroke.Parent = Toggle

        table.insert(Atramenta.Elements.HighStrokeColor, {
            Element = UIStroke,
            Property = "Color"
        })

        ToggleValue.Name = Atramenta:_RandomString()
        ToggleValue.Parent = Toggle
        ToggleValue.AnchorPoint = Vector2.new(0.5, 0.5)
        ToggleValue.BackgroundColor3 = Atramenta.Colors.SwitchColor
        ToggleValue.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ToggleValue.BorderSizePixel = 0
        ToggleValue.Position = UDim2.new(0.25, 0, 0.5, 0)
        ToggleValue.Size = UDim2.new(0.550000012, 0, 0.550000012, 0)
        ToggleValue.SizeConstraint = Enum.SizeConstraint.RelativeYY
        ToggleValue.ZIndex = GlobalBlock.ZIndex + 2

        UICorner_2.CornerRadius = UDim.new(1, 0)
        UICorner_2.Parent = ToggleValue

        local ToggleElement = function(bool, noChange)
            if not noChange then
                Default = bool
            end

            if bool then
                Toggle:SetAttribute('Enabled',true)

                Atramenta:_Animation(ToggleValue, rep.Tween, {
                    Position = UDim2.new(0.75, 0, 0.5, 0)
                })

                Atramenta:_Animation(Toggle, rep.Tween, {
                    BackgroundColor3 = Atramenta.Colors.Toggle
                })
            else
                Toggle:SetAttribute('Enabled',false)

                Atramenta:_Animation(ToggleValue, rep.Tween, {
                    Position = UDim2.new(0.25, 0, 0.5, 0)
                })

                Atramenta:_Animation(Toggle, rep.Tween, {
                    BackgroundColor3 = Atramenta.Colors.DropColor
                })
            end
        end

        local Input = Atramenta:_Input(Toggle)

        Atramenta:_Hover(Input, function()
            if not Default then
                Atramenta:_Animation(ToggleValue, rep.Tween, {
                    Size = UDim2.new(0.6, 0, 0.6, 0)
                })
            end
        end, function()
            Atramenta:_Animation(ToggleValue, rep.Tween, {
                Size = UDim2.new(0.550000012, 0, 0.550000012, 0)
            })
        end)

        local ToggleUI = function(bool)
            if bool then
                ToggleElement(Default, true)

                Atramenta:_Animation(ToggleValue, rep.Tween, {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(Toggle, rep.Tween, {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(UIStroke, rep.Tween, {
                    Transparency = 0
                })
            else
                ToggleElement(false, true)

                Atramenta:_Animation(ToggleValue, rep.Tween, {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(Toggle, rep.Tween, {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(UIStroke, rep.Tween, {
                    Transparency = 1
                })
            end
        end

        ToggleElement(Default)

        Signal:Connect(ToggleUI)

        return {
            Root = Toggle,
            ChangeValue = ToggleElement,
            Input = Input,
            ToggleUI = ToggleUI,
        }
    elseif Name == "ColorPicker" then
        local ColorPicker = Instance.new("Frame")
        local ColorFrame = Instance.new("Frame")
        local UIScale = Instance.new("UIScale")
        local UIStroke = Instance.new("UIStroke")
        local UICorner = Instance.new("UICorner")

        ColorPicker.Name = Atramenta:_RandomString()
        ColorPicker.Parent = LinkValues
        ColorPicker.BackgroundTransparency = 1.000
        ColorPicker.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ColorPicker.BorderSizePixel = 0
        ColorPicker.Size = UDim2.new(0, 16, 0, 16)
        ColorPicker.ZIndex = GlobalBlock.ZIndex + 1
        ColorPicker.LayoutOrder = -#LinkValues:GetChildren()

        ColorFrame.Name = Atramenta:_RandomString()
        ColorFrame.Parent = ColorPicker
        ColorFrame.AnchorPoint = Vector2.new(0.5, 0.5)
        ColorFrame.BackgroundColor3 = Color3.fromRGB(15, 255, 207)
        ColorFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ColorFrame.BorderSizePixel = 0
        ColorFrame.Position = UDim2.new(0.5, 0, 0.5, 0)
        ColorFrame.Size = UDim2.new(1, -1, 1, -1)
        ColorFrame.ZIndex = GlobalBlock.ZIndex + 1

        UIScale.Parent = ColorFrame

        UIStroke.Color = Atramenta.Colors.HighStrokeColor
        UIStroke.Parent = ColorFrame

        table.insert(Atramenta.Elements.HighStrokeColor, {
            Element = UIStroke,
            Property = "Color"
        })

        UICorner.CornerRadius = UDim.new(0, 3)
        UICorner.Parent = ColorFrame

        Signal:Connect(function(bool)
            if bool then
                Atramenta:_Animation(ColorFrame, TweenInfo.new(0.15), {
                    BackgroundTransparency = 0,
                })

                Atramenta:_Animation(UIStroke, TweenInfo.new(0.15), {
                    Transparency = 0,
                })
            else
                Atramenta:_Animation(ColorFrame, TweenInfo.new(0.15), {
                    BackgroundTransparency = 1,
                })

