    local Tween = TweenInfo.new(0.2, Enum.EasingStyle.Quad)
    local Tween2 = TweenInfo.new(0.275, Enum.EasingStyle.Quad)

    Atramenta:_AddPropertyEvent(ColorPickerWindow, function(v)
        ColorPickerWindow.Visible = v

        if Atramenta.PerformanceMode then
            if ColorPickerWindow.Visible then
                Atramenta:_SetNilP(ColorPickerWindow, Window)
            else
                Atramenta:_SetNilP(ColorPickerWindow, nil)
            end
        else
            Atramenta:_SetNilP(ColorPickerWindow, Window)
        end
    end)

    local ToggleUI = function(bool)
        local IsSame = Args.IsVisible == bool

        Args.IsVisible = bool

        local MainPosition = UDim2.new(0, Button.AbsolutePosition.X + 95, 0, Button.AbsolutePosition.Y + 65)
        local DropPosition = UDim2.new(0, MainPosition.X.Offset, 0, MainPosition.Y.Offset + 15)

        local MUL = Window.AbsoluteSize.Y / 2

        if MainPosition.Y.Offset > MUL then
            MainPosition = UDim2.fromOffset(Button.AbsolutePosition.X, Button.AbsolutePosition.Y + 45)
            DropPosition = UDim2.fromOffset(MainPosition.X.Offset, MainPosition.Y.Offset - 25)

            ColorPickerWindow.AnchorPoint = Vector2.new(0.5, 1)
        else
            ColorPickerWindow.AnchorPoint = Vector2.new(0.5, 0)
        end

        if bool then

            if not IsSame then
                ColorPickerWindow.Position = DropPosition
            end

            Atramenta:_Animation(ColorPickerWindow, Tween2, {
                BackgroundTransparency = 0,
                Size = UDim2.new(0, 175, 0, 200)
            })

            Atramenta:_Animation(ColorPickerWindow, Tween, {
                Position = MainPosition,
            })

            Atramenta:_Animation(UIStroke_8, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(UIStroke_7, Tween, {
                Transparency = 0.5
            })

            Atramenta:_Animation(UIStroke_6, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(UIStroke_5, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(UIStroke_4, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(UIStroke_3, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(UIStroke_2, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(UIStroke, Tween, {
                Transparency = 0
            })

            Atramenta:_Animation(ColorPickBox, Tween, {
                BackgroundTransparency = 0,
                ImageTransparency = 0
            })

            Atramenta:_Animation(MouseMovement, Tween, {
                ImageTransparency = 0
            })

            Atramenta:_Animation(ColorOpc, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(TransparentImage, Tween, {
                ImageTransparency = 0
            })

            Atramenta:_Animation(Left, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(Left_2, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(Right, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(Right_2, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(ColorRedGreenBlue, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(HexFrame, Tween, {
                BackgroundTransparency = 0
            })

            Atramenta:_Animation(TextLabel, Tween, {
                TextTransparency = 0
            })
        else
            Atramenta:_Animation(UIStroke_8, Tween, {
                Transparency = 1
            })

            Atramenta:_Animation(UIStroke_7, Tween, {
                Transparency = 1
            })

            Atramenta:_Animation(UIStroke_6, Tween, {
                Transparency = 1
            })

            Atramenta:_Animation(UIStroke_5, Tween, {
                Transparency = 1
            })

