            })

            Atramenta:_Animation(ColorPickerWindow, Tween2, {
                BackgroundTransparency = 1,
            })

            Atramenta:_Animation(ColorPickerWindow, Tween, {
                Position = DropPosition,
            })

            Atramenta:_Animation(ColorPickBox, Tween, {
                BackgroundTransparency = 1,
                ImageTransparency = 1
            })

            Atramenta:_Animation(MouseMovement, Tween, {
                ImageTransparency = 1
            })

            Atramenta:_Animation(ColorOpc, Tween, {
