    local Ref = {
        Root = Keybinds
    }

    Ref.THREAD = task.spawn(function()
        while true do task.wait()
            Atramenta:_Animation(MainFrame, TweenInfo.new(0.4), {
                Size = UDim2.new(1, 30, 1, UIListLayout.AbsoluteContentSize.Y + 1)
            })

            if UIListLayout.AbsoluteContentSize.Y > 1 then
                Atramenta:_Animation(IconFrame, TweenInfo.new(0.25), {
                    BackgroundTransparency = 0.3
                })

                Atramenta:_Animation(Frame, TweenInfo.new(0.25), {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(HeadLabel, TweenInfo.new(0.25), {
                    TextTransparency = 0
                })

                Atramenta:_Animation(Icon, TweenInfo.new(0.25), {
                    ImageTransparency = 0
                })

                local LargF = 100

                for i, v in next, MainFrame:GetChildren() do
                    if v:GetAttribute('AvgScale') then
                        if v:GetAttribute('AvgScale') > LargF then
                            LargF = v:GetAttribute('AvgScale')
                        end
                    end
                end

                Atramenta:_Animation(Keybinds, TweenInfo.new(0.25), {
                    BackgroundTransparency = 0.025,
                    Size = UDim2.new(0, LargF, 0, 25)
                })
            else
                Atramenta:_Animation(HeadLabel, TweenInfo.new(0.25), {
                    TextTransparency = 1
                })

                Atramenta:_Animation(Keybinds, TweenInfo.new(0.25), {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(IconFrame, TweenInfo.new(0.25), {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(Frame, TweenInfo.new(0.25), {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(Icon, TweenInfo.new(0.25), {
                    ImageTransparency = 1
                })
            end

            Keybinds.Visible = (Keybinds.BackgroundTransparency < 0.9 and true) or false

            if Atramenta.PerformanceMode then
                if Keybinds.Visible then
                    Atramenta:_SetNilP(Keybinds, Window)
                else
                    Atramenta:_SetNilP(Keybinds, nil)
                end
            else
                Atramenta:_SetNilP(Keybinds, Window)
            end
        end
    end)

