        SliderInput.Name = Atramenta:_RandomString()
        SliderInput.Parent = SliderBar
        SliderInput.AnchorPoint = Vector2.new(0, 0.5)
        SliderInput.BackgroundColor3 = Atramenta.Colors.Highlight
        SliderInput.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SliderInput.BorderSizePixel = 0
        SliderInput.Position = UDim2.new(0, 0, 0.5, 0)
        SliderInput.Size = UDim2.new(math.max((Config.Default - Config.Min) / (Config.Max - Config.Min), 0.045), 0, 1, 0)
        SliderInput.ZIndex = Zindex + 4

        table.insert(Atramenta.Elements.Highlight, {
            Element = SliderInput,
            Property = "BackgroundColor3"
        })

        UICorner_2.CornerRadius = UDim.new(0, 6)
        UICorner_2.Parent = SliderInput

        Frame.Parent = SliderInput
        Frame.AnchorPoint = Vector2.new(1, 0.5)
        Frame.BackgroundColor3 = Atramenta.Colors.SwitchColor
        Frame.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Frame.BorderSizePixel = 0
        Frame.Position = UDim2.new(1, 5, 0.5, 0)
        Frame.Rotation = 45.000
        Frame.Size = UDim2.new(1, 0, 1, 0)
        Frame.SizeConstraint = Enum.SizeConstraint.RelativeYY
        Frame.ZIndex = Zindex + 6

        table.insert(Atramenta.Elements.SwitchColor, {
            Element = Frame,
            Property = 'BackgroundColor3'
        })

        UICorner_3.CornerRadius = UDim.new(3, 0)
        UICorner_3.Parent = Frame

        UIScale.Parent = Frame
        UIScale.Scale = 1.300

        ValueText.Name = Atramenta:_RandomString()
        ValueText.Parent = Slider
        ValueText.BackgroundTransparency = 1.000
        ValueText.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ValueText.BorderSizePixel = 0
        ValueText.Position = UDim2.new(0, 12, 0, 1)
        ValueText.Size = UDim2.new(1, -20, 0, 25)
        ValueText.ZIndex = Zindex + 4
        ValueText.Font = Enum.Font.GothamMedium
        ValueText.Text = tostring(Config.Default)..tostring(Config.Type)
        ValueText.TextColor3 = Atramenta.Colors.SwitchColor
        ValueText.TextSize = 12.000
        ValueText.TextTransparency = 0.750
        ValueText.TextXAlignment = Enum.TextXAlignment.Right

        table.insert(Atramenta.Elements.SwitchColor, {
            Element = ValueText,
            Property = 'TextColor3'
        })

        Atramenta:_Hover(SliderBar, function()
            if Signal:GetValue() then
                Atramenta:_Animation(ValueText, TweenInfo.new(0.2), {
                    TextTransparency = 0.2
                })
            end
        end, function()
            if Signal:GetValue() then
                Atramenta:_Animation(ValueText, TweenInfo.new(0.2), {
                    TextTransparency = 0.750
                })
            end
        end)

        local IsHold = false

        local Update = function(Input)
            local SizeScale = math.clamp((((Input.Position.X) - SliderBar.AbsolutePosition.X) / SliderBar.AbsoluteSize.X), 0, 1)

            local Main = ((Config.Max - Config.Min) * SizeScale) + Config.Min

            local Value = Atramenta:_Rounding(Main, Config.Round)

            local PositionX = UDim2.fromScale(SizeScale, 1)

            local Size = (Value - Config.Min) / (Config.Max - Config.Min)

            TweenService:Create(SliderInput, TweenInfo.new(0.2), {
                Size = UDim2.new(math.clamp(Size, 0.045, 1), 0, 1, 0)
            }):Play()

            Config.Default = Value

            ValueText.Text = tostring(Config.Default)..tostring(Config.Type)

            Config.Callback(Value)
        end

        do
            SliderBar.InputBegan:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    IsHold = true
                    Update(Input)
                end
            end)

            SliderBar.InputEnded:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    if UserInputService.TouchEnabled then
                        if not Atramenta:_IsMouseOverFrame(SliderBar) then
                            IsHold = false
                        end
                    else
                        IsHold = false
                    end
                end
            end)

            UserInputService.InputChanged:Connect(function(Input)
                if IsHold then
                    if (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then
                        if UserInputService.TouchEnabled then
                            if not Atramenta:_IsMouseOverFrame(SliderBar) then
                                IsHold = false
                            else
                                Update(Input)
                            end
                        else
                            Update(Input)
                        end
                    end
                end
            end)
        end

        local Args = {}

        Args.Flag = Config.Flag

        function Args:SetValue(Value)
            Config.Default = Value

            ValueText.Text = tostring(Config.Default)..tostring(Config.Type)

            Atramenta:_Animation(SliderInput, TweenInfo.new(0.35), {
                Size = UDim2.new(math.max((Config.Default - Config.Min) / (Config.Max - Config.Min), 0.045), 0, 1, 0)
            })

            Config.Callback(Value)
        end

        function Args:SetText(str: string)
            BlockText.Text = str or Config.Name
        end

        function Args:GetText()
            return BlockText.Text
        end

        Args.Signal = Signal:Connect(function(bool)
            if bool then
                Atramenta:_Animation(SliderInput, TweenInfo.new(0.35), {
                    Size = UDim2.new(math.max((Config.Default - Config.Min) / (Config.Max - Config.Min), 0.045), 0, 1, 0)
                })

                Atramenta:_Animation(ValueText, Tween, {
                    TextTransparency = 0.750
                })

                Atramenta:_Animation(Frame, Tween, {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(SliderInput, Tween, {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(UIStroke, Tween, {
                    Transparency = 0
                })

                Atramenta:_Animation(SliderBar, Tween, {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(BlockLine, Tween, {
                    BackgroundTransparency = 0.5
                })

                Atramenta:_Animation(BlockText, Tween, {
                    TextTransparency = 0.1
                })
            else
                Atramenta:_Animation(SliderInput, TweenInfo.new(0.35), {
                    Size = UDim2.new(0, 0, 1, 0)
                })

                Atramenta:_Animation(ValueText, Tween, {
                    TextTransparency = 1
                })

                Atramenta:_Animation(Frame, Tween, {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(SliderInput, Tween, {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(UIStroke, Tween, {
                    Transparency = 1
                })

                Atramenta:_Animation(SliderBar, Tween, {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(BlockLine, Tween, {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(BlockText, Tween, {
                    TextTransparency = 1
                })
            end
        end)

        function Args:GetValue()
            return Config.Default
        end

        if Config.Flag then
            Atramenta.Flags[Config.Flag] = Args
        end

        if not DisableStackKeybind then
            local AutoKeybind = Atramenta:_KeybindHandler(Slider , "Number" , Args , Signal , Zindex , Config)

            Args.AutoKeybind = AutoKeybind
        end

        return Args
    end

