        TextBox_2.BackgroundTransparency = 1.000
        TextBox_2.BorderColor3 = Color3.fromRGB(0, 0, 0)
        TextBox_2.BorderSizePixel = 0
        TextBox_2.ClipsDescendants = true
        TextBox_2.Position = UDim2.new(0.5, 0, 0.5, 0)
