        UICorner.Parent = ValueItems

        ValueText.Name = Atramenta:_RandomString()
        ValueText.Parent = ValueItems
        ValueText.AnchorPoint = Vector2.new(0.5, 0.5)
        ValueText.BackgroundTransparency = 1.000
        ValueText.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ValueText.BorderSizePixel = 0
        ValueText.Position = UDim2.new(0.5, 0, 0.5, 0)
        ValueText.Size = UDim2.new(1, -10, 0, 15)
        ValueText.ZIndex = Zindex + 8
        ValueText.Font = Enum.Font.Gotham
        ValueText.Text = DaTabarser(Config.Default)
        ValueText.TextColor3 = Atramenta.Colors.SwitchColor
        ValueText.TextSize = 11.000
        ValueText.TextXAlignment = Enum.TextXAlignment.Left

        table.insert(Atramenta.Elements.SwitchColor, {
            Element = ValueText,
            Property = 'TextColor3'
        })

        MainButton.Name = Atramenta:_RandomString()
        MainButton.Parent = ValueItems
        MainButton.AnchorPoint = Vector2.new(1, 0.5)
        MainButton.BackgroundTransparency = 1.000
        MainButton.BorderColor3 = Color3.fromRGB(0, 0, 0)
        MainButton.BorderSizePixel = 0
        MainButton.Position = UDim2.new(1, -5, 0.5, 0)
        MainButton.Size = UDim2.new(0, 13, 0, 13)
        MainButton.ZIndex = Zindex + 5
        MainButton.Image = Atramenta:CacheImage("rbxassetid://109535175596957")

        Atramenta:_Hover(ValueItems, function()
            Atramenta:_Animation(ValueItems, TweenInfo.new(0.3), {
                BackgroundColor3 = Atramenta.Colors.MouseEnter
            })
        end, function()
            Atramenta:_Animation(ValueItems, TweenInfo.new(0.3), {
                BackgroundColor3 = Atramenta.Colors.DropColor
            })
        end)

        local repi
        local Button = Atramenta:_Input(ValueItems)

        repi = Atramenta:_LoadDropdown(Button, function(value)
            Config.Default = value

            repi:SetData(Config.Default, Config.Values, Config.Multi, false)
            repi:SetDefault(Config.Default)

            ValueText.Text = DaTabarser(Config.Default)

            Config.Callback(Config.Default)
        end)

        repi.EventOut:Connect(function(v)
            if v then
                Atramenta:_Animation(MainButton, TweenInfo.new(0.2), {
                    Rotation = -180
                })
            else
                Atramenta:_Animation(MainButton, TweenInfo.new(0.2), {
                    Rotation = 0
                })
            end
        end)

        repi:SetData(Config.Default, Config.Values, Config.Multi, false)
        repi:Refersh()

        local Args = {}

        Args.Flag = Config.Flag

        function Args:SetValue(Value)
            Config.Default = Value

            ValueText.Text = DaTabarser(Config.Default)

            repi:SetData(Config.Default, Config.Values, Config.Multi, true)

            Config.Callback(Value)
        end

        function Args:SetText(str: string)
            BlockText.Text = str or Config.Name
        end

        function Args:GetText()
            return BlockText.Text
        end

        function Args:SetValues(v)
            Config.Values = v

            repi:SetData(Config.Default, Config.Values, Config.Multi, true)
        end

        Args.Signal = Signal:Connect(function(bool)
            if bool then
                Atramenta:_Animation(BlockText, TweenInfo.new(0.2), {
                    TextTransparency = 0.100
                })

                Atramenta:_Animation(BlockLine, TweenInfo.new(0.2), {
                    BackgroundTransparency = 0.100
                })

                Atramenta:_Animation(ValueItems, TweenInfo.new(0.2), {
                    BackgroundTransparency = 0
                })

                Atramenta:_Animation(UIStroke, TweenInfo.new(0.2), {
                    Transparency = 0
                })

                Atramenta:_Animation(ValueText, TweenInfo.new(0.32), {
                    TextTransparency = 0
                })

                Atramenta:_Animation(MainButton, TweenInfo.new(0.2), {
                    ImageTransparency = 0
                })
            else
                Atramenta:_Animation(BlockText, TweenInfo.new(0.2), {
                    TextTransparency = 1
                })

                Atramenta:_Animation(BlockLine, TweenInfo.new(0.2), {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(ValueItems, TweenInfo.new(0.2), {
                    BackgroundTransparency = 1
                })

                Atramenta:_Animation(UIStroke, TweenInfo.new(0.2), {
                    Transparency = 1
                })

                Atramenta:_Animation(ValueText, TweenInfo.new(0.2), {
                    TextTransparency = 1
                })

                Atramenta:_Animation(MainButton, TweenInfo.new(0.2), {
                    ImageTransparency = 1
                })
            end
        end)

        Args.Link = Atramenta:_LoadOption({
            AddLink = function(self, Name, Default)
                return Atramenta:_AddLinkValue(Name, Default, LinkValues, LinkValues, {
                    Tween = TweenInfo.new(0.2)
                }, Signal)
            end,
            Root = Dropdown
        })

        function Args:GetValue()
            return Config.Default
        end

        if Config.Flag then
            Atramenta.Flags[Config.Flag] = Args
        end

        return Args
    end

    return Args
end

