function Atramenta:RefreshCurrentColor()
    for i, v in next, Atramenta.Elements.Highlight do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.Highlight
        end
    end

    for i, v in next, Atramenta.Elements do
        if v.Element and v.Property and v.Element:GetAttribute('Enabled') then
            v.Element[v.Property] = Atramenta.Colors.Highlight
        end
    end

    for i, v in next, Atramenta.Elements.Risky do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.Risky
        end
    end

    for i, v in next, Atramenta.Elements.BlockColor do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.BlockColor
        end
    end

    for i, v in next, Atramenta.Elements.BGDBColor do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.BGDBColor
        end
    end

    for i, v in next, Atramenta.Elements.StrokeColor do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.StrokeColor
        end
    end

    for i, v in next, Atramenta.Elements.SwitchColor do
        if v.Element and v.Property and v.Element[v.Property] ~= Atramenta.Colors.MouseEnter then
            v.Element[v.Property] = Atramenta.Colors.SwitchColor
        end
    end

    for i, v in next, Atramenta.Elements.BlockBackground do
        if v.Element and v.Property and v.Element[v.Property] then
            v.Element[v.Property] = Atramenta.Colors.BlockBackground
        end
    end

    for i, v in next, Atramenta.Elements.DropColor do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.DropColor
        end
    end

    for i, v in next, Atramenta.Elements.LineColor do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.LineColor
        end
    end

    for i, v in next, Atramenta.Elements.HighStrokeColor do
        if v.Element and v.Property then
            v.Element[v.Property] = Atramenta.Colors.HighStrokeColor
        end
    end
end

function Atramenta:ChangeHighlightColor(NewColor: Color3)
    local H, S, V = NewColor:ToHSV()

    Atramenta.Colors.Highlight = NewColor
    Atramenta.Colors.Toggle = Color3.fromHSV(H, S, V - 0.2)

    for i, v in next, Atramenta.Elements.Highlight do
        if v.Element and v.Property then
            v.Element[v.Property] = NewColor
        end
    end

    for i, v in next, Atramenta.Elements do
        if v.Element and v.Property and v.Element:GetAttribute('Enabled') then
            v.Element[v.Property] = NewColor
        end
    end
end

