                else
                    Signal:Fire(false)

                    Atramenta:_Animation(UserSettings, TweenInfo.new(0.2), {
                        BackgroundTransparency = 1,
                    })

                    Atramenta:_Animation(SectionFrame, TweenInfo.new(0.2), {
                        BackgroundTransparency = 1,
