                        TextTransparency = 1,
                    })

                    Atramenta:_Animation(ImageLabel, TweenInfo.new(0.2), {
                        ImageTransparency = 1,
                    })
                end
            end

            Atramenta:_Input(ImageLabel, function()
                WindowArgs.UserSettings:Window(false)
            end)

            WindowArgs.UserSettings:Window(false)

            return Atramenta:_LoadElement(SectionFrame, true, Signal)
        end
    end

