            CompLogo.Image = Config.Logo

            if Atramenta.CustomHighlightMode then
                CompLogo.ImageColor3 = Atramenta.Colors.Highlight

                table.insert(Atramenta.Elements.Highlight, {
                    Element = CompLogo,
                    Property = 'ImageColor3'
                })
            end

            WaternarkList.Name = Atramenta:_RandomString()
            WaternarkList.Parent = Watermark
            WaternarkList.AnchorPoint = Vector2.new(0.5, 0)
            WaternarkList.BackgroundTransparency = 1.000
            WaternarkList.BorderColor3 = Color3.fromRGB(0, 0, 0)
            WaternarkList.BorderSizePixel = 0
            WaternarkList.Position = UDim2.new(0.5, 0, 0, 0)
            WaternarkList.Size = UDim2.new(1, -10, 1, 0)
            WaternarkList.ZIndex = 155
            WaternarkList.ClipsDescendants = true

            UIListLayout.Parent = WaternarkList
            UIListLayout.FillDirection = Enum.FillDirection.Horizontal
            UIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
            UIListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
            UIListLayout.Padding = UDim.new(0, 3)

            local BackFrame = Instance.new("Frame")

            BackFrame.Name = Atramenta:_RandomString()
            BackFrame.Parent = Watermark
            BackFrame.AnchorPoint = Vector2.new(1, 0.5)
            BackFrame.BackgroundTransparency = 1.000
            BackFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
            BackFrame.BorderSizePixel = 0
            BackFrame.Position = UDim2.new(1, 0, 0.5, 0)
            BackFrame.Size = UDim2.new(1, 30, 1, 0)

            Atramenta:_Blur(BackFrame, Signal)

            UIListLayout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
                Atramenta:_Animation(Watermark, TweenInfo.new(0.4), {
                    Size = UDim2.new(0, UIListLayout.AbsoluteContentSize.X + 8, 0, 23)
                })
            end)

            local Args = {}

            function Args:AddText(Watermark: Watermark)
                Watermark = Atramenta.__CONFIG(Watermark, {
                    Text = "Watermark",
                    Icon = "info"
                })

                local Icon = Instance.new("ImageLabel")
                local TextLabel = Instance.new("TextLabel")

                Icon.Name = Atramenta:_RandomString()
                Icon.Parent = WaternarkList
                Icon.BackgroundTransparency = 1.000
                Icon.BorderColor3 = Color3.fromRGB(0, 0, 0)
                Icon.BorderSizePixel = 0
                Icon.Size = UDim2.fromOffset(15, 15)
                Icon.SizeConstraint = Enum.SizeConstraint.RelativeYY
                Icon.ZIndex = 156
                Icon.Image = Atramenta:_GetIcon(Watermark.Icon)

                TextLabel.Parent = WaternarkList
                TextLabel.BackgroundTransparency = 1.000
                TextLabel.BorderColor3 = Color3.fromRGB(0, 0, 0)
                TextLabel.BorderSizePixel = 0
                TextLabel.Size = UDim2.new(0, 50, 0.699999988, 0)
                TextLabel.ZIndex = 156
                TextLabel.Font = Enum.Font.GothamMedium
                TextLabel.Text = Watermark.Text
                TextLabel.TextColor3 = Atramenta.Colors.SwitchColor
                TextLabel.TextSize = 10.000
                TextLabel.TextXAlignment = Enum.TextXAlignment.Left

                table.insert(Atramenta.Elements.SwitchColor, {
                    Element = TextLabel,
                    Property = 'TextColor3'
                })

                local Update = function()
                    local scale = TextService:GetTextSize(TextLabel.Text, TextLabel.TextSize, TextLabel.Font, Vector2.new(math.huge, math.huge))

                    TextLabel.Size = UDim2.new(0, scale.X + 2, 0.7, 0)
                end

                Update()

                local Arg = {}

                function Arg:SetText(text)
                    TextLabel.Text = text
                    Update()
                end

                function Arg:Visible(v)
                    Icon.Visible = v
                    TextLabel.Visible = v

                    if Atramenta.PerformanceMode then
                        if v then
                            Atramenta:_SetNilP(Icon, WaternarkList)
                            Atramenta:_SetNilP(TextLabel, WaternarkList)
                        else
                            Atramenta:_SetNilP(Icon, nil)
                            Atramenta:_SetNilP(TextLabel, nil)
                        end
                    else
                        Atramenta:_SetNilP(Icon, WaternarkList)
                        Atramenta:_SetNilP(TextLabel, WaternarkList)
                    end
                end

                return Arg
            end

            return Args
        end

        function WindowArgs:Toggle(Value: boolean)
            if WindowArgs.PerformanceMode then
                MainFrame.Visible = Value
            end

            WindowOpen:Fire(Value)

            if Value then
                for i, v in next, WindowArgs.Tabs do
                    if v.Root == WindowArgs.SelectedTab then
                        v.Remote:Fire(true)
                    end
                end
            else
                for i, v in next, WindowArgs.Tabs do
                    v.Remote:Fire(false)
                end
            end
        end

        function WindowArgs:_ToggleUI()
            WindowArgs.IsOpen = not WindowArgs.IsOpen

            WindowArgs:Toggle(WindowArgs.IsOpen)
        end

        local Button = Atramenta:_Input(CloseWindow, function()
            WindowArgs:_ToggleUI()
        end)

        if not Atramenta:_IsMobile() then

            Atramenta:_Hover(Button, function()
                ImageLabel:SetAttribute("Hover",true)
            end, function()
                ImageLabel:SetAttribute("Hover",false)
            end)
        end

        table.insert(WindowArgs.THREADS, task.spawn(function()
            while true do task.wait(0.15)
                if Atramenta:_IsMobile() then
                    ToggleCloseUI(true)

                    if WindowArgs.IsOpen then
                        Atramenta:_Animation(ImageLabel, TweenInfo.new(0.2), {
                            ImageTransparency = 0.35
                        })

                        ImageLabel:GetAttribute("Hover",false)
                    else
                        ImageLabel:GetAttribute("Hover",true)

                        Atramenta:_Animation(ImageLabel, TweenInfo.new(0.2), {
                            ImageTransparency = 0.1
                        })
                    end
                else
                    if not WindowArgs.IsOpen then
                        ToggleCloseUI(true)
                    else
                        ToggleCloseUI(false)
                    end
                end
            end
        end))

        UserInputService.InputBegan:Connect(function(Input, Typing)
            if not Typing and (Input.KeyCode == Config.Keybind or Input.KeyCode.Name == Config.Keybind) then
                WindowArgs:_ToggleUI()
            end
        end)
    end

    function WindowArgs:SetMenuKey(new: string | Enum.KeyCode)
        Config.Keybind = new
    end

    function WindowArgs:Update(config: WindowUpdate)
        config = config or {}
        config.Logo = config.Logo or Config.Logo
        config.Username = config.Username or LocalPlayer.DisplayName
        config.ExpireDate = config.ExpireDate or "NEVER"
        config.WindowName = config.WindowName or Config.Name
        config.UserProfile = config.UserProfile or WindowArgs.Profile or string.format("rbxthumb://type=AvatarHeadShot&id=%s&w=150&h=150",tostring(LocalPlayer.UserId))

        if Atramenta.SecureMode and string.find(config.UserProfile, "rbxassetid://",1,true) then
            config.UserProfile = Atramenta:_GetIcon("user")
        end

        UserText.Text = config.Username
        CompLogo.Image = config.Logo
        ExpireText.Text = config.ExpireDate
        WindowLabel.Text = config.WindowName
        UserProfile.Image = config.UserProfile
        WindowArgs.Username = config.Username

        Config.Logo = config.Logo or Config.Logo
        WindowArgs.Username = config.Username or WindowArgs.Username
        WindowArgs.ExipreDate = config.ExpireDate or WindowArgs.ExipreDate
        Config.Name = config.WindowName or Config.Name
        WindowArgs.Profile = config.UserProfile or WindowArgs.Profile
    end

    WindowArgs.LOOP_THREAD = task.spawn(function()
        local TimeTic = tick()

        local BlurElement = Instance.new("Frame")

        BlurElement.Name = Atramenta:_RandomString()
        BlurElement.Parent = MainFrame
        BlurElement.AnchorPoint = Vector2.new(1, 0.5)
        BlurElement.BackgroundTransparency = 1.000
        BlurElement.BorderColor3 = Color3.fromRGB(0, 0, 0)
        BlurElement.BorderSizePixel = 0
        BlurElement.Position = UDim2.new(1, -5, 0.5, 0)
        BlurElement.Size = UDim2.new(1, 0, 1, 0)
        BlurElement.ZIndex = -100
        BlurElement.Active = true

        Atramenta:_Blur(BlurElement, WindowOpen)

        local MovementFrame = Instance.new("Frame")

        MovementFrame.Name = Atramenta:_RandomString()
        MovementFrame.Parent = MainFrame
        MovementFrame.AnchorPoint = Vector2.new(1, 0.5)
        MovementFrame.BackgroundTransparency = 1.000
        MovementFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
        MovementFrame.BorderSizePixel = 0
        MovementFrame.Position = UDim2.new(1, 0, 0.5, 0)
        MovementFrame.Size = UDim2.new(1, 0, 1, 0)
        MovementFrame.ZIndex = 9

        Atramenta:Drag(MovementFrame, MainFrame, 0.1)

        SelectionFrame.Position = UDim2.new(1, 5, 0, 28)
        SelectionFrame.Size = UDim2.new(0, 8, 0, 22)

        table.insert(Atramenta.Elements.Highlight, {
            Element = SelectionFrame,
            Property = "BackgroundColor3"
        })

        while true do task.wait(0.01)
            BlurElement.Size = UDim2.new(1, TabFrame.AbsoluteSize.X - 35, 1, 0)
            MovementFrame.Size = UDim2.new(1, TabFrame.AbsoluteSize.X - 35, 1, 0)

            SelectionFrame.BackgroundColor3 = Atramenta.Colors.Highlight

            if WindowArgs.SelectedTab and WindowArgs.IsOpen then
                local vili = -(TabButtons.AbsolutePosition.Y - WindowArgs.SelectedTab.AbsolutePosition.Y) + 4
                local distance = (SelectionFrame.Position.Y.Offset - vili)

                if vili < 0 or vili > TabButtons.AbsoluteSize.Y then
                    Atramenta:_Animation(SelectionFrame, TweenInfo.new(0.1), {
                        BackgroundTransparency = 1
                    })
                else
                    if math.abs(distance) <= 10 then
                        Atramenta:_Animation(SelectionFrame, TweenInfo.new(0.1), {
                            BackgroundTransparency = 0
                        })

                        SelectionFrame.Position = UDim2.new(1, 5, 0, math.ceil(vili))
                    else
                        Atramenta:_Animation(SelectionFrame, TweenInfo.new(0.15), {
                            BackgroundTransparency = 0,
                            Position = UDim2.new(1, 5, 0, math.ceil(vili))
                        })
                    end
                end
            else
                Atramenta:_Animation(SelectionFrame, TweenInfo.new(0.15), {
                    BackgroundTransparency = 1
                })
            end

            if WindowArgs.AlwayShowTab then
                TabHover:Fire(true)
            end
        end
    end)

    WindowArgs:Update()

    local OldDelayThread
    local DurationTime = tick()

    Atramenta:_Hover(TabFrame, function()
        if OldDelayThread then
            task.cancel(OldDelayThread)
            OldDelayThread = nil
        end

        if WindowArgs.AlwayShowTab then
            return
        end

        DurationTime = tick()

        TabHover:Fire(true)
    end, function()
        if OldDelayThread then
            task.cancel(OldDelayThread)
            OldDelayThread = nil
        end

        if WindowArgs.AlwayShowTab then
            return
        end

        OldDelayThread = task.delay(math.clamp((tick() - DurationTime), 0.01, 5), function()
            if TabHover:GetValue() then
                TabHover:Fire(false)
            end
        end)
    end)

    return WindowArgs
end

function Atramenta:GetDate(Time)
    Time = Time or tick()

    local val = os.date('*t',Time)

    return string.format("%s/%s/%s",val.day,val.month,val.year)
end

function Atramenta:GetTimeNow(Time)
    Time = Time or tick()

    local val = os.date('*t',Time)

    return string.format("%s:%s:%s",val.hour,val.min,val.sec)
end

function Atramenta:GetConfig(Type: string)
    local ConfigFlags = {}

    for i, v in next, Atramenta.Flags do
        local Value = v:GetValue()
        local Suf = {}

        if typeof(Value) == "table" and Value.ColorPicker and typeof(Value.ColorPicker) == 'table' then
            Suf.Color3 = {
                R = Value.ColorPicker.Color.R,
                G = Value.ColorPicker.Color.G,
                B = Value.ColorPicker.Color.B
            }

            Suf.Transparency = Value.ColorPicker.Transparency

            Suf.Type = "ColorPicker"
        else
            Suf.Value = Value
            Suf.Type = "NormalElement"
        end

        if Type == "KV" then
            ConfigFlags[v.Flag] = {
                Flag = v.Flag,
                Value = Suf,
                Functions = v,
                AutoKeybind = (v.AutoKeybind and v.AutoKeybind:GetSettings())
            }
        elseif Type == "MK" then
            ConfigFlags[v.Flag] = {
                Flag = v.Flag,
                Value = Suf,
                AutoKeybind = (v.AutoKeybind and v.AutoKeybind:GetSettings())
            }
        else
            table.insert(ConfigFlags, {
                Flag = v.Flag,
                Value = Suf,
                AutoKeybind = (v.AutoKeybind and v.AutoKeybind:GetSettings())
            })
        end
    end

    return ConfigFlags
end

function Atramenta:_Path(...)
    local args = {...}

    return table.concat(args, "/")
end

function Atramenta:ConfigManager(ConfigManager: ConfigManager): ConfigFunctions
    ConfigManager = Atramenta.__CONFIG(ConfigManager, {
        Directory = "Atramenta",
        Config = "Software"
    })

    if not isfolder(ConfigManager.Directory) then
        makefolder(ConfigManager.Directory)
    end

    if not isfolder(Atramenta:_Path(ConfigManager.Directory, ConfigManager.Config)) then
        makefolder(Atramenta:_Path(ConfigManager.Directory, ConfigManager.Config))
    end

    local Args = {
        Directory = Atramenta:_Path(ConfigManager.Directory, ConfigManager.Config)
        EnableNotify = false,
    }

    local notify = Atramenta.newNotify()

    function Args:WriteConfig(Config: WriteConfig)
        Config = Atramenta.__CONFIG(Config, {
            Name = Atramenta:_RandomString(),
            Author = LocalPlayer.Name,
        })

        local Flags = Atramenta:GetConfig("MK")

        Flags["__INFORMATION"] = {
            Type = "Information",
            Author = Config.Author,
            Name = Config.Name,
            CreatedDate = Atramenta:GetDate()
        }

        if Args.EnableNotify then
            notify.new({
                Title = "Configs",
                Icon = Atramenta:_GetIcon('settings'),
                Content = "Create config \""..Config.Name.."\""
            })
        end

        writefile(Atramenta:_Path(Args.Directory, Config.Name), HttpService:JSONEncode(Flags))
    end

    function Args:LoadConfigFromString(str: string)
        local decoded = HttpService:JSONDecode(str)

        local Flags = Atramenta:GetConfig("KV")

        for i, v in next, decoded do
            if v and v.Flag then

                local Value = Flags[v.Flag]

                if Value then

                    if v.Value.Type == "NormalElement" then
                        Value.Functions:SetValue(v.Value.Value)

                    elseif v.Value.Type == "ColorPicker" then

                        local Color = Color3.new(v.Value.Color3.R, v.Value.Color3.G, v.Value.Color3.B)

                        local Transparency = v.Value.Transparency

                        Value.Functions:SetValue(Color, Transparency)
                    end
                end
            end
        end
    end

    function Args:GetCurrentConfig()
        return Atramenta:GetConfig("MK")
    end

    function Args:ReadInfo(ConfigName: string)
        local _path = Atramenta:_Path(Args.Directory, ConfigName)

        if isfile(_path) then
            local info = readfile(_path)

            local decoded = HttpService:JSONDecode(info)

            return decoded.__INFORMATION
        end

        return false
    end

    function Args:GetConfigs()
        local names = {}

        for i, v in next, listfiles(Args.Directory) do
            local Name = string.sub(v, #Args.Directory + 2)

            table.insert(names, Name)
        end

        return names
    end

    function Args:GetFullConfigs()
        local names = {}

        for i, v in next, listfiles(Args.Directory) do
            local Name = string.sub(v, #Args.Directory + 2)
            local Info = Args:ReadInfo(Name)

            table.insert(names, {
                Name = Name,
                Info = Info,
            })
        end

        return names
    end

    function Args:DeleteConfig(ConfigName)
        local _path = Atramenta:_Path(Args.Directory, ConfigName)

        if Args.EnableNotify then
            notify.new({
                Title = "Configs",
                Icon = Atramenta:_GetIcon('settings'),
                Content = "Delete config \""..ConfigName.."\""
            })
        end

        if isfile(_path) then
            delfile(_path)
        end
    end

    function Args:GetConfigCount()
        return #listfiles(Args.Directory)
    end

    function Args:LoadConfig(ConfigName: string)
        local _path = Atramenta:_Path(Args.Directory, ConfigName)

        if isfile(_path) then
            local info = readfile(_path)

            local decoded = HttpService:JSONDecode(info)

            local Flags = Atramenta:GetConfig("KV")

            if Args.EnableNotify then
                notify.new({
                    Title = "Configs",
                    Icon = Atramenta:_GetIcon('settings'),
                    Content = "Load config \""..ConfigName.."\""
                })
            end

            for i, v in next, decoded do
                if v and v.Flag then

                    local Value = Flags[v.Flag]

                    if Value then

                        if v.Value.Type == "NormalElement" then
                            Value.Functions:SetValue(v.Value.Value)

                        elseif v.Value.Type == "ColorPicker" then

                            local Color = Color3.new(v.Value.Color3.R, v.Value.Color3.G, v.Value.Color3.B)

                            local Transparency = v.Value.Transparency

                            Value.Functions:SetValue(Color, Transparency)
                        end

                        if Value.Functions.AutoKeybind then
                            if v.AutoKeybind then
                                Value.Functions.AutoKeybind:LoadSettings(v.AutoKeybind)
                            end
                        end
                    end
                end
            end
        end
    end

    return Args
end

function Atramenta:Loader(IconId, Duration)
    local AtramentaGui = Instance.new("ScreenGui")

    AtramentaGui.Name = Atramenta:_RandomString()
    AtramentaGui.Parent = CoreGui
    AtramentaGui.Enabled = true
    AtramentaGui.ResetOnSpawn = false
    AtramentaGui.IgnoreGuiInset = true
    AtramentaGui.ZIndexBehavior = Enum.ZIndexBehavior.Global

    local Loader = Instance.new("Frame")
    local Icon = Instance.new("ImageLabel")
    local Vignette = Instance.new("ImageLabel")

    Loader.Name = Atramenta:_RandomString()
    Loader.Parent = AtramentaGui
    Loader.AnchorPoint = Vector2.new(0.5, 0.5)
    Loader.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    Loader.BackgroundTransparency = 1
    Loader.BorderColor3 = Color3.fromRGB(0, 0, 0)
    Loader.BorderSizePixel = 0
    Loader.Position = UDim2.new(0.5, 0, 0.5, 0)
    Loader.Size = UDim2.new(1, 0, 1, 0)

    Icon.Name = Atramenta:_RandomString()
    Icon.Parent = Loader
    Icon.AnchorPoint = Vector2.new(0.5, 0.5)
    Icon.BackgroundTransparency = 1.000
    Icon.BorderColor3 = Color3.fromRGB(0, 0, 0)
    Icon.BorderSizePixel = 0
    Icon.Position = UDim2.new(0.5, 0, 0.5, 0)
    Icon.Size = UDim2.new(0, 750, 0, 750)
    Icon.ZIndex = 100
    Icon.Image = IconId or Atramenta.Logo
    Icon.ImageTransparency = 1

    Vignette.Name = Atramenta:_RandomString()
    Vignette.Parent = Loader
    Vignette.BackgroundTransparency = 1.000
    Vignette.BorderColor3 = Color3.fromRGB(27, 42, 53)
    Vignette.BorderSizePixel = 0
    Vignette.Size = UDim2.new(1, 0, 1, 0)
    Vignette.Image = Atramenta:CacheImage("rbxassetid://18720640102")
    Vignette.ImageColor3 = Atramenta.Colors.Highlight
    Vignette.ImageTransparency = 1
    Vignette.AnchorPoint = Vector2.new(0.5, 0.5)
    Vignette.Position = UDim2.fromScale(0.5, 0.5)

    Atramenta:_Animation(Loader, TweenInfo.new(0.55, Enum.EasingStyle.Quint), {
        BackgroundTransparency = 0.5
    })

    local Event = Instance.new('BindableEvent')

    task.delay(0.5, function()
        Atramenta:_Animation(Icon, TweenInfo.new(0.75, Enum.EasingStyle.Quint), {
            ImageTransparency = 0.01,
            Size = UDim2.new(0, 200, 0, 200)
        })

        task.delay(0.25, function()
            Atramenta:_Animation(Vignette, TweenInfo.new(5), {
                ImageTransparency = 0.2
            })

            task.wait(Duration or 4.5)

            Atramenta:_Animation(Vignette, TweenInfo.new(3, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut), {
                Size = UDim2.new(2, 0, 2, 0)
            })

            Atramenta:_Animation(Icon, TweenInfo.new(0.75, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut), {
                ImageTransparency = 1,
            })

            Atramenta:_Animation(Loader, TweenInfo.new(1.5, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut), {
                BackgroundTransparency = 1
            })

            task.delay(0.1, function()
                Atramenta:_Animation(Vignette, TweenInfo.new(1, Enum.EasingStyle.Quint, Enum.EasingDirection.InOut), {
                    ImageTransparency = 1
                })

                task.wait(0.2)

                task.delay(3, function()
                    AtramentaGui:Destroy()
                end)
            end)

            task.delay(0.6, function()
                Event:Fire()
            end)
        end)
    end)

    return {
        yield = function()
            return Event.Event:Wait()
        end
    }
end

function Atramenta.newNotify()
    if Atramenta.NOTIFY_CACHE then
        return Atramenta.NOTIFY_CACHE
    end

    local Notification = Instance.new("ScreenGui")
    local NotifyContainer = Instance.new("Frame")
    local UIListLayout = Instance.new("UIListLayout")

    Notification.Name = Atramenta:_RandomString()
    Notification.Parent = CoreGui
    Notification.ResetOnSpawn = false
    Notification.ZIndexBehavior = Enum.ZIndexBehavior.Global

    NotifyContainer.Name = Atramenta:_RandomString()
    NotifyContainer.Parent = Notification
    NotifyContainer.AnchorPoint = Vector2.new(1, 0)
    NotifyContainer.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    NotifyContainer.BackgroundTransparency = 1.000
    NotifyContainer.BorderColor3 = Color3.fromRGB(0, 0, 0)
    NotifyContainer.BorderSizePixel = 0
    NotifyContainer.Position = UDim2.new(1, -10, 0, 1)
    NotifyContainer.Size = UDim2.new(0, 100, 0, 100)

    UIListLayout.Parent = NotifyContainer
    UIListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
    UIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
    UIListLayout.Padding = UDim.new(0, 3)

    local LayoutREF = 0

    Atramenta.NOTIFY_CACHE = {
        new = function(Notify: Notify): NotifyPayback
            Notify = Atramenta.__CONFIG(Notify, {
                Icon = Atramenta.Logo,
                Title = "Notification",
                Content = "Content",
                Duration = 3,
            })

            LayoutREF -= 5

            local BlockFrame = Instance.new("Frame")
            local NotifyFrame = Instance.new("Frame")
            local UICorner = Instance.new("UICorner")
            local CompLogo = Instance.new("ImageLabel")
            local Header = Instance.new("TextLabel")
            local Body = Instance.new("TextLabel")
            local TimeLeftFrame = Instance.new("Frame")
            local UICorner_2 = Instance.new("UICorner")
            local TimeLeft = Instance.new("Frame")
            local UICorner_3 = Instance.new("UICorner")

            BlockFrame.Name = Atramenta:_RandomString()
            BlockFrame.Parent = NotifyContainer
            BlockFrame.AnchorPoint = Vector2.new(1, 0)
            BlockFrame.BackgroundColor3 = Atramenta.Colors.BGDBColor
            BlockFrame.BackgroundTransparency = 1.000
            BlockFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
            BlockFrame.BorderSizePixel = 0
            BlockFrame.ClipsDescendants = false
            BlockFrame.Size = UDim2.new(0, 200, 0, 0)
            BlockFrame.LayoutOrder = LayoutREF

            NotifyFrame.Name = Atramenta:_RandomString()
            NotifyFrame.Parent = BlockFrame
            NotifyFrame.BackgroundColor3 = Atramenta.Colors.BGDBColor
            NotifyFrame.BackgroundTransparency = 0.100
            NotifyFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
            NotifyFrame.BorderSizePixel = 0
            NotifyFrame.ClipsDescendants = false
            NotifyFrame.Size = UDim2.new(1, 0, 1, -5)
            NotifyFrame.ZIndex = 2
            NotifyFrame.Position = UDim2.new(1, 200, 0, 0)

            UICorner.CornerRadius = UDim.new(0, 4)
            UICorner.Parent = NotifyFrame

            CompLogo.Name = Atramenta:_RandomString()
            CompLogo.Parent = NotifyFrame
            CompLogo.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            CompLogo.BackgroundTransparency = 1.000
            CompLogo.BorderColor3 = Color3.fromRGB(0, 0, 0)
            CompLogo.BorderSizePixel = 0
            CompLogo.Position = UDim2.new(0, 6, 0, 6)
            CompLogo.Size = UDim2.new(0, 25, 0, 25)
            CompLogo.ZIndex = 4

            if string.find(Notify.Icon,'cache-ck-',1,true) then
                CompLogo.Image = Notify.Icon
            else
                CompLogo.Image = Atramenta:_GetIcon(Notify.Icon)
            end

            if Atramenta.CustomHighlightMode then
                CompLogo.ImageColor3 = Atramenta.Colors.Highlight
            end

            Header.Name = Atramenta:_RandomString()
            Header.Parent = NotifyFrame
            Header.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Header.BackgroundTransparency = 1.000
            Header.BorderColor3 = Color3.fromRGB(0, 0, 0)
            Header.BorderSizePixel = 0
            Header.Position = UDim2.new(0, 40, 0, 10)
            Header.Size = UDim2.new(1, -50, 0, 15)
            Header.ZIndex = 3
            Header.Font = Enum.Font.GothamBold
            Header.Text = Notify.Title
            Header.TextColor3 = Atramenta.Colors.SwitchColor
            Header.TextSize = 14.000
            Header.TextXAlignment = Enum.TextXAlignment.Left

            Body.Name = Atramenta:_RandomString()
            Body.Parent = NotifyFrame
            Body.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Body.BackgroundTransparency = 1.000
            Body.BorderColor3 = Color3.fromRGB(0, 0, 0)
            Body.BorderSizePixel = 0
            Body.Position = UDim2.new(0, 10, 0, 33)
            Body.Size = UDim2.new(1, -15, 0, 30)
            Body.ZIndex = 3
            Body.Font = Enum.Font.GothamMedium
            Body.Text = Notify.Content
            Body.TextColor3 = Atramenta.Colors.SwitchColor
            Body.TextSize = 12.000
            Body.TextTransparency = 0.500
            Body.TextXAlignment = Enum.TextXAlignment.Left
            Body.TextYAlignment = Enum.TextYAlignment.Top

            TimeLeftFrame.Name = Atramenta:_RandomString()
            TimeLeftFrame.Parent = NotifyFrame
            TimeLeftFrame.AnchorPoint = Vector2.new(0, 1)
            TimeLeftFrame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            TimeLeftFrame.BackgroundTransparency = 1.000
            TimeLeftFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
            TimeLeftFrame.BorderSizePixel = 0
            TimeLeftFrame.Position = UDim2.new(0, 0, 1, 1)
            TimeLeftFrame.Size = UDim2.new(1, 0, 0, 5)
            TimeLeftFrame.ZIndex = 5

            UICorner_2.CornerRadius = UDim.new(0, 4)
            UICorner_2.Parent = TimeLeftFrame

            TimeLeft.Name = Atramenta:_RandomString()
            TimeLeft.Parent = TimeLeftFrame
            TimeLeft.BackgroundColor3 = Atramenta.Colors.Highlight
            TimeLeft.BorderColor3 = Color3.fromRGB(0, 0, 0)
            TimeLeft.BorderSizePixel = 0
            TimeLeft.Size = UDim2.new(0, 0, 1, 0)
            TimeLeft.ZIndex = 5

            UICorner_3.CornerRadius = UDim.new(0, 1)
            UICorner_3.Parent = TimeLeft

            local UpdateText = function()
                local TitleScale = TextService:GetTextSize(Header.Text, Header.TextSize, Header.Font, Vector2.new(math.huge, math.huge))
                local BodyScale = TextService:GetTextSize(Body.Text, Body.TextSize, Body.Font, Vector2.new(math.huge, math.huge))

                local MainX = (TitleScale.X >= BodyScale.X and TitleScale.X) or BodyScale.X
                local MainY = TitleScale.Y + ((Body.Text:byte() and BodyScale.Y) or 1)

                if BlockFrame:GetAttribute('Already') then
                    Atramenta:_Animation(BlockFrame, TweenInfo.new(0.3), {
                        Size = UDim2.new(0, MainX + 55, 0, MainY + 35)
                    })
                else
                    BlockFrame:SetAttribute('Already',true)
                    BlockFrame.Size = UDim2.new(0, MainX + 45, 0, 0)

                    Atramenta:_Animation(BlockFrame, TweenInfo.new(0.3), {
                        Size = UDim2.new(0, MainX + 55, 0, MainY + 35)
                    })
                end
            end

            UpdateText()

            local Close = function()
                Atramenta:_Animation(NotifyFrame, TweenInfo.new(0.65, Enum.EasingStyle.Quint), {
                    Position = UDim2.new(1, 200, 0, 0)
                })

                task.wait(0.3)

                Atramenta:_Animation(BlockFrame, TweenInfo.new(0.3), {
                    Size = UDim2.new(1, 0, 0, 0)
                })

                task.wait(0.35)
                BlockFrame:Destroy()

            end

            local Show = function()
                Atramenta:_Animation(NotifyFrame, TweenInfo.new(0.5, Enum.EasingStyle.Quint), {
                    Position = UDim2.new(0, 0, 0, 0)
                })
            end

            if typeof(Notify.Duration) == 'number' and Notify.Duration ~= math.huge then
                Atramenta:_Animation(TimeLeft, TweenInfo.new(Notify.Duration + 0.2, Enum.EasingStyle.Linear), {
                    Size = UDim2.new(1, 0, 1, 0)
                })

                return task.delay(0.25, function()
                    Show()

                    task.delay(Notify.Duration + 0.2, Close)
                end)
            end

            Show()

            return {
                Title = function(self, new)
                    Header.Text = new
                    UpdateText()
                end,

                Content = function(self, new)
                    Body.Text = new
                    UpdateText()
                end,

                SetProgress = function(self, new, Time)
                    if Time and Time <= 0 then
                        TimeLeft.Size = UDim2.new(new, 0, 1, 0)

                        UpdateText()
                        return
                    end

                    if new > 1 then
                        new = (new / 100)
                    end

                    Atramenta:_Animation(TimeLeft, TweenInfo.new(Time or 0.85, (Time and Enum.EasingStyle.Linear) or Enum.EasingStyle.Quint), {
                        Size = UDim2.new(new, 0, 1, 0)
                    })

                    UpdateText()
                end,

                Close = Close,
            }
        end,
    }

    return Atramenta.NOTIFY_CACHE
end

Atramenta.NilFolder.Name = "Nil-Instances"

local Runtime
local Library = {
    Flags = {},
    Setters = {},
    Folders = {
        Root = "Atramenta.rip",
        Configs = "Atramenta.rip/Configs",
        Assets = "Atramenta.rip/Assets"
    }
}

function Library.Call(Function, ...)
    if type(Function) ~= "function" then return false, nil end

    local Arguments = table.pack(...)
    local Results = table.pack(xpcall(function()
        return Function(table.unpack(Arguments, 1, Arguments.n))
    end, function(Error)
        return tostring(Error)
    end))

    if Results[1] ~= true then
        return false, Results[2]
    end

    return true, table.unpack(Results, 2, Results.n)
end

local function BuildRuntime()
    local TweenService = game:GetService("TweenService")
    local UserInputService = game:GetService("UserInputService")
    local RunService = game:GetService("RunService")
    local HttpService = game:GetService("HttpService")
    local CoreGui = game:GetService("CoreGui")
    local Players = game:GetService("Players")
    local LocalizationService = game:GetService("LocalizationService")

    if type(makefolder) == "function" then
        Library.Call(makefolder, Library.Folders.Root)
        Library.Call(makefolder, Library.Folders.Configs)
        Library.Call(makefolder, Library.Folders.Assets)
    end

    local IconAsset, RifleAsset, LogoAsset
    do
    local Base64Data = ""
    local RifleBase64Data = ""
    local LogoBase64Data = ""
    local Base64Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

    local function DecodeBase64(Data)
        Data = Data:gsub("[^" .. Base64Alphabet .. "=]", "")
        return (Data:gsub(".", function(Character)
            if Character == "=" then
                return ""
            end
            local Value = Base64Alphabet:find(Character, 1, true) - 1
            local Bits = ""
            for Index = 6, 1, -1 do
                Bits ..= Value % 2 ^ Index - Value % 2 ^ (Index - 1) > 0 and "1" or "0"
            end
            return Bits
        end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(Bits)
            if #Bits ~= 8 then
                return ""
            end
            local Value = 0
            for Index = 1, 8 do
                if Bits:sub(Index, Index) == "1" then
                    Value += 2 ^ (8 - Index)
                end
            end
            return string.char(Value)
        end))
    end

    local function ResolveIconAsset()
        local CustomAsset = getcustomasset or getsynasset
        if type(writefile) ~= "function" or type(CustomAsset) ~= "function" then
            return nil
        end
        local FileName = Library.Folders.Assets .. "/AtramentaIcons.png"
        local Exists = type(isfile) == "function" and isfile(FileName)
        if not Exists then
            writefile(FileName, DecodeBase64(Base64Data))
        end
        local Success, Asset = Library.Call(CustomAsset, FileName)
        if Success then
            return Asset
        end
        return nil
    end

    local function ResolveRifleAsset()
        local CustomAsset = getcustomasset or getsynasset
        if type(writefile) ~= "function" or type(CustomAsset) ~= "function" then
            return nil
        end
        local FileName = Library.Folders.Assets .. "/AtramentaCombatIcon.png"
        local Exists = type(isfile) == "function" and isfile(FileName)
        if not Exists then
            Library.Call(writefile, FileName, DecodeBase64(RifleBase64Data))
        end
        local Success, Asset = Library.Call(CustomAsset, FileName)
        if Success then
            return Asset
        end
        return nil
    end

    local function ResolveLogoAsset()
        local CustomAsset = getcustomasset or getsynasset
        if type(writefile) ~= "function" or type(CustomAsset) ~= "function" then
            return nil
        end
        local FileName = Library.Folders.Assets .. "/AtramentaLogo.png"
        local Exists = type(isfile) == "function" and isfile(FileName)
        if not Exists then
            Library.Call(writefile, FileName, DecodeBase64(LogoBase64Data))
        end
        local Success, Asset = Library.Call(CustomAsset, FileName)
        if Success then
            return Asset
        end
        return nil
    end

        IconAsset = ResolveIconAsset()
        RifleAsset = ResolveRifleAsset()
        LogoAsset = ResolveLogoAsset()
    end
    local IconIndexes = {
        Lightning = 0,
        Rifle = 1,
        Pistol = 1,
        Shield = 2,
        Gear = 3,
        Minus = 4,
        Target = 5,
        Cloud = 6,
        Search = 7,
        Warning = 8,
        Check = 9,
        Chevron = 10,
        User = 11,
        Eye = 12,
        Run = 13,
        Globe = 14,
        Wrench = 15,
        Sliders = 16,
        Boxes = 17
    }

    local DefaultAccent = Color3.fromRGB(86, 66, 235)
    local Accent = DefaultAccent
    local Background = Color3.fromRGB(10, 10, 12)
    local SidebarColor = Color3.fromRGB(14, 14, 17)
    local Surface = Color3.fromRGB(18, 18, 21)
    local SurfaceAlt = Color3.fromRGB(24, 24, 28)
    local Border = Color3.fromRGB(56, 56, 63)
    local PrimaryText = Color3.fromRGB(228, 228, 232)
    local MutedText = Color3.fromRGB(156, 156, 164)
    local DisabledText = Color3.fromRGB(88, 88, 96)
    local Danger = Color3.fromRGB(202, 72, 78)
    local BaseScaleFactor = 1
    local AnimationFactor = 1

    local Menu = {
        Call = Library.Call,
        Flags = {},
        Setters = {},
        Connections = {},
        Visible = true,
        Pages = {},
        SidebarButtons = {},
        ModeButtons = {},
        Sections = {},
        BindRuntime = {},
        BindSystem = {},
        PlayerStatuses = {},
        PlayerListController = nil,
        QuickPanelController = nil,
        QuickPanelBindCapture = false,
        SettingsUI = {},
        DefaultFlags = {},
        DefaultFlagKnown = {},
        ConfigLoadGeneration = 0,
        ConfigApplying = false,
        LastConfigFlags = {},
        ChromeAccentTargets = setmetatable({}, {__mode = "k"})
    }

    local function CloneFlagValue(Value, Seen)
        if type(Value) ~= "table" then return Value end
        Seen = Seen or {}
        if Seen[Value] then return Seen[Value] end
        local Result = {}
        Seen[Value] = Result
        for Key, Item in pairs(Value) do Result[CloneFlagValue(Key, Seen)] = CloneFlagValue(Item, Seen) end
        return Result
    end

    local function FlagValuesEqual(A, B, Seen)
        if typeof(A) ~= typeof(B) then return false end
        if type(A) ~= "table" then return A == B end
        Seen = Seen or {}
        if Seen[A] == B then return true end
        Seen[A] = B
        for Key, Value in pairs(A) do
            if not FlagValuesEqual(Value, B[Key], Seen) then return false end
        end
        for Key in pairs(B) do
            if A[Key] == nil then return false end
        end
        return true
    end

    setmetatable(Menu.Setters, {
        __newindex = function(Target, Flag, Setter)
            rawset(Target, Flag, Setter)
            if Menu.DefaultFlagKnown[Flag] ~= true then
                Menu.DefaultFlagKnown[Flag] = true
                Menu.DefaultFlags[Flag] = CloneFlagValue(Menu.Flags[Flag])
            end
        end
    })

    do
        local GlowBase64Data = ""
        local CustomAsset = getcustomasset or getsynasset
        if type(writefile) == "function" and type(CustomAsset) == "function" then
            local GlowFileName = Library.Folders.Assets .. "/AtramentaGlow.png"
            local GlowExists = type(isfile) == "function" and isfile(GlowFileName)
            if not GlowExists then
                Library.Call(function()
                    writefile(GlowFileName, DecodeBase64(GlowBase64Data))
                end)
            end
            local Success, Asset = Library.Call(CustomAsset, GlowFileName)
            if Success then
                Menu.GlowAsset = Asset
            end
        end
    end

    local function Create(ClassName, Properties)
        Properties = Properties or {}
        if Properties.BackgroundColor3 and Properties.BackgroundTransparency == nil then
            local Color = Properties.BackgroundColor3
            local Maximum = math.max(Color.R, Color.G, Color.B)
            if Maximum <= 0.18 then
                Properties.BackgroundTransparency = 0.08
            end
        end

        local Object = Instance.new(ClassName)
        for Property, Value in pairs(Properties) do
            Object[Property] = Value
        end

        return Object
    end

    local function Corner(Parent, Radius)
        local Value = tonumber(Radius) or 0
        if Value < 50 then Value = math.min(Value, 4) end
        return Create("UICorner", {
            Parent = Parent,
            CornerRadius = UDim.new(0, Value)
        })
    end

    local function Stroke(Parent, Color, Transparency, Thickness)
        return Create("UIStroke", {
            Parent = Parent,
            Color = Color,
            Transparency = Transparency or 0,
            Thickness = Thickness or 1,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        })
    end

    local function Bind(Connection)
        table.insert(Menu.Connections, Connection)
        return Connection
    end

    local function AddChromeLine(Parent, Position, Size, Color, Transparency, ZIndex, TrackAccent)
        if not Parent then return nil end
        local Line = Create("Frame", {
            Parent = Parent,
            Position = Position,
            Size = Size,
            BackgroundColor3 = Color or Border,
            BackgroundTransparency = Transparency or 0,
            BorderSizePixel = 0,
            ZIndex = ZIndex or ((Parent.ZIndex or 1) + 1)
        })
        if TrackAccent == true then
            Menu.ChromeAccentTargets[Line] = true
        end
        return Line
    end

    local function AddPanelChrome(Parent, Radius, ZIndex)
        if not Parent then return nil end
        local Inner = Create("Frame", {
            Parent = Parent,
            Position = UDim2.fromOffset(1, 1),
            Size = UDim2.new(1, -2, 1, -2),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Active = false,
            ZIndex = ZIndex or ((Parent.ZIndex or 1) + 1)
        })
        Corner(Inner, math.max(0, (tonumber(Radius) or 3) - 1))
        Stroke(Inner, Color3.fromRGB(78, 78, 86), 0.58, 1)
        return Inner
    end

    local function AddPanelGradient(Parent, TopColor, BottomColor)
        if not Parent then return nil end
        return Create("UIGradient", {
            Parent = Parent,
            Rotation = 90,
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, TopColor or Color3.fromRGB(28, 28, 32)),
                ColorSequenceKeypoint.new(1, BottomColor or Color3.fromRGB(16, 16, 19))
            })
        })
    end

    function Menu:AddSoftGlow(Target, ZIndex, Padding, Transparency, UseSlice)
        if not self.GlowAsset or not Target or not Target.Parent then
            return nil
        end

        local Extra = math.min(Padding or 8, 7)
        local GlowTransparency = math.max(Transparency or 0.72, 0.90)
        local Glow = Create("ImageLabel", {
            Parent = Target.Parent,
            AnchorPoint = Target.AnchorPoint,
            Position = Target.Position,
            Size = UDim2.new(Target.Size.X.Scale, Target.Size.X.Offset + Extra * 2, Target.Size.Y.Scale, Target.Size.Y.Offset + Extra * 2),
            BackgroundTransparency = 1,
            Image = self.GlowAsset,
            ImageColor3 = Accent,
            ImageTransparency = GlowTransparency,
            ScaleType = UseSlice == false and Enum.ScaleType.Fit or Enum.ScaleType.Slice,
            SliceCenter = Rect.new(34, 34, 62, 62),
            Visible = Target.Visible,
            ZIndex = (ZIndex or Target.ZIndex) - 1
        })

        local function Sync()
            if not Target.Parent or not Glow.Parent then
                return
            end
            local Anchor = Target.AnchorPoint
            Glow.AnchorPoint = Anchor
            Glow.Position = UDim2.new(
                Target.Position.X.Scale,
                Target.Position.X.Offset + math.floor((Extra * ((Anchor.X * 2) - 1)) + 0.5),
                Target.Position.Y.Scale,
                Target.Position.Y.Offset + math.floor((Extra * ((Anchor.Y * 2) - 1)) + 0.5)
)
            Glow.Size = UDim2.new(Target.Size.X.Scale, Target.Size.X.Offset + Extra * 2, Target.Size.Y.Scale, Target.Size.Y.Offset + Extra * 2)
            Glow.Visible = Target.Visible
        end

        Sync()
        Bind(Target:GetPropertyChangedSignal("Position"):Connect(Sync))
        Bind(Target:GetPropertyChangedSignal("Size"):Connect(Sync))
        Bind(Target:GetPropertyChangedSignal("Visible"):Connect(Sync))
        Bind(Target.AncestryChanged:Connect(function(_, ParentObject)
            if not ParentObject and Glow.Parent then
                Glow:Destroy()
            end
        end))

        return Glow
    end

    local ActiveTweens = setmetatable({}, { __mode = "k" })

    local function Tween(Object, Duration, Properties)
        if not Object or not Object.Parent or type(Properties) ~= "table" then return nil end
        local Previous = ActiveTweens[Object]
        if Previous then Library.Call(function() Previous:Cancel() end) end
        local RequestedDuration = (tonumber(Duration) or 0.08) / math.max(AnimationFactor, 0.05)
        local EffectiveDuration = math.clamp(RequestedDuration, 0.025, 0.075)
        local Animation = TweenService:Create(
            Object,
            TweenInfo.new(EffectiveDuration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            Properties
)
        ActiveTweens[Object] = Animation
        Animation:Play()

        local CompletionConnection
        CompletionConnection = Animation.Completed:Connect(function()
            if CompletionConnection then
                CompletionConnection:Disconnect()
                CompletionConnection = nil
            end
            if ActiveTweens[Object] == Animation then ActiveTweens[Object] = nil end
        end)
        return Animation
    end

    local function SmoothSlider(FrameObject, KnobObject, Alpha, Duration)
        Alpha = math.clamp(Alpha or 0, 0, 1)
        if FrameObject then
            Tween(FrameObject, Duration or 0.12, {Size = UDim2.new(Alpha, 0, 1, 0)})
        end
        if KnobObject then
            Tween(KnobObject, Duration or 0.12, {Position = UDim2.new(Alpha, 0, 0.5, 0)})
        end
    end

    local function CreateFallbackIcon(Parent, Name, Size, Position, Color, ZIndex)
        local Root = Create("Frame", {
            Parent = Parent,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = Position,
            Size = Size,
            BackgroundTransparency = 1,
            ZIndex = ZIndex
        })

        local function Line(PositionValue, SizeValue, Rotation)
            local Object = Create("Frame", {
                Parent = Root,
                Position = PositionValue,
                Size = SizeValue,
                Rotation = Rotation or 0,
                BackgroundColor3 = Color,
                BorderSizePixel = 0,
                ZIndex = ZIndex + 1
            })
            Corner(Object, 3)
            return Object
        end

        if Name == "Minus" then
            Line(UDim2.new(0.18, 0, 0.44, 0), UDim2.new(0.64, 0, 0.12, 0))
        elseif Name == "Target" then
            local Outer = Create("Frame", {
                Parent = Root,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(0.8, 0.8),
                BackgroundTransparency = 1,
                ZIndex = ZIndex + 1
            })
            Corner(Outer, 100)
            Stroke(Outer, Color, 0, 1)
            local Dot = Create("Frame", {
                Parent = Root,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(0.2, 0.2),
                BackgroundColor3 = Color,
                BorderSizePixel = 0,
                ZIndex = ZIndex + 2
            })
            Corner(Dot, 100)
        elseif Name == "Rifle" then
            Line(UDim2.new(0.14, 0, 0.46, 0), UDim2.new(0.46, 0, 0.08, 0), -10)
            Line(UDim2.new(0.54, 0, 0.40, 0), UDim2.new(0.24, 0, 0.05, 0), -10)
            Line(UDim2.new(0.68, 0, 0.33, 0), UDim2.new(0.12, 0, 0.04, 0), -10)
            Line(UDim2.new(0.08, 0, 0.52, 0), UDim2.new(0.20, 0, 0.05, 0), 22)
            Line(UDim2.new(0.22, 0, 0.60, 0), UDim2.new(0.10, 0, 0.16, 0), -58)
            Line(UDim2.new(0.36, 0, 0.50, 0), UDim2.new(0.06, 0, 0.18, 0), 10)
            Line(UDim2.new(0.44, 0, 0.56, 0), UDim2.new(0.10, 0, 0.18, 0), 24)
            Line(UDim2.new(0.34, 0, 0.34, 0), UDim2.new(0.12, 0, 0.04, 0), -10)
        elseif Name == "Gear" then
            local Ring = Create("Frame", {
                Parent = Root,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(0.65, 0.65),
                BackgroundTransparency = 1,
                ZIndex = ZIndex + 1
            })
            Corner(Ring, 100)
            Stroke(Ring, Color, 0, 2)
            for Index = 0, 3 do
                Line(UDim2.new(0.45, 0, 0.05, 0), UDim2.new(0.1, 0, 0.9, 0), Index * 45)
            end
        elseif Name == "Lightning" then
            Line(UDim2.new(0.42, 0, 0.02, 0), UDim2.new(0.2, 0, 0.55, 0), 18)
            Line(UDim2.new(0.25, 0, 0.39, 0), UDim2.new(0.5, 0, 0.18, 0), -18)
            Line(UDim2.new(0.40, 0, 0.43, 0), UDim2.new(0.2, 0, 0.55, 0), 18)
        else
            local Box = Create("Frame", {
                Parent = Root,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(0.55, 0.55),
                BackgroundTransparency = 1,
                ZIndex = ZIndex + 1
            })
            Corner(Box, 2)
            Stroke(Box, Color, 0, 1)
        end

        return Root
    end

    local function Icon(Parent, Name, Size, Position, Color, ZIndex)
        if Name == "Rifle" and RifleAsset then
            return Create("ImageLabel", {
                Parent = Parent,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = Position,
                Size = Size,
                BackgroundTransparency = 1,
                Image = RifleAsset,
                ImageColor3 = Color,
                ScaleType = Enum.ScaleType.Fit,
                ZIndex = ZIndex
            })
        end
        if Name == "Rifle" or not IconAsset then
            return CreateFallbackIcon(Parent, Name, Size, Position, Color, ZIndex)
        end
        return Create("ImageLabel", {
            Parent = Parent,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = Position,
            Size = Size,
            BackgroundTransparency = 1,
            Image = IconAsset,
            ImageRectOffset = Vector2.new(IconIndexes[Name] * 32, 0),
            ImageRectSize = Vector2.new(32, 32),
            ImageColor3 = Color,
            ScaleType = Enum.ScaleType.Fit,
            ZIndex = ZIndex
        })
    end

    function Menu:SetIconColor(Object, Color, Duration)
        if not Object then
            return
        end
        local Objects = {Object}
        for _, Descendant in ipairs(Object:GetDescendants()) do
            table.insert(Objects, Descendant)
        end
        for _, Item in ipairs(Objects) do
            if Item:IsA("ImageLabel") or Item:IsA("ImageButton") then
                if Duration then
                    Tween(Item, Duration, {ImageColor3 = Color})
                else
                    Item.ImageColor3 = Color
                end
            elseif Item:IsA("TextLabel") or Item:IsA("TextButton") then
                if Duration then
                    Tween(Item, Duration, {TextColor3 = Color})
                else
                    Item.TextColor3 = Color
                end
            elseif Item:IsA("Frame") and Item.BackgroundTransparency < 1 then
                if Duration then
                    Tween(Item, Duration, {BackgroundColor3 = Color})
                else
                    Item.BackgroundColor3 = Color
                end
            elseif Item:IsA("UIStroke") then
                if Duration then
                    Tween(Item, Duration, {Color = Color})
                else
                    Item.Color = Color
                end
            end
        end
    end

