    Menu.BindSystem.CanonicalBindKey = function(KeyType, KeyName)
        KeyType = tostring(
            KeyType or ""
)

        KeyName = tostring(
            KeyName or ""
)

        local Canonical =
            BindKeyCanonical[
                KeyName
            ]
            or KeyName

        if string.match(
            Canonical,
            "^MouseButton%d+$"
)
        then
            return "UserInputType",
                Canonical
        end

        return KeyType,
            Canonical
    end

    do
    local function GetControlBinds(ControlFlag)
        SavedPositions.ControlBinds = SavedPositions.ControlBinds or {}

        local TargetFlag = tostring(ControlFlag or "Unknown")
        local Binds = SavedPositions.ControlBinds[TargetFlag]
        if type(Binds) ~= "table" then
            Binds = {}
            SavedPositions.ControlBinds[TargetFlag] = Binds
        end

        local Seen = {}
        for Index = #Binds, 1, -1 do
            local BindData = Binds[Index]

            if type(BindData) ~= "table"
                or type(BindData.KeyType) ~= "string"
                or type(BindData.Key) ~= "string"
                or (BindData.KeyType == "UserInputType" and BindData.Key == "MouseButton1") then
                table.remove(Binds, Index)
            else
                local CanonicalType,
                    CanonicalKey =
                    Menu.BindSystem.CanonicalBindKey(
                        BindData.KeyType,
                        BindData.Key
)

                BindData.KeyType =
                    CanonicalType

                BindData.Key =
                    CanonicalKey

                BindData.Id = type(BindData.Id) == "string"
                    and BindData.Id
                    or (tostring(os.clock()) .. tostring(math.random(1000, 9999)))
                BindData.Mode = BindData.Mode == "Hold" and "Hold" or "Toggle"
                BindData.ShowInBinds = BindData.ShowInBinds ~= false
                BindData.Modifiers = type(BindData.Modifiers) == "table"
                    and BindData.Modifiers
                    or {Ctrl = false, Shift = false, Alt = false}

                if BindData.Mode == "Hold" then
                    local GateFlag = BindData.GateFlag or BindData.EnabledFlag
                    BindData.GateFlag = type(GateFlag) == "string" and GateFlag ~= "" and GateFlag or nil
                else
                    BindData.GateFlag = nil
                end

                BindData.EnabledFlag = nil
                BindData.ControlType = nil
                BindData.Value = nil
                BindData.BaseValue = nil

                local Signature = table.concat({
                    BindData.KeyType,
                    BindData.Key,
                    BindData.Modifiers.Ctrl and "1" or "0",
                    BindData.Modifiers.Shift and "1" or "0",
                    BindData.Modifiers.Alt and "1" or "0"
                }, ":")

                if Seen[Signature] then
                    table.remove(Binds, Index)
                else
                    Seen[Signature] = true
                end
            end
        end

        return Binds, TargetFlag
    end

    local function ApplyFlagValue(Flag, Value)
        Flag = tostring(Flag or "Unknown")
        local Setter = Menu.Setters[Flag]

        if Setter then
            Setter(Value)
        else
            Menu.Flags[Flag] = Value
            if Menu.BindSystem.NotifyFlagChanged then
                Menu.BindSystem.NotifyFlagChanged(Flag, Value)
            end
        end
    end

    local function IsModifierKey(KeyCode)
        return KeyCode == Enum.KeyCode.LeftControl
            or KeyCode == Enum.KeyCode.RightControl
            or KeyCode == Enum.KeyCode.LeftShift
            or KeyCode == Enum.KeyCode.RightShift
            or KeyCode == Enum.KeyCode.LeftAlt
            or KeyCode == Enum.KeyCode.RightAlt
    end

    local function ReadModifiers()
        return {
            Ctrl = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl),
            Shift = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift),
            Alt = UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt) or UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)
        }
    end

    local BindKeyAliases = {
        MouseButton2 = "RMB",
        MouseButton3 = "MMB",
        MouseButton4 = "M4",
        MouseButton5 = "M5",
        MouseButton6 = "M6",
        MouseButton7 = "M7",
        MouseButton8 = "M8",
        KeypadZero = "NUM0",
        KeypadOne = "NUM1",
        KeypadTwo = "NUM2",
        KeypadThree = "NUM3",
        KeypadFour = "NUM4",
        KeypadFive = "NUM5",
        KeypadSix = "NUM6",
        KeypadSeven = "NUM7",
        KeypadEight = "NUM8",
        KeypadNine = "NUM9",
        KeypadPeriod = "NUM.",
        KeypadDivide = "NUM/",
        KeypadMultiply = "NUM*",
        KeypadMinus = "NUM-",
        KeypadPlus = "NUM+",
        KeypadEnter = "NUMENTER",
        KeypadEquals = "NUM=",
        Return = "ENTER",
        Escape = "ESC",
        Backspace = "BACK",
        Delete = "DEL",
        Insert = "INS",
        PageUp = "PGUP",
        PageDown = "PGDN",
        Home = "HOME",
        End = "END",
        CapsLock = "CAPS",
        Space = "SPACE",
        Tab = "TAB",
        Up = "UP",
        Down = "DOWN",
        Left = "LEFT",
        Right = "RIGHT",
        Minus = "-",
        Equals = "=",
        LeftBracket = "[",
        RightBracket = "]",
        BackSlash = "\\",
        Semicolon = ";",
        Quote = "'",
        Comma = ",",
        Period = ".",
        Slash = "/",
        Backquote = "`"
    }

    local function FriendlyKeyName(Name)
        local Raw =
            tostring(
                Name or "Unknown"
)

        local Canonical =
            BindKeyCanonical[Raw]
            or Raw

        local Alias =
            BindKeyAliases[Canonical]

        if Alias then
            return Alias
        end

        local Result =
            Canonical:
                gsub(
                    "(%l)(%u)",
                    "%1 %2"
)

        return string.upper(
            Result
)
    end

    local function BuildBindDisplay(KeyName, Modifiers)
        local Parts = {}

        if Modifiers
            and Modifiers.Ctrl
        then
            table.insert(
                Parts,
                "CTRL"
)
        end

        if Modifiers
            and Modifiers.Shift
        then
            table.insert(
                Parts,
                "SHIFT"
)
        end

        if Modifiers
            and Modifiers.Alt
        then
            table.insert(
                Parts,
                "ALT"
)
        end

        table.insert(
            Parts,
            FriendlyKeyName(
                KeyName
)
)

        return table.concat(
            Parts,
            " + "
)
    end

    local function GetInputIdentity(Input)
        if not Input then
            return nil, nil
        end

        local InputType =
            Input.UserInputType

        local InputTypeName =
            InputType
            and InputType.Name
            or ""

        local KeyCode =
            Input.KeyCode

        local KeyCodeName =
            KeyCode
            and KeyCode.Name
            or ""

        if type(InputTypeName) == "string"
            and string.match(
                InputTypeName,
                "^MouseButton%d+$"
)
        then
            if InputTypeName
                == "MouseButton1"
            then
                return nil, nil
            end

            return Menu.BindSystem.CanonicalBindKey(
                "UserInputType",
                InputTypeName
)
        end

        if type(KeyCodeName) == "string"
            and KeyCodeName ~= ""
            and KeyCodeName ~= "Unknown"
        then
            local CanonicalType,
                CanonicalName =
                Menu.BindSystem.CanonicalBindKey(
                    "KeyCode",
                    KeyCodeName
)

            if CanonicalName
                == "MouseButton1"
            then
                return nil, nil
            end

            return CanonicalType,
                CanonicalName
        end

        if type(InputTypeName) == "string"
            and InputTypeName ~= ""
            and InputTypeName ~= "Keyboard"
            and InputTypeName ~= "MouseMovement"
            and InputTypeName ~= "MouseWheel"
            and InputTypeName ~= "Touch"
            and InputTypeName ~= "None"
        then
            local CanonicalType,
                CanonicalName =
                Menu.BindSystem.CanonicalBindKey(
                    "UserInputType",
                    InputTypeName
)

            if CanonicalName
                ~= InputTypeName
                or string.match(
                    CanonicalName,
                    "^MouseButton%d+$"
)
            then
                return CanonicalType,
                    CanonicalName
            end
        end

        return nil, nil
    end

    local function ModifiersEqual(Expected)
        Expected = Expected or {}
        local Current = ReadModifiers()
        return Current.Ctrl == (Expected.Ctrl == true)
            and Current.Shift == (Expected.Shift == true)
            and Current.Alt == (Expected.Alt == true)
    end

    local function BindMatchesInput(BindData, Input, CheckModifiers)
        if type(BindData) ~= "table" then
            return false
        end

        local KeyType,
            KeyName =
            GetInputIdentity(
                Input
)

        if not KeyType
            or not KeyName
        then
            return false
        end

        local StoredType,
            StoredName =
            Menu.BindSystem.CanonicalBindKey(
                BindData.KeyType,
                BindData.Key
)

        if StoredType ~= KeyType
            or StoredName ~= KeyName
        then
            return false
        end

        if CheckModifiers == false then
            return true
        end

        return ModifiersEqual(
            BindData.Modifiers
)
    end

    local function FormatBindLabel(BindData)
        local Display = BuildBindDisplay(BindData.Key, BindData.Modifiers)
        BindData.Display = Display
        return Display .. "   |   " .. tostring(BindData.Mode or "Toggle")
    end

    local function AddPopupShadow(Target, ZIndex)
        return Menu:AddSoftGlow(Target, ZIndex, 9, 0.64, true)
    end

    local function RectsOverlap(A, B)
        if not A or not B or not A.Parent or not B.Parent then
            return false
        end
        local AP, AS = A.AbsolutePosition, A.AbsoluteSize
        local BP, BS = B.AbsolutePosition, B.AbsoluteSize
        return AP.X < BP.X + BS.X and AP.X + AS.X > BP.X and AP.Y < BP.Y + BS.Y and AP.Y + AS.Y > BP.Y
    end

    local function PointInside(Object, Position)
        if not Object or not Object.Parent or not Position then
            return false
        end
        local ObjectPosition = Object.AbsolutePosition
        local ObjectSize = Object.AbsoluteSize
        return Position.X >= ObjectPosition.X and Position.X <= ObjectPosition.X + ObjectSize.X
            and Position.Y >= ObjectPosition.Y and Position.Y <= ObjectPosition.Y + ObjectSize.Y
    end

    local function PlacePopup(FrameObject, PreferredPosition, Peers)
        local Position = Menu.ClampPopupPosition(FrameObject, PreferredPosition)
        FrameObject.Position = Position
        for _, Peer in ipairs(Peers or {}) do
            if Peer and Peer.Parent and RectsOverlap(FrameObject, Peer) then
                local Gap = 8
                local Candidates = {
                    UDim2.fromOffset(Peer.AbsolutePosition.X + Peer.AbsoluteSize.X + Gap, Position.Y.Offset),
                    UDim2.fromOffset(Peer.AbsolutePosition.X - FrameObject.AbsoluteSize.X - Gap, Position.Y.Offset),
                    UDim2.fromOffset(Position.X.Offset, Peer.AbsolutePosition.Y + Peer.AbsoluteSize.Y + Gap),
                    UDim2.fromOffset(Position.X.Offset, Peer.AbsolutePosition.Y - FrameObject.AbsoluteSize.Y - Gap)
                }
                for _, Candidate in ipairs(Candidates) do
                    local CandidatePosition = Menu.ClampPopupPosition(FrameObject, Candidate)
                    FrameObject.Position = CandidatePosition
                    if not RectsOverlap(FrameObject, Peer) then
                        Position = CandidatePosition
                        break
                    end
                end
            end
        end
        return FrameObject.Position
    end

    local function MakePopupDraggable(FrameObject, Height)
        local Handle = Create("TextButton", {
            Parent = FrameObject,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.new(1, 0, 0, Height or 14),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            Active = true,
            ZIndex = FrameObject.ZIndex + 20
        })

        local Grip = Create("Frame", {
            Parent = Handle,
            AnchorPoint = Vector2.new(0.5, 0),
            Position = UDim2.new(0.5, 0, 0, 5),
            Size = UDim2.fromOffset(24, 2),
            BackgroundColor3 = Border,
            BackgroundTransparency = 0.12,
            BorderSizePixel = 0,
            ZIndex = Handle.ZIndex + 1
        })
        Corner(Grip, 2)

        local Dragging = false
        local DragStart
        local StartPosition

        Bind(Handle.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = true
                DragStart = Input.Position
                StartPosition = FrameObject.Position
            end
        end))

        Bind(UserInputService.InputChanged:Connect(function(Input)
            if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                local Delta = Input.Position - DragStart
                FrameObject.Position = Menu.ClampPopupPosition(FrameObject, UDim2.fromOffset(StartPosition.X.Offset + Delta.X, StartPosition.Y.Offset + Delta.Y))
            end
        end))

        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = false
            end
        end))
    end

    local function CreateGlyph(ParentObject, Kind, Color, Position)
        local Root = Create("Frame", {
            Parent = ParentObject,
            Position = Position or UDim2.fromOffset(10, 8),
            Size = UDim2.fromOffset(12, 12),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = ParentObject.ZIndex + 2
        })

        local function Line(X, Y, W, H)
            local Object = Create("Frame", {
                Parent = Root,
                Position = UDim2.fromOffset(X, Y),
                Size = UDim2.fromOffset(W, H),
                BackgroundColor3 = Color,
                BorderSizePixel = 0,
                ZIndex = Root.ZIndex + 1
            })
            Corner(Object, 2)
            return Object
        end

        local function Outline(X, Y, W, H)
            local Object = Create("Frame", {
                Parent = Root,
                Position = UDim2.fromOffset(X, Y),
                Size = UDim2.fromOffset(W, H),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = Root.ZIndex + 1
            })
            Corner(Object, 2)
            Stroke(Object, Color, 0, 1)
            return Object
        end

        if Kind == "Bind" then
            Outline(1, 3, 10, 7)
            Line(3, 5, 6, 1)
            Line(2, 7, 1, 1)
            Line(4, 7, 1, 1)
            Line(6, 7, 1, 1)
            Line(8, 7, 1, 1)
            Line(10, 7, 1, 1)
            Line(2, 9, 2, 1)
            Line(5, 9, 3, 1)
            Line(9, 9, 2, 1)
        elseif Kind == "Hotkeys" then
            Line(1, 2, 10, 1)
            Line(1, 6, 10, 1)
            Line(1, 10, 10, 1)
            Line(3, 0, 2, 4)
            Line(7, 4, 2, 4)
            Line(4, 8, 2, 4)
        elseif Kind == "Reset" then
            Line(2, 3, 8, 1)
            Line(5, 1, 2, 1)
            Outline(3, 4, 6, 7)
            Line(5, 6, 1, 3)
            Line(7, 6, 1, 3)
        end
        return Root
    end

    local function CreateMenuEntry(ParentObject, Y, TextValue, GlyphKind, TextColor, Arrow)
        local Entry = Create("TextButton", {
            Parent = ParentObject,
            Position = UDim2.fromOffset(7, Y),
            Size = UDim2.new(1, -14, 0, 27),
            BackgroundColor3 = SurfaceAlt,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = ParentObject.ZIndex + 2
        })
        Corner(Entry, 5)
        local EntryScale = Create("UIScale", {Parent = Entry, Scale = 1})
        local Glyph = CreateGlyph(Entry, GlyphKind, TextColor, UDim2.fromOffset(8, 7))

        local Label = Create("TextLabel", {
            Parent = Entry,
            Position = UDim2.fromOffset(28, 0),
            Size = UDim2.new(1, Arrow and -44 or -34, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = TextValue,
            TextColor3 = TextColor,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = Entry.ZIndex + 2
        })

        local ArrowIcon
        if Arrow then
            ArrowIcon = Icon(Entry, "Chevron", UDim2.fromOffset(8, 8), UDim2.new(1, -10, 0.5, 0), TextColor, Entry.ZIndex + 2)
            ArrowIcon.Rotation = -90
        end

        local Hovered = false
        local Pressed = false
        local function RefreshEntry()
            if not Entry.Parent then return end
            local Selected = Entry:GetAttribute("Selected") == true
            local Active = Selected or Hovered
            local ActiveText = GlyphKind == "Reset" and Danger or (Active and PrimaryText or TextColor)
            local ActiveGlyph = GlyphKind == "Reset" and Danger or (Active and Accent or TextColor)
            Tween(Entry, 0.10, {
                BackgroundTransparency = Selected and 0.18 or (Hovered and 0.42 or 1),
                BackgroundColor3 = Selected and Accent:Lerp(SurfaceAlt, 0.78) or SurfaceAlt
            })
            Tween(Label, 0.10, {TextColor3 = ActiveText})
            SetGearIconColor(Glyph, ActiveGlyph)
            if ArrowIcon then Tween(ArrowIcon, 0.10, {ImageColor3 = ActiveGlyph}) end
            EntryScale.Scale = 1
        end

        RegisterAccentTarget(function()
            RefreshEntry()
        end)

        Bind(Entry.MouseEnter:Connect(function()
            Hovered = true
            RefreshEntry()
        end))
        Bind(Entry.MouseLeave:Connect(function()
            Hovered = false
            Pressed = false
            RefreshEntry()
        end))
        Bind(Entry.MouseButton1Down:Connect(function()
            Pressed = true
            RefreshEntry()
        end))
        Bind(Entry.MouseButton1Up:Connect(function()
            Pressed = false
            RefreshEntry()
        end))
        Bind(Entry:GetAttributeChangedSignal("Selected"):Connect(RefreshEntry))
        RefreshEntry()
        return Entry
    end

    local function SetEntrySelected(Entry, State)
        if not Entry or not Entry.Parent then return end
        Entry:SetAttribute("Selected", State and true or false)
    end

    local function AttachBindButtonHover(Button, RefreshVisual)
        local State = {Hovered = false, Pressed = false}
        local Scale = Button:FindFirstChildWhichIsA("UIScale") or Create("UIScale", {Parent = Button, Scale = 1})
        local function Refresh()
            if not Button or not Button.Parent then return end
            if type(RefreshVisual) == "function" then RefreshVisual(State) end
            Scale.Scale = 1
        end
        RegisterAccentTarget(function()
            Refresh()
        end)
        Bind(Button.MouseEnter:Connect(function()
            State.Hovered = true
            Refresh()
        end))
        Bind(Button.MouseLeave:Connect(function()
            State.Hovered = false
            State.Pressed = false
            Refresh()
        end))
        Bind(Button.MouseButton1Down:Connect(function()
            State.Pressed = true
            Refresh()
        end))
        Bind(Button.MouseButton1Up:Connect(function()
            State.Pressed = false
            Refresh()
        end))
        Refresh()
        return State, Refresh
    end

    CloseGearMenus = function()
        PendingBindCapture = nil
        if ActiveGearMenu then
            ActiveGearMenu:Destroy()
            ActiveGearMenu = nil
        end
        if ActiveGearBindMenu then
            ActiveGearBindMenu:Destroy()
            ActiveGearBindMenu = nil
        end
        if ActiveGearHotkeysMenu then
            ActiveGearHotkeysMenu:Destroy()
            ActiveGearHotkeysMenu = nil
        end
        if ActiveGearButtonIcon then
            SetGearIconColor(ActiveGearButtonIcon, MutedText)
        end
        ActiveGearButton = nil
        ActiveGearButtonIcon = nil
        ActiveGearMeta = nil
        ActiveGearBindEntry = nil
        ActiveGearHotkeysEntry = nil
        if not ActivePopup then
            Menu.PopupInputBlocker.Visible = false
        end
    end

    local function OpenHotkeysMenu(SourceEntry)
        if ActiveGearHotkeysMenu then
            ActiveGearHotkeysMenu:Destroy()
            ActiveGearHotkeysMenu = nil
            SetEntrySelected(SourceEntry, false)
            return
        end
        if not ActiveGearMenu or not ActiveGearMeta then
            return
        end

        ActiveGearHotkeysEntry = SourceEntry
        SetEntrySelected(SourceEntry, true)
        local Binds = GetControlBinds(ActiveGearMeta.Flag)
        local ContentHeight = math.max(32, #Binds * 34)
        local Height = math.min(214, 42 + ContentHeight)

        ActiveGearHotkeysMenu = Create("Frame", {
            Parent = ScreenGui,
            Active = true,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.fromOffset(208, Height),
            BackgroundColor3 = Surface,
            BorderSizePixel = 0,
            ZIndex = 170
        })
        Corner(ActiveGearHotkeysMenu, 7)
        if AddPopupShadow then
            AddPopupShadow(ActiveGearHotkeysMenu, 170)
        end
        Stroke(ActiveGearHotkeysMenu, Border, 0.08, 1)

        local Preferred = UDim2.fromOffset(ActiveGearMenu.AbsolutePosition.X + ActiveGearMenu.AbsoluteSize.X + 8, ActiveGearMenu.AbsolutePosition.Y + 42)
        PlacePopup(ActiveGearHotkeysMenu, Preferred, {ActiveGearBindMenu, ActiveGearMenu})
        MakePopupDraggable(ActiveGearHotkeysMenu, 14)

        Create("TextLabel", {
            Parent = ActiveGearHotkeysMenu,
            Position = UDim2.fromOffset(11, 14),
            Size = UDim2.new(1, -22, 0, 20),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = "Hotkeys",
            TextColor3 = PrimaryText,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 172
        })

        local List = Create("ScrollingFrame", {
            Parent = ActiveGearHotkeysMenu,
            Position = UDim2.fromOffset(8, 38),
            Size = UDim2.new(1, -16, 1, -46),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            CanvasSize = UDim2.fromOffset(0, ContentHeight),
            ScrollBarThickness = 2,
            ScrollBarImageColor3 = Accent,
            ZIndex = 171
        })

        if #Binds == 0 then
            Create("TextLabel", {
                Parent = List,
                Size = UDim2.new(1, 0, 0, 28),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSans,
                Text = "No binds",
                TextColor3 = DisabledText,
                TextSize = 10,
                ZIndex = 172
            })
            return
        end

        for Index, BindData in ipairs(Binds) do
            local Row = Create("Frame", {
                Parent = List,
                Position = UDim2.fromOffset(0, (Index - 1) * 34),
                Size = UDim2.new(1, -3, 0, 30),
                BackgroundColor3 = SurfaceAlt,
                BorderSizePixel = 0,
                ZIndex = 172
            })
            Corner(Row, 5)
            Stroke(Row, Border, 0.42, 1)
            Bind(Row.MouseEnter:Connect(function()
                Tween(Row, 0.10, {BackgroundColor3 = Accent:Lerp(SurfaceAlt, 0.86)})
            end))
            Bind(Row.MouseLeave:Connect(function()
                Tween(Row, 0.10, {BackgroundColor3 = SurfaceAlt})
            end))

            Create("TextLabel", {
                Parent = Row,
                Position = UDim2.fromOffset(10, 0),
                Size = UDim2.new(1, -38, 1, 0),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSansMedium,
                Text = FormatBindLabel(BindData),
                TextColor3 = PrimaryText,
                TextSize = 9,
                TextStrokeColor3 = Color3.new(0, 0, 0),
                TextStrokeTransparency = 0.76,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 173
            })

            local Remove = Create("TextButton", {
                Parent = Row,
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(18, 18),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Font = Enum.Font.BuilderSansMedium,
                Text = "×",
                TextColor3 = DisabledText,
                TextSize = 13,
                ZIndex = 174
            })
            AttachBindButtonHover(Remove, function(State)
                Tween(Remove, 0.10, {
                    BackgroundColor3 = State.Hovered and Danger or SurfaceAlt,
                    BackgroundTransparency = State.Hovered and 0.78 or 1,
                    TextColor3 = State.Hovered and PrimaryText or DisabledText
                })
            end)
            Bind(Remove.MouseButton1Click:Connect(function()
                table.remove(Binds, Index)
                if Menu.KeybindListController and Menu.KeybindListController.MarkDirty then
                    Menu.KeybindListController.MarkDirty()
                end
                SavePositions()
                ActiveGearHotkeysMenu:Destroy()
                ActiveGearHotkeysMenu = nil
                OpenHotkeysMenu(SourceEntry)
            end))
        end
    end

    local function CreateValueControl(ParentObject, Meta, InitialValue, OnChanged)
        local Info = Meta.Info or {}
        if Info.Type == "Boolean" or type(InitialValue) == "boolean" then
            local State = InitialValue == true
            local Button = Create("TextButton", {
                Parent = ParentObject,
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -11, 0, 88),
                Size = UDim2.fromOffset(13, 13),
                BackgroundColor3 = State and Accent or SurfaceAlt,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Text = "",
                ZIndex = 182
            })
            Corner(Button, 3)
            local ButtonStroke = Stroke(Button, State and Accent or Border, 0, 1)
            local Check = Icon(Button, "Check", UDim2.fromOffset(9, 9), UDim2.fromScale(0.5, 0.5), Background, 183)
            Check.Visible = State
            RegisterAccentTarget(function(NewColor)
                if Button and Button.Parent then
                    Button.BackgroundColor3 = State and NewColor or SurfaceAlt
                end
                if ButtonStroke and ButtonStroke.Parent then
                    ButtonStroke.Color = State and NewColor or Border
                end
            end)
            Bind(Button.MouseButton1Click:Connect(function()
                State = not State
                Check.Visible = State
                Button.BackgroundColor3 = State and Accent or SurfaceAlt
                ButtonStroke.Color = State and Accent or Border
                OnChanged(State)
            end))
            OnChanged(State)
            return
        end

        if Info.Type == "Number" or type(InitialValue) == "number" then
            local Minimum = tonumber(Info.Minimum) or 0
            local Maximum = tonumber(Info.Maximum) or math.max(100, tonumber(InitialValue) or 100)
            local Step = math.max(math.abs(tonumber(Info.Step) or 1), 0.000001)
            local Value = math.clamp(tonumber(InitialValue) or Minimum, Minimum, Maximum)
            local Track = Create("Frame", {
                Parent = ParentObject,
                Position = UDim2.fromOffset(12, 96),
                Size = UDim2.fromOffset(112, 4),
                BackgroundColor3 = Border,
                BorderSizePixel = 0,
                ZIndex = 182
            })
            Corner(Track, 2)
            local Fill = Create("Frame", {
                Parent = Track,
                BackgroundColor3 = Accent,
                BorderSizePixel = 0,
                ZIndex = 183
            })
            Corner(Fill, 2)
            local Knob = Create("Frame", {
                Parent = Track,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(6, 13),
                BackgroundColor3 = Color3.fromRGB(218, 232, 239),
                BorderSizePixel = 0,
                ZIndex = 184
            })
            Corner(Knob, 2)
            local ValueLabel = Create("TextLabel", {
                Parent = ParentObject,
                Position = UDim2.fromOffset(132, 84),
                Size = UDim2.fromOffset(32, 20),
                BackgroundColor3 = SurfaceAlt,
                BorderSizePixel = 0,
                Font = Enum.Font.BuilderSansMedium,
                TextColor3 = PrimaryText,
                TextSize = 10,
                ZIndex = 182
            })
            Corner(ValueLabel, 4)
            local Dragging = false
            local function Set(ValueInput)
                Value = math.clamp(tonumber(ValueInput) or Value, Minimum, Maximum)
                Value = Minimum + math.floor(((Value - Minimum) / Step) + 0.5) * Step
                Value = math.clamp(Value, Minimum, Maximum)
                local Power = 10 ^ (tonumber(Info.Decimals) or 0)
                Value = math.floor(Value * Power + 0.5) / Power
                local Alpha = (Value - Minimum) / math.max(0.0001, Maximum - Minimum)
                SmoothSlider(Fill, Knob, Alpha, 0.12)
                ValueLabel.Text = tostring(Value)
                OnChanged(Value)
            end
            local function Update(Input)
                local Alpha = math.clamp((Input.Position.X - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
                Set(Minimum + (Maximum - Minimum) * Alpha)
            end
            Bind(Track.InputBegan:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                    Dragging = true
                    Update(Input)
                end
            end))
            Bind(UserInputService.InputChanged:Connect(function(Input)
                if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                    Update(Input)
                end
            end))
            Bind(UserInputService.InputEnded:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                    Dragging = false
                end
            end))
            Set(Value)
            return
        end

        local Values = Info.Values or {}
        local Current = InitialValue
        local Button = Create("TextButton", {
            Parent = ParentObject,
            Position = UDim2.fromOffset(92, 84),
            Size = UDim2.fromOffset(72, 22),
            BackgroundColor3 = SurfaceAlt,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Font = Enum.Font.BuilderSansMedium,
            Text = tostring(Current),
            TextColor3 = PrimaryText,
            TextSize = 10,
            ZIndex = 182
        })
        Corner(Button, 4)
        Bind(Button.MouseButton1Click:Connect(function()
            local Index = table.find(Values, Current) or 0
            Index = (Index % math.max(1, #Values)) + 1
            Current = Values[Index] or Current
            Button.Text = tostring(Current)
            OnChanged(Current)
        end))
        OnChanged(Current)
    end

