    Menu.BindSystem.CustomMouse = {
        Previous = {MouseButton4 = false, MouseButton5 = false},
        States = {MouseButton4 = false, MouseButton5 = false},
        KeyCodes = {}, InputTypes = {}
    }

    local function FindEnumItem(EnumType, Names)
        local Wanted = {}

        for _, Name in ipairs(Names) do
            Wanted[Name] = true
        end

        for _, Item in ipairs(
            EnumType:GetEnumItems()
) do
            if Wanted[Item.Name] then
                return Item
            end
        end

        return nil
    end

    Menu.BindSystem.CustomMouse.KeyCodes.MouseButton4 =
        FindEnumItem(
            Enum.KeyCode,
            {
                "MouseBackButton",
                "BrowserBack"
            }
)

    Menu.BindSystem.CustomMouse.KeyCodes.MouseButton5 =
        FindEnumItem(
            Enum.KeyCode,
            {
                "MouseForwardButton",
                "BrowserForward"
            }
)

    Menu.BindSystem.CustomMouse.InputTypes.MouseButton4 =
        FindEnumItem(
            Enum.UserInputType,
            {
                "MouseButton4",
                "XButton1"
            }
)

    Menu.BindSystem.CustomMouse.InputTypes.MouseButton5 =
        FindEnumItem(
            Enum.UserInputType,
            {
                "MouseButton5",
                "XButton2"
            }
)

    function Menu.BindSystem.GetCustomMouseStates()
        local States = Menu.BindSystem.CustomMouse.States
        States.MouseButton4 = false
        States.MouseButton5 = false

        for _, Input in ipairs(
            UserInputService:
                GetMouseButtonsPressed()
) do
            local KeyType,
                KeyName =
                Menu.BindSystem.
                    GetInputIdentity(
                        Input
)

            if KeyType
                and (
                    KeyName == "MouseButton4"
                    or KeyName == "MouseButton5"
)
            then
                States[KeyName] = true
            end
        end

        for _, Input in ipairs(
            UserInputService:
                GetKeysPressed()
) do
            local KeyType,
                KeyName =
                Menu.BindSystem.
                    GetInputIdentity(
                        Input
)

            if KeyType
                and (
                    KeyName == "MouseButton4"
                    or KeyName == "MouseButton5"
)
            then
                States[KeyName] = true
            end
        end

        for KeyName, KeyCode in pairs(
            Menu.BindSystem.CustomMouse.KeyCodes
) do
            if KeyCode
                and UserInputService:
                    IsKeyDown(
                        KeyCode
)
            then
                States[KeyName] = true
            end
        end

        for KeyName, InputType in pairs(
            Menu.BindSystem.CustomMouse.InputTypes
) do
            if InputType
                and UserInputService:
                    IsMouseButtonPressed(
                        InputType
)
            then
                States[KeyName] = true
            end
        end

        return States
    end

    function Menu.BindSystem.BindMatchesIdentity(
        BindData,
        KeyType,
        KeyName,
        CheckModifiers
)
        if type(BindData) ~= "table" then
            return false
        end

        local StoredType,
            StoredName =
            Menu.BindSystem.
                CanonicalBindKey(
                    BindData.KeyType,
                    BindData.Key
)

        KeyType,
            KeyName =
            Menu.BindSystem.
                CanonicalBindKey(
                    KeyType,
                    KeyName
)

        if StoredType ~= KeyType
            or StoredName ~= KeyName
        then
            return false
        end

        if CheckModifiers == false then
            return true
        end

        return ModifiersEqual(
            BindData.Modifiers
)
    end
    end

    Menu.DropdownIndicators =
        setmetatable(
            {},
            { __mode = "k" }
)

    function Menu.RefreshDropdownIndicators(CloseAll)
        local Dead = {}

        for Indicator in pairs(
            Menu.DropdownIndicators
) do
            if not Indicator
                or not Indicator.Root
                or not Indicator.Root.Parent
            then
                Dead[#Dead + 1] =
                    Indicator
            else
                if CloseAll == true then
                    Indicator.Opened =
                        false
                end

                Indicator:SetAccentColor(
                    Accent
)

                Indicator:Refresh(
                    false
)
            end
        end

        for _, Indicator in ipairs(
            Dead
) do
            Menu.DropdownIndicators[
                Indicator
            ] = nil
        end
    end

