                Size = UDim2.fromOffset(1, 4),
                BackgroundColor3 = IconColor,
                BorderSizePixel = 0,
                ZIndex = 215
            })
            Corner(Hour, 1)

            local Minute = Create("Frame", {
                Parent = Ring,
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(4, 1),
                BackgroundColor3 = IconColor,
                BorderSizePixel = 0,
                Rotation = 28,
                ZIndex = 215
            })
