        local function NormalizeBind(Value)
            if type(Value) ~= "table" then
                Value = DefaultBind
            end

            local KeyType = tostring(Value.KeyType or "")
            local Key = tostring(Value.Key or "")

            if (KeyType ~= "KeyCode" and KeyType ~= "UserInputType")
                or Key == ""
                or (KeyType == "UserInputType" and Key == "MouseButton1")
            then
                Value = DefaultBind
                KeyType = tostring(Value.KeyType or "KeyCode")
                Key = tostring(Value.Key or "F2")
            end

            local Canonicalizer =
                Menu.BindSystem.CanonicalBindKey

            if type(Canonicalizer)
                == "function"
            then
                KeyType,
                    Key =
                    Canonicalizer(
                        KeyType,
                        Key
)
            else
                local MouseNumber =
                    string.match(
                        Key,
                        "^MouseButton(%d+)$"
)

                if MouseNumber then
                    KeyType =
                        "UserInputType"
                end
            end

            return {
                KeyType = KeyType,
                Key = Key,
                Modifiers = type(Value.Modifiers) == "table"
                    and {
                        Ctrl = Value.Modifiers.Ctrl == true,
                        Shift = Value.Modifiers.Shift == true,
                        Alt = Value.Modifiers.Alt == true
                    }
                    or {Ctrl = false, Shift = false, Alt = false}
            }
        end

        local function Set(Value)
            local BindData = NormalizeBind(Value)
            Menu.Flags[Flag] = BindData
            Button.Text = Menu.BindSystem.BuildBindDisplay(
                BindData.Key,
                BindData.Modifiers
)
            Button.TextColor3 = PrimaryText
            Menu.QuickPanelBindCapture = false
            Tween(ButtonStroke, 0.10, {Color = Border})
            Tween(Button, 0.10, {BackgroundTransparency = 0.30})
        end

        Menu.Setters[Flag] = Set

        Bind(Button.MouseButton1Click:Connect(function()
            Menu.QuickPanelBindCapture = true
            Button.Text = "PRESS..."
            Button.TextColor3 = Accent
            Tween(ButtonStroke, 0.10, {Color = Accent})
            Tween(Button, 0.10, {BackgroundTransparency = 0.12})
        end))

        Bind(Button.MouseButton2Click:Connect(function()
            Menu.QuickPanelBindCapture = false
            Set(DefaultBind)
        end))

        Set(Menu.Flags[Flag] or DefaultBind)

        return {
            Row = Row,
            Button = Button,
            Set = Set,
            Get = function()
                return Menu.Flags[Flag]
            end
        }
    end

    local function CreatePopupSlider(Y, LabelText, Minimum, Maximum, Default, FormatText, Callback, X, Width)
        if Callback == nil and type(FormatText) == "function" then
            Callback = FormatText
            FormatText = nil
        end
        X = tonumber(X) or 28
        Width = tonumber(Width) or 292
        local Row = Create("Frame", {
            Parent = Menu.SettingsUI.SettingsPanel,
            Position = UDim2.fromOffset(X, Y),
            Size = UDim2.fromOffset(Width, 58),
            BackgroundTransparency = 1,
            ZIndex = 31
        })

        Create("TextLabel", {
            Parent = Row,
            Size = UDim2.new(1, -56, 0, 18),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = LabelText,
            TextColor3 = PrimaryText,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = 32
        })

        local ValueLabel = Create("TextBox", {
            Parent = Row,
            AnchorPoint = Vector2.new(1, 0),
            Position = UDim2.new(1, 0, 0, 0),
            Size = UDim2.fromOffset(56, 18),
            BackgroundTransparency = 1,
            ClearTextOnFocus = false,
            Font = Enum.Font.BuilderSansMedium,
            Text = "",
            TextColor3 = PrimaryText,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Right,
            ZIndex = 32
        })

        local Track = Create("Frame", {
            Parent = Row,
            Position = UDim2.fromOffset(0, 34),
            Size = UDim2.new(1, 0, 0, 8),
            Active = true,
            BackgroundColor3 = Border,
            BorderSizePixel = 0,
            ZIndex = 32
        })
        Corner(Track, 2)

        local Fill = Create("Frame", {
            Parent = Track,
            Size = UDim2.new((Default - Minimum) / (Maximum - Minimum), 0, 1, 0),
            BackgroundColor3 = Accent,
            BorderSizePixel = 0,
            ZIndex = 33
        })
        Corner(Fill, 2)
        local FillGlow = Menu:AddSoftGlow(Fill, 33, 8, 0.62, true)

        local Knob = Create("Frame", {
            Parent = Track,
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new((Default - Minimum) / (Maximum - Minimum), 0, 0.5, 0),
            Size = UDim2.fromOffset(7, 14),
            BackgroundColor3 = Color3.fromRGB(226, 230, 246),
            BorderSizePixel = 0,
            ZIndex = 34
        })
        Corner(Knob, 2)
        local KnobGlow = Menu:AddSoftGlow(Knob, 34, 7, 0.22, false)

        local Value = Default
        local Dragging = false

        local function FormatNumber(NewValue)
            if Maximum <= 2 then
                local Formatted = string.format("%.2f", NewValue)
                return Formatted:gsub("(%..-)0+$", "%1"):gsub("%.$", "")
            end
            return tostring(math.floor(NewValue + 0.5))
        end

        local function Set(NewValue)
            NewValue = math.clamp(NewValue, Minimum, Maximum)
            if Maximum <= 2 then
                NewValue = math.floor(NewValue * 100 + 0.5) / 100
            else
                NewValue = math.floor(NewValue + 0.5)
            end
            Value = NewValue
            local Alpha = (Value - Minimum) / (Maximum - Minimum)
            SmoothSlider(Fill, Knob, Alpha, 0.12)
            ValueLabel.Text = FormatText and FormatText(Value) or FormatNumber(Value)
            if Callback then
                Callback(Value)
            end
        end

        RegisterAccentTarget(function(NewColor)
            Fill.BackgroundColor3 = NewColor
            if FillGlow then
                FillGlow.ImageColor3 = NewColor
            end
            if KnobGlow then
                KnobGlow.ImageColor3 = NewColor
            end
        end)

        local function Update(Input)
            local Alpha = math.clamp((Input.Position.X - Track.AbsolutePosition.X) / Track.AbsoluteSize.X, 0, 1)
            Set(Minimum + (Maximum - Minimum) * Alpha)
        end

        Bind(Track.MouseEnter:Connect(function()
            if FillGlow then
                Tween(FillGlow, 0.12, {ImageTransparency = 0.52})
            end
            if KnobGlow then
                Tween(KnobGlow, 0.12, {ImageTransparency = 0.14})
            end
        end))
        Bind(Track.MouseLeave:Connect(function()
            if not Dragging then
                if FillGlow then
                    Tween(FillGlow, 0.12, {ImageTransparency = 0.62})
                end
                if KnobGlow then
                    Tween(KnobGlow, 0.12, {ImageTransparency = 0.22})
                end
            end
        end))

        Bind(ValueLabel.Focused:Connect(function()
            ValueLabel.Text = FormatNumber(Value)
        end))
        Bind(ValueLabel.FocusLost:Connect(function()
            local Parsed = tonumber(tostring(ValueLabel.Text):gsub(",", "."):match("[-+]?%d*%.?%d+"))
            if Parsed ~= nil then
                Set(Parsed)
            else
                ValueLabel.Text = FormatText and FormatText(Value) or FormatNumber(Value)
            end
        end))

        Bind(Track.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = true
                Update(Input)
            end
        end))

        Bind(UserInputService.InputChanged:Connect(function(Input)
            if Dragging and Input.UserInputType == Enum.UserInputType.MouseMovement then
                Update(Input)
            end
        end))

        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = false
            end
        end))

        Set(Default)
        return {
            Row = Row,
            Set = Set,
            Get = function()
                return Value
            end
        }
    end

