    local QuickPanelHasRestoreState = false
    local QuickPanelRestoreState = {
        Menu = false,
        EspPreview = false,
        PlayerList = false
    }

    local function CreateQuickButton(Name, IconName, Order, Callback)
        local Button = Create("TextButton", {
            Parent = QuickPanel,
            Size = UDim2.fromOffset(42, 36),
            BackgroundColor3 = SurfaceAlt,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            LayoutOrder = Order,
            ZIndex = 237
        })
        Corner(Button, 7)

        local ButtonIcon = Icon(
            Button,
            IconName,
            UDim2.fromOffset(17, 17),
            UDim2.fromScale(0.5, 0.5),
            MutedText,
            238
)

        local Data = {
            Button = Button,
            Icon = ButtonIcon,
            Active = false,
            Callback = Callback
        }

        QuickPanelButtons[Name] = Data

        Bind(Button.MouseEnter:Connect(function()
            if not Data.Active then
                Tween(Button, 0.10, {
                    BackgroundTransparency = 0.72
                })
                Menu:SetIconColor(ButtonIcon, PrimaryText, 0.10)
            end
        end))

        Bind(Button.MouseLeave:Connect(function()
            if not Data.Active then
                Tween(Button, 0.10, {
                    BackgroundTransparency = 1
                })
                Menu:SetIconColor(ButtonIcon, MutedText, 0.10)
            end
        end))

        Bind(Button.MouseButton1Click:Connect(function()
            if type(Data.Callback) == "function" then
                Data.Callback()
            end
        end))

        return Data
    end

    local function SetQuickButtonState(Name, State)
        local Data = QuickPanelButtons[Name]
        if not Data then return end

        State = State == true
        if Data.RenderedState == State then
            Data.Active = State
            return
        end

        Data.RenderedState = State
        Data.Active = State

        Tween(Data.Button, 0.10, {
            BackgroundTransparency = State and 0.50 or 1,
            BackgroundColor3 = State and SurfaceAlt or SurfaceAlt
        })

        Menu:SetIconColor(
            Data.Icon,
            State and Accent or MutedText,
            0.10
)
    end

    local function GetEspPreviewVisible()
        if Menu.EspPreviewController
            and type(Menu.EspPreviewController.IsVisible) == "function"
        then
            return Menu.EspPreviewController.IsVisible() == true
        end
        return false
    end

    local function GetPlayerListVisible()
        local Controller = Menu.PlayerListController
        return Controller
            and Controller.State
            and Controller.State.Visible == true
            or false
    end

    local function RefreshQuickPanelButtons()
        SetQuickButtonState("Menu", Menu.Visible == true)
        SetQuickButtonState("ESP Editor", GetEspPreviewVisible())
        SetQuickButtonState("Player List", GetPlayerListVisible())
    end

    CreateQuickButton("Menu", "Boxes", 1, function()
        local State = not (Menu.Visible == true)
        if Menu.MainWindowController and type(Menu.MainWindowController.SetVisible) == "function" then
            Menu.MainWindowController:SetVisible(State)
        else
            Menu.InternalSetVisible(State)
        end
        task.defer(RefreshQuickPanelButtons)
    end)

    CreateQuickButton("ESP Editor", "Eye", 2, function()
        local Controller = Menu.EspPreviewController
        if Controller and type(Controller.SetVisibility) == "function" then
            Controller.SetVisibility(not GetEspPreviewVisible())
        elseif Controller and type(Controller.SetHidden) == "function" then
            Controller.SetHidden(GetEspPreviewVisible())
        end
        task.defer(RefreshQuickPanelButtons)
    end)

    CreateQuickButton("Player List", "User", 3, function()
        local Controller = Menu.PlayerListController
        if Controller and type(Controller.SetVisibility) == "function" then
            Controller:SetVisibility(not GetPlayerListVisible())
        end
        task.defer(RefreshQuickPanelButtons)
    end)

    local function CaptureQuickPanelWindowState()
        QuickPanelRestoreState.Menu =
            Menu.Visible == true

        QuickPanelRestoreState.EspPreview =
            GetEspPreviewVisible()

        QuickPanelRestoreState.PlayerList =
            GetPlayerListVisible()

        QuickPanelHasRestoreState = true
    end

    local function HideQuickPanelWindows()
        if Menu.Visible then
            Menu.InternalSetVisible(false)
        end

        local EspController =
            Menu.EspPreviewController

        if EspController
            and type(EspController.SetVisibility) == "function"
        then
            EspController.SetVisibility(false)
        elseif EspController
            and type(EspController.SetHidden) == "function"
        then
            EspController.SetHidden(true)
        end

        local PlayerController =
            Menu.PlayerListController

        if PlayerController
            and type(PlayerController.SetVisibility) == "function"
        then
            PlayerController:SetVisibility(false)
        end
    end

    local function RestoreQuickPanelWindows()
        if not QuickPanelHasRestoreState then
            return
        end

        Menu.InternalSetVisible(
            QuickPanelRestoreState.Menu == true
)

        local EspController =
            Menu.EspPreviewController

        if EspController
            and type(EspController.SetVisibility) == "function"
        then
            EspController.SetVisibility(
                QuickPanelRestoreState.EspPreview == true
)
        elseif EspController
            and type(EspController.SetHidden) == "function"
        then
            EspController.SetHidden(
                QuickPanelRestoreState.EspPreview ~= true
)
        end

        local PlayerController =
            Menu.PlayerListController

        if PlayerController
            and type(PlayerController.SetVisibility) == "function"
        then
            PlayerController:SetVisibility(
                QuickPanelRestoreState.PlayerList == true
)
        end
    end

    local function SetQuickPanelVisible(State)
        State = State == true

        if State == QuickPanelVisible then
            QuickPanel.Visible = State

            if QuickPanelGlow then
                QuickPanelGlow.Visible = State
            end

            if State then
                RefreshQuickPanelButtons()
            end

            return
        end

        if not State then
            CaptureQuickPanelWindowState()
        end

        QuickPanelVisible = State
        QuickPanel.Visible = QuickPanelVisible

        if QuickPanelGlow then
            QuickPanelGlow.Visible = QuickPanelVisible
        end

        if QuickPanelVisible then
            RestoreQuickPanelWindows()
            task.defer(RefreshQuickPanelButtons)
        else
            HideQuickPanelWindows()
            task.defer(RefreshQuickPanelButtons)
        end
    end

    Menu.QuickPanelController = {
        Root = QuickPanel,
        SetVisibility = SetQuickPanelVisible,
        Toggle = function()
            SetQuickPanelVisible(not QuickPanelVisible)
        end,
        Refresh = RefreshQuickPanelButtons,
        IsVisible = function()
            return QuickPanelVisible
        end
    }

    local QuickPanelRefreshClock = 0
    Bind(RunService.Heartbeat:Connect(function(DeltaTime)
        if not QuickPanelVisible then
            QuickPanelRefreshClock = 0
            return
        end

        QuickPanelRefreshClock += math.clamp(DeltaTime, 0, 0.1)
        if QuickPanelRefreshClock >= 0.50 then
            QuickPanelRefreshClock = 0
            RefreshQuickPanelButtons()
        end
    end))

    Menu.ToggleSettingsPanel = function()
        SetSettingsOpen(not SettingsOpen)
    end

    Bind(Menu.SettingsUI.AddThemeButton.MouseButton1Click:Connect(function()
        local CurrentHex = ColorToThemeHex(Color3.fromHSV(HueValue, SaturationValue, BrightnessValue))
        local ActiveThemeColors = GetPickerThemeColors()

        for _, ExistingHex in ipairs(ActiveThemeColors) do
            if string.upper(ExistingHex) == string.upper(CurrentHex) then
                return
            end
        end

        if #ActiveThemeColors >= 7 then
            table.remove(ActiveThemeColors, 1)
        end

        table.insert(ActiveThemeColors, CurrentHex)
        SavePickerThemeColors()
        RefreshThemeButtons()
    end))

