    Menu.CurrentMode = "Ragebot"

    function Menu.SelectMode(Name)
        Menu.CurrentMode = Name
        for ModeName, Button in pairs(Menu.ModeButtons) do
            local Selected = ModeName == Name
            Tween(Button, 0.14, {
                BackgroundTransparency = Selected and 0 or 1,
                BackgroundColor3 = Selected and SurfaceAlt or Surface,
                TextColor3 = Selected and PrimaryText or MutedText
            })
        end
    end

    function Menu.RestorePageSections(Page, Animated)
        for _, Section in pairs(Menu.Sections) do
            if Section.Root.Parent == Page then
                local Target = Section.HomePosition or Section.Root.Position
                local SectionScale = Section.AssemblyScale

                Section.Root.Position = Target
                if SectionScale then SectionScale.Scale = 1 end
            end
        end
    end

    function Menu.SelectPage(Name)
        Menu.CurrentPage = Name
        Menu.ActivePageName = Name
        ClosePopup()
        local SelectedPage = Menu.Pages[Name]
        for PageName, Page in pairs(Menu.Pages) do
            Page.Visible = PageName == Name
        end
        Menu.RestorePageSections(SelectedPage, Menu.Visible and Main.Visible)
        for ButtonName, Data in pairs(Menu.SidebarButtons) do
            local Selected = ButtonName == Name
            Tween(Data.Button, 0.16, {
                BackgroundTransparency = Selected and 0.72 or 1,
                BackgroundColor3 = Selected and Color3.fromRGB(29, 29, 34) or SidebarColor
            })
            if Data.Scale then
                Tween(Data.Scale, 0.16, {Scale = Selected and 1.025 or 1})
            end
            if Data.Marker then
                Data.Marker.Visible = Selected
                if Selected then
                    Data.Marker.Size = UDim2.fromOffset(2, 8)
                    Data.Marker.Position = UDim2.fromOffset(3, (Data.BaseY or Data.Button.Position.Y.Offset) + 24)
                    Tween(Data.Marker, 0.18, {
                        Size = UDim2.fromOffset(2, 36),
                        Position = UDim2.fromOffset(3, (Data.BaseY or Data.Button.Position.Y.Offset) + 8),
                        BackgroundTransparency = 0
                    })
                end
            end
            if Data.Label then
                Tween(Data.Label, 0.16, {TextColor3 = Selected and PrimaryText or MutedText})
            end
            Menu:SetIconColor(Data.Icon, Selected and Accent or MutedText, 0.16)
        end
    end

    Menu.SelectMode("Ragebot")
    Menu.SelectPage("Combat")

    Bind(RagebotMode.MouseButton1Click:Connect(function()
        Menu.SelectMode("Ragebot")
    end))

    Bind(LegitbotMode.MouseButton1Click:Connect(function()
