        for Name, Data in pairs(Menu.SidebarButtons) do
            Bind(Data.Button.MouseButton1Click:Connect(function()
                Menu.SelectPage(Name)
            end))
            Bind(Data.Button.MouseEnter:Connect(function()
                if Menu.CurrentPage ~= Name then
