    Menu.InitDragRuntime = function()
    local Dragging = false
    local DragStart
    local StartPosition
    local SettingsDragging = false
    local SettingsDragStart
    local SettingsStartPosition
    local ColorPickerWindowDragging = false
    local ColorPickerWindowDragStart
    local ColorPickerWindowStartPosition

    Bind(Menu.SettingsUI.SettingsDragArea.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            SetTextInputsEnabled(false)
            SettingsDragging = true
            SettingsDragStart = Input.Position
            SettingsStartPosition = Menu.SettingsUI.SettingsPanel.Position
        end
    end))

    Bind(Menu.SettingsUI.ColorPickerDragArea.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            SetTextInputsEnabled(false)
            ColorPickerWindowDragging = true
            MarkPickerInteraction(true)
            ColorPickerWindowDragStart = Input.Position
            ColorPickerWindowStartPosition = Menu.SettingsUI.ColorPickerContainer.Position
        end
    end))

    Bind(DragArea.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            SetTextInputsEnabled(false)
            Dragging = true
            DragStart = Input.Position
            StartPosition = Main.Position
        end
    end))

    Bind(Menu.SidebarLogo.InputBegan:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            SetTextInputsEnabled(false)
            Dragging = true
            DragStart = Input.Position
            StartPosition = Main.Position
        end
    end))

    local function ClampCenteredPosition(Object, Position)
        local Camera = workspace.CurrentCamera
        if not Camera then
            return Position
        end

        local Viewport = Camera.ViewportSize
        local ParentObject = Object.Parent
        local ParentPosition = ParentObject and ParentObject.AbsolutePosition or Vector2.new(0, 0)
        local ParentSize = ParentObject and ParentObject.AbsoluteSize or Viewport
        local Size = Object.AbsoluteSize
        local Anchor = Object.AnchorPoint
        local AbsoluteX = ParentPosition.X + (ParentSize.X * Position.X.Scale) + Position.X.Offset
        local AbsoluteY = ParentPosition.Y + (ParentSize.Y * Position.Y.Scale) + Position.Y.Offset
        local MinimumX = 16 + (Size.X * Anchor.X)
        local MaximumX = Viewport.X - 16 - (Size.X * (1 - Anchor.X))
        local MinimumY = 16 + (Size.Y * Anchor.Y)
        local MaximumY = Viewport.Y - 16 - (Size.Y * (1 - Anchor.Y))

        AbsoluteX = math.clamp(AbsoluteX, MinimumX, math.max(MinimumX, MaximumX))
        AbsoluteY = math.clamp(AbsoluteY, MinimumY, math.max(MinimumY, MaximumY))

        return UDim2.new(
            0,
            math.floor((AbsoluteX - ParentPosition.X) + 0.5),
            0,
            math.floor((AbsoluteY - ParentPosition.Y) + 0.5)
)
    end

    Bind(UserInputService.InputChanged:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseMovement then
            if Dragging then
                local Delta = Input.Position - DragStart
                Main.Position = ClampCenteredPosition(Main, UDim2.new(
                    StartPosition.X.Scale,
                    StartPosition.X.Offset + Delta.X,
                    StartPosition.Y.Scale,
                    StartPosition.Y.Offset + Delta.Y
))
            end
            if SettingsDragging then
                local Delta = Input.Position - SettingsDragStart
                Menu.SettingsUI.SettingsPanel.Position = ClampCenteredPosition(Menu.SettingsUI.SettingsPanel, UDim2.new(
                    SettingsStartPosition.X.Scale,
                    SettingsStartPosition.X.Offset + Delta.X,
                    SettingsStartPosition.Y.Scale,
                    SettingsStartPosition.Y.Offset + Delta.Y
))
            end
            if ColorPickerWindowDragging then
                local Delta = Input.Position - ColorPickerWindowDragStart
                Menu.SettingsUI.ColorPickerContainer.Position = ClampCenteredPosition(Menu.SettingsUI.ColorPickerContainer, UDim2.new(
                    ColorPickerWindowStartPosition.X.Scale,
                    ColorPickerWindowStartPosition.X.Offset + Delta.X,
                    ColorPickerWindowStartPosition.Y.Scale,
                    ColorPickerWindowStartPosition.Y.Offset + Delta.Y
))
            end
        end
    end))

    Bind(UserInputService.InputEnded:Connect(function(Input)
        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            if Dragging then
                SavedPositions.Main = EncodePosition(Main.Position)
                SavePositions()
            end
            if SettingsDragging then
                SavedPositions.Settings = EncodePosition(Menu.SettingsUI.SettingsPanel.Position)
                SavePositions()
            end
            if ColorPickerWindowDragging then
                SavedPositions.ColorPickerOffsetX = Menu.SettingsUI.ColorPickerContainer.AbsolutePosition.X - Menu.SettingsUI.SettingsPanel.AbsolutePosition.X
                SavedPositions.ColorPickerOffsetY = Menu.SettingsUI.ColorPickerContainer.AbsolutePosition.Y - Menu.SettingsUI.SettingsPanel.AbsolutePosition.Y
                SavedPositions.ColorPickerPinned = true
                SavePositions()
                MarkPickerInteraction(false, 0.24)
            end
            Dragging = false
            SettingsDragging = false
            ColorPickerWindowDragging = false
            task.defer(function()
                SetTextInputsEnabled(true)
            end)
        end
    end))

    end
    Menu.InitDragRuntime()
    Menu.InitDragRuntime = nil

    Menu.UpdateScale = function()
        local Camera = workspace.CurrentCamera
        if not Camera then
            return
        end
        local Viewport = Camera.ViewportSize
        Menu.Flags.ViewportScale = math.min(1, (Viewport.X - 20) / 744, (Viewport.Y - 20) / 610)
        MainScale.Scale = Menu.Flags.ViewportScale * BaseScaleFactor
    end

    Menu.UpdateScale()
    Bind(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        task.defer(Menu.UpdateScale)
    end))

    if workspace.CurrentCamera then
        Bind(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(Menu.UpdateScale))
    end

    Menu.AssemblyTargets = {
        Sidebar = Sidebar.Position,
        Topbar = Topbar.Position,
        SearchBar = SearchBar.Position,
        SearchSettings = SearchSettings.Position
    }

    Menu.AssemblyGeneration = 0

    Menu.InitializeSectionAssemblyRuntime = function()
        for _, Section in pairs(Menu.Sections) do
            if typeof(Section.Root) == "Instance" then
                Section.HomePosition = Section.HomePosition or Section.Root.Position
                Section.AssemblyScale = Create("UIScale", {
                    Parent = Section.Root,
                    Scale = 1
                })
            end
        end
    end
    Menu.InitializeSectionAssemblyRuntime()
    Menu.InitializeSectionAssemblyRuntime = nil

    Menu.InternalSetVisible = function(State)
        State = State and true or false

        if Menu.MainWindowController then
            Menu.Visible = State
            Main.Visible = false
            Overlay.Visible = false
            InputBlocker.Visible = false
            Library.Call(function()
                Menu.MainWindowController:SetVisible(State)
            end)
            if Menu.QuickPanelController and Menu.QuickPanelController.Refresh then
                Menu.QuickPanelController.Refresh()
            end
            return
        end

        Menu.AssemblyGeneration += 1
        local Generation = Menu.AssemblyGeneration
        Menu.Visible = State

        local TargetScale = (Menu.Flags.ViewportScale or 1) * BaseScaleFactor
        if State then
            local TargetPosition = DecodePosition(SavedPositions.Main, UDim2.fromScale(0.5, 0.535))
            Main.Position = TargetPosition
            MainScale.Scale = TargetScale
            Main.BackgroundTransparency = 0.08
            Main.Visible = true
            InputBlocker.Visible = true
            Overlay.Visible = Menu.Flags.BackgroundDim ~= false
            Overlay.BackgroundTransparency = 0.55
            Sidebar.Position = Menu.AssemblyTargets.Sidebar
            Topbar.Position = Menu.AssemblyTargets.Topbar
            SearchBar.Position = Menu.AssemblyTargets.SearchBar
            SearchSettings.Position = Menu.AssemblyTargets.SearchSettings
            for _, Section in pairs(Menu.Sections) do
                if Section.Root and Section.Root.Parent then
                    Section.Root.Position = Section.HomePosition or Section.Root.Position
                    if Section.AssemblyScale then Section.AssemblyScale.Scale = 1 end
                end
            end
        else
            Library.Call(ClosePopup)
            if type(CloseGearMenus) == "function" then Library.Call(CloseGearMenus) end
            if type(SetSettingsOpen) == "function" then Library.Call(SetSettingsOpen, false) end
            if Menu.ConfigsUI and type(Menu.ConfigsUI.SetOpen) == "function" then
                Library.Call(Menu.ConfigsUI.SetOpen, false)
            end
            if type(SetPickerOpen) == "function" then Library.Call(SetPickerOpen, false) end

            if SettingsToggleHitbox then
                SettingsToggleHitbox.Visible = false
                SettingsToggleHitbox.Active = false
            end
            if Menu.SettingsInputBlocker then
                Menu.SettingsInputBlocker.Visible = false
                Menu.SettingsInputBlocker.Active = false
            end
            if Menu.PopupInputBlocker then
                Menu.PopupInputBlocker.Visible = false
                Menu.PopupInputBlocker.Active = false
            end
            if Menu.PickerInputBlocker then
                Menu.PickerInputBlocker.Visible = false
                Menu.PickerInputBlocker.Active = false
            end

            if Menu.SettingsUI then
                if Menu.SettingsUI.SettingsPanel then Menu.SettingsUI.SettingsPanel.Visible = false end
                if Menu.SettingsUI.SettingsOverlay then Menu.SettingsUI.SettingsOverlay.Visible = false end
                if Menu.SettingsUI.ColorPickerContainer then Menu.SettingsUI.ColorPickerContainer.Visible = false end
                if Menu.SettingsUI.ColorPickerGlow then Menu.SettingsUI.ColorPickerGlow.Visible = false end
            end
            if Menu.ConfigsUI then
                Menu.ConfigsUI.Open = false
                if Menu.ConfigsUI.Window then Menu.ConfigsUI.Window.Visible = false end
                if Menu.ConfigsUI.Overlay then Menu.ConfigsUI.Overlay.Visible = false end
            end

            Main.Visible = false
            Overlay.Visible = false
            InputBlocker.Visible = false
        end

        if Menu.QuickPanelController and Menu.QuickPanelController.Refresh then
            Menu.QuickPanelController.Refresh()
        end
    end

    Menu.BindSystem.CaptureIdentity = function(
        KeyType,
        KeyName
)
        if not PendingBindCapture then
            return false
        end

        KeyType,
            KeyName =
            Menu.BindSystem.
                CanonicalBindKey(
                    KeyType,
                    KeyName
)

        if not KeyType
            or not KeyName
            or KeyName == ""
        then
            return false
        end

        if KeyType == "UserInputType"
            and KeyName == "MouseButton1"
        then
            if PendingBindCapture.SetText then
                PendingBindCapture.SetText(
                    "LMB unavailable"
)
            end

            return true
        end

        local Meta =
            PendingBindCapture.Meta

        local TargetFlag =
            Meta
            and tostring(
                Meta.Flag or ""
)
            or ""

        if TargetFlag == ""
            or type(
                Menu.Flags[TargetFlag]
            ) ~= "boolean"
        then
            if PendingBindCapture.SetText then
                PendingBindCapture.SetText(
                    "Boolean only"
)
            end

            PendingBindCapture = nil
            return true
        end

        local Mode =
            PendingBindCapture.Mode
            and PendingBindCapture.Mode()
            or "Toggle"

        Mode =
            Mode == "Hold"
            and "Hold"
            or "Toggle"

        local Modifiers =
            Menu.BindSystem.
                ReadModifiers()

        local Binds =
            Menu.BindSystem.
                GetControlBinds(
                    TargetFlag
)

        local ShowInBinds =
            PendingBindCapture.ShowInBinds == nil
            or PendingBindCapture.
                ShowInBinds()

        local MetaGateFlag =
            Meta.Info
            and Meta.Info.GateFlag

        local GateFlag =
            Mode == "Hold"
            and type(MetaGateFlag)
                == "string"
            and MetaGateFlag
            or nil

        for Index = #Binds, 1, -1 do
            local Existing =
                Binds[Index]

            local ExistingModifiers =
                type(
                    Existing.Modifiers
                ) == "table"
                and Existing.Modifiers
                or {}

            if Existing.KeyType
                    == KeyType
                and Existing.Key
                    == KeyName
                and (
                    ExistingModifiers.Ctrl
                        == true
) == (
                    Modifiers.Ctrl
                        == true
)
                and (
                    ExistingModifiers.Shift
                        == true
) == (
                    Modifiers.Shift
                        == true
)
                and (
                    ExistingModifiers.Alt
                        == true
) == (
                    Modifiers.Alt
                        == true
)
            then
                table.remove(
                    Binds,
                    Index
)
            end
        end

        local BindData = {
            Id =
                tostring(
                    os.clock()
)
                .. tostring(
                    math.random(
                        1000,
                        9999
)
),
            KeyType = KeyType,
            Key = KeyName,
            Modifiers = Modifiers,
            Display =
                Menu.BindSystem.
                    BuildBindDisplay(
                        KeyName,
                        Modifiers
),
            Mode = Mode,
            ShowInBinds =
                ShowInBinds,
            GateFlag =
                GateFlag
        }

        Binds[#Binds + 1] =
            BindData

        if Menu.KeybindListController
            and Menu.KeybindListController.MarkDirty
        then
            Menu.KeybindListController.
                MarkDirty()
        end

        if PendingBindCapture.SetText then
            PendingBindCapture.SetText(
                BindData.Display
)
        end

        PendingBindCapture = nil
        return true
    end

    Menu.BindSystem.CaptureInput = function(Input)
        if not PendingBindCapture then
            return false
        end

        if Input.UserInputType
            == Enum.UserInputType.MouseButton1
        then
            return Menu.BindSystem.
                CaptureIdentity(
                    "UserInputType",
                    "MouseButton1"
)
        end

        if Input.UserInputType
                == Enum.UserInputType.Keyboard
            and Menu.BindSystem.
                IsModifierKey(
                    Input.KeyCode
)
        then
            return true
        end

        local KeyType,
            KeyName =
            Menu.BindSystem.
                GetInputIdentity(
                    Input
)

        if not KeyType
            or not KeyName
        then
            return false
        end

        return Menu.BindSystem.
            CaptureIdentity(
                KeyType,
                KeyName
)
    end

    Menu.BindSystem.ExecutePressed = function(TargetFlag, BindData)
        TargetFlag = tostring(TargetFlag or "Unknown")
        local Current = Menu.Flags[TargetFlag]

        if type(Current) ~= "boolean" or type(BindData) ~= "table" then
            return
        end

        if BindData.Mode ~= "Hold" then
            Menu.BindSystem.ApplyFlagValue(TargetFlag, not Current)
            return
        end

        local GateFlag = type(BindData.GateFlag) == "string" and BindData.GateFlag or nil
        if GateFlag and Menu.Flags[GateFlag] ~= true then
            return
        end

        local RuntimeKey = Menu.BindSystem.GetRuntimeKey(TargetFlag, BindData)
        if Menu.BindRuntime[RuntimeKey] ~= nil then
            return
        end

        local HoldState = Menu.BindHoldState[TargetFlag]
        if type(HoldState) ~= "table" then
            HoldState = {Count = 0, Base = Current == true}
            Menu.BindHoldState[TargetFlag] = HoldState
        end

        HoldState.Count += 1
        Menu.BindRuntime[RuntimeKey] = {
            TargetFlag = TargetFlag,
            GateFlag = GateFlag
        }

        if Current ~= true then
            Menu.BindSystem.ApplyFlagValue(TargetFlag, true)
        end

        if Menu.KeybindListController and Menu.KeybindListController.MarkDirty then
            Menu.KeybindListController.MarkDirty()
        end
    end

    Menu.BindSystem.ProcessIdentityBegan =
        function(
            KeyType,
            KeyName
)
            local Matched = false
            local ExecutedTargets = {}
            local AllBinds =
                SavedPositions.ControlBinds
                or {}

            for TargetFlag, Binds in pairs(
                AllBinds
) do
                TargetFlag =
                    tostring(
                        TargetFlag
)

                if type(Binds)
                        == "table"
                    and type(
                        Menu.Flags[
                            TargetFlag
                        ]
                    ) == "boolean"
                    and not ExecutedTargets[
                        TargetFlag
                    ]
                then
                    for _, BindData in ipairs(
                        Binds
) do
                        if Menu.BindSystem.
                            BindMatchesIdentity(
                                BindData,
                                KeyType,
                                KeyName,
                                true
)
                        then
                            ExecutedTargets[
                                TargetFlag
                            ] = true

                            Matched = true

                            Menu.BindSystem.
                                ExecutePressed(
                                    TargetFlag,
                                    BindData
)

                            break
                        end
                    end
                end
            end

            return Matched
        end

    Menu.BindSystem.ProcessIdentityEnded =
        function(
            KeyType,
            KeyName
)
            local AllBinds =
                SavedPositions.ControlBinds
                or {}

            for TargetFlag, Binds in pairs(
                AllBinds
) do
                TargetFlag =
                    tostring(
                        TargetFlag
)

                if type(Binds)
                    == "table"
                then
                    for _, BindData in ipairs(
                        Binds
) do
                        if BindData.Mode
                                == "Hold"
                            and Menu.BindSystem.
                                BindMatchesIdentity(
                                    BindData,
                                    KeyType,
                                    KeyName,
                                    false
)
                        then
                            Menu.BindSystem.
                                ReleaseHold(
                                    Menu.BindSystem.
                                        GetRuntimeKey(
                                            TargetFlag,
                                            BindData
)
)
                        end
                    end
                end
            end
        end

    Menu.BindSystem.ProcessBegan = function(Input)
        local Matched = false
        local ExecutedTargets = {}
        local AllBinds = SavedPositions.ControlBinds or {}

        for TargetFlag, Binds in pairs(AllBinds) do
            TargetFlag = tostring(TargetFlag)

            if type(Binds) == "table"
                and type(Menu.Flags[TargetFlag]) == "boolean"
                and not ExecutedTargets[TargetFlag] then
                for _, BindData in ipairs(Binds) do
                    if Menu.BindSystem.BindMatchesInput(BindData, Input, true) then
                        ExecutedTargets[TargetFlag] = true
                        Matched = true
                        Menu.BindSystem.ExecutePressed(TargetFlag, BindData)
                        break
                    end
                end
            end
        end

        return Matched
    end

    Menu.BindSystem.ProcessEnded = function(Input)
        local AllBinds = SavedPositions.ControlBinds or {}

        for TargetFlag, Binds in pairs(AllBinds) do
            TargetFlag = tostring(TargetFlag)

            if type(Binds) == "table" then
                for _, BindData in ipairs(Binds) do
                    if BindData.Mode == "Hold"
                        and Menu.BindSystem.BindMatchesInput(BindData, Input, false) then
                        Menu.BindSystem.ReleaseHold(Menu.BindSystem.GetRuntimeKey(TargetFlag, BindData))
                    end
                end
            end
        end
    end

    Bind(UserInputService.InputBegan:Connect(function(Input, Processed)
        if PendingBindCapture then
            if Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode == Enum.KeyCode.Escape then
                if PendingBindCapture.SetText then
                    PendingBindCapture.SetText("Press key")
                end
                PendingBindCapture = nil
                return
            end
            if Menu.BindSystem.CaptureInput(Input) then
                return
            end
        end

        if Input.UserInputType == Enum.UserInputType.MouseButton1 then
            local Position = Input.Position
            local function IsInside(Object)
                if not Object or not Object.Parent then
                    return false
                end
                local ObjectPosition = Object.AbsolutePosition
                local ObjectSize = Object.AbsoluteSize
                return Position.X >= ObjectPosition.X and Position.X <= ObjectPosition.X + ObjectSize.X
                    and Position.Y >= ObjectPosition.Y and Position.Y <= ObjectPosition.Y + ObjectSize.Y
            end

            if ActiveGearMenu
                and not IsInside(ActiveGearMenu)
                and not IsInside(ActiveGearBindMenu)
                and not IsInside(ActiveGearHotkeysMenu)
                and not IsInside(ActiveGearButton) then
                CloseGearMenus()
            end

            if ActivePopup and not IsInside(ActivePopup) then
                ClosePopup()
            end
        end

        if Input.UserInputType == Enum.UserInputType.MouseButton1 and PickerOpen and Menu.SettingsUI.ColorPickerContainer.Visible then
            local Position = Input.Position
            local PickerPosition = Menu.SettingsUI.ColorPickerContainer.AbsolutePosition
            local PickerSize = Menu.SettingsUI.ColorPickerContainer.AbsoluteSize
            local PickerAnchor = Menu.SettingsUI.PickerAnchor or Menu.SettingsUI.AccentPreviewButton
            local SwatchPosition = PickerAnchor.AbsolutePosition
            local SwatchSize = PickerAnchor.AbsoluteSize
            local InsidePicker = Position.X >= PickerPosition.X and Position.X <= PickerPosition.X + PickerSize.X
                and Position.Y >= PickerPosition.Y and Position.Y <= PickerPosition.Y + PickerSize.Y
            local InsideSwatch = Position.X >= SwatchPosition.X and Position.X <= SwatchPosition.X + SwatchSize.X
                and Position.Y >= SwatchPosition.Y and Position.Y <= SwatchPosition.Y + SwatchSize.Y
            if not InsidePicker and not InsideSwatch and CanDismissPicker() then
                SetPickerOpen(false)
            end
        end

        local FocusedTextBox = UserInputService:GetFocusedTextBox()

        if not FocusedTextBox and Menu.QuickPanelBindCapture then
            if Input.UserInputType == Enum.UserInputType.Keyboard
                and Input.KeyCode == Enum.KeyCode.Escape
            then
                Menu.QuickPanelBindCapture = false

                if Menu.SettingsUI.QuickPanelBindControl
                    and Menu.SettingsUI.QuickPanelBindControl.Set
                then
                    Menu.SettingsUI.QuickPanelBindControl.Set(
                        Menu.Flags["Quick Panel Bind"]
)
                end

                return
            end

            local KeyType, KeyName =
                Menu.BindSystem.GetInputIdentity(Input)

            if KeyType and KeyName then
                KeyType,
                    KeyName =
                    Menu.BindSystem.CanonicalBindKey(
                        KeyType,
                        KeyName
)

                local NewBind = {
                    KeyType = KeyType,
                    Key = KeyName,
                    Modifiers = Menu.BindSystem.ReadModifiers()
                }

                if Menu.SettingsUI.QuickPanelBindControl
                    and Menu.SettingsUI.QuickPanelBindControl.Set
                then
                    Menu.SettingsUI.QuickPanelBindControl.Set(NewBind)
                else
                    Menu.Flags["Quick Panel Bind"] = NewBind
                    Menu.QuickPanelBindCapture = false
                end

                return
            end
        end

        local QuickBind =
            Menu.Flags["Quick Panel Bind"]

        if not FocusedTextBox
            and type(QuickBind) == "table"
            and Menu.BindSystem.BindMatchesInput(
                QuickBind,
                Input,
                true
)
        then
            if Menu.QuickPanelController
                and Menu.QuickPanelController.Toggle
            then
                Menu.QuickPanelController.Toggle()
            end

            return
        end

        local BindMatched = false
        if not FocusedTextBox then
            BindMatched = Menu.BindSystem.ProcessBegan(Input)
        end

        if Processed and not BindMatched then
            return
        end
    end))

    Bind(UserInputService.InputEnded:Connect(function(Input)
        Menu.BindSystem.ProcessEnded(Input)
    end))

    Menu.CustomMouseAccumulator = 0

    Bind(RunService.Heartbeat:Connect(function(DeltaTime)
        Menu.CustomMouseAccumulator +=
            math.clamp(
                DeltaTime,
                0,
                0.05
)

        if Menu.CustomMouseAccumulator
            < 1 / 30
        then
            return
        end

        Menu.CustomMouseAccumulator = 0

        local States =
            Menu.BindSystem.
                GetCustomMouseStates()

        for _, KeyName in ipairs({
            "MouseButton4",
            "MouseButton5"
        }) do
            local IsDown =
                States[KeyName]
                == true

            local WasDown =
                Menu.BindSystem.
                    CustomMouse.
                    Previous[
                        KeyName
                    ] == true

            if IsDown ~= WasDown then
                Menu.BindSystem.
                    CustomMouse.
                    Previous[
                        KeyName
                    ] = IsDown

                if IsDown then
                    local FocusedTextBox =
                        UserInputService:
                            GetFocusedTextBox()

                    if not FocusedTextBox then
                        if PendingBindCapture then
                            Menu.BindSystem.
                                CaptureIdentity(
                                    "UserInputType",
                                    KeyName
)
                        elseif Menu.QuickPanelBindCapture then
                            local NewBind = {
                                KeyType =
                                    "UserInputType",
                                Key = KeyName,
                                Modifiers =
                                    Menu.BindSystem.
                                        ReadModifiers()
                            }

                            if Menu.SettingsUI.
                                QuickPanelBindControl
                                and Menu.SettingsUI.
                                    QuickPanelBindControl.Set
                            then
                                Menu.SettingsUI.
                                    QuickPanelBindControl.Set(
                                        NewBind
)
                            else
                                Menu.Flags[
                                    "Quick Panel Bind"
                                ] = NewBind

                                Menu.QuickPanelBindCapture =
                                    false
                            end
                        else
                            local QuickBind =
                                Menu.Flags[
                                    "Quick Panel Bind"
                                ]

                            if type(QuickBind)
                                    == "table"
                                and Menu.BindSystem.
                                    BindMatchesIdentity(
                                        QuickBind,
                                        "UserInputType",
                                        KeyName,
                                        true
)
                            then
                                if Menu.QuickPanelController
                                    and Menu.QuickPanelController.Toggle
                                then
                                    Menu.QuickPanelController.Toggle()
                                end
                            else
                                Menu.BindSystem.
                                    ProcessIdentityBegan(
                                        "UserInputType",
                                        KeyName
)
                            end
                        end
                    end
                else
                    Menu.BindSystem.
                        ProcessIdentityEnded(
                            "UserInputType",
                            KeyName
)
                end
            end
        end
    end))

    Menu.Visible = false
    Main.Visible = false
    Overlay.Visible = false
    InputBlocker.Visible = false
    Menu.SettingsInputBlocker.Visible = false
    Menu.PopupInputBlocker.Visible = false
    Menu.PickerInputBlocker.Visible = false

    function Menu:SetVisible(State)
        Menu.InternalSetVisible(State)
    end

    function Menu:Toggle()
        Menu.InternalSetVisible(not Menu.Visible)
    end

    function Menu:GetFlag(Name)
        return self.Flags[Name]
    end

    function Menu:Destroy()
        for _, Connection in ipairs(self.Connections) do
            Library.Call(function()
                Connection:Disconnect()
            end)
        end
        table.clear(self.Connections)
        if self.MainWindowController
            and self.MainWindowController.Native
            and self.MainWindowController.Native.Root
        then
            Library.Call(function()
                self.MainWindowController.Native.Root:Destroy()
            end)
        end
        ScreenGui:Destroy()
    end

    function Menu:InstallPublicApi()
    local Library = self
    local ApiState = {Initialized = false, PageSlots = {}, Keybinds = {}, ActivePage = nil}
    ApiState.PageOrder = {"Combat", "Visuals", "Movement", "World", "Utility", "Settings", "Players", "Cloud", "Config", "Misc"}
    ApiState.PageIcons = {
        Combat = "Rifle",
        Visuals = "Eye",
        Movement = "Run",
        World = "Globe",
        Utility = "Wrench",
        Settings = "Gear",
        Players = "User",
        Cloud = "Cloud",
        Config = "Sliders",
        Misc = "Boxes"
    }
    ApiState.WindowObject = nil

    local function ApiRead(Data, Name, Fallback)
        if type(Data) ~= "table" then
            return Fallback
        end
        local Value = Data[Name]
        if Value == nil then
            Value = Data[string.lower(Name)]
        end
        if Value == nil then
            return Fallback
        end
        return Value
    end

    local function ApiNormalizeFlag(Data, Name)
        return tostring(ApiRead(Data, "Flag", Name) or Name)
    end

    local function ApiClearBuiltInContent()
        if ApiState.Initialized then
            return
        end
        ApiState.Initialized = true
        local PreservedSetters = {
            QuickPanelBind = Menu.Setters["Quick Panel Bind"]
        }

        local PreservedFlags = {
            QuickPanelBind = Menu.Flags["Quick Panel Bind"],
            AutoSave = Menu.Flags.AutoSave,
            BackgroundDim = Menu.Flags.BackgroundDim,
            AnimationSpeed = Menu.Flags.AnimationSpeed,
            MenuScale = Menu.Flags.MenuScale,
            ViewportScale = Menu.Flags.ViewportScale,
            HideWatermark = Menu.Flags.HideWatermark,
            WatermarkScale = Menu.Flags.WatermarkScale,
            AccentAlpha = Menu.Flags.AccentAlpha,
            HideEspPreview = Menu.Flags.HideEspPreview,
            EspPreviewScale = Menu.Flags.EspPreviewScale
        }
        for _, Section in pairs(Menu.Sections) do
            if Section.Root and Section.Root.Parent then
                Section.Root:Destroy()
            end
        end
        for _, Page in pairs(Menu.Pages) do
            if Page and Page.Parent then
                Page:Destroy()
            end
        end
        for _, Data in pairs(Menu.SidebarButtons) do
            if Data.Button and Data.Button.Parent then
                Data.Button:Destroy()
            end
            if Data.MarkerGlow and Data.MarkerGlow.Parent then
                Data.MarkerGlow:Destroy()
            end
            if Data.Marker and Data.Marker.Parent then
                Data.Marker:Destroy()
            end
        end
        table.clear(Menu.Sections)
        table.clear(Menu.Pages)
        table.clear(Menu.SidebarButtons)
        table.clear(Menu.Flags)
        table.clear(Menu.Setters)
        table.clear(Menu.DefaultFlags)
        table.clear(Menu.DefaultFlagKnown)
        for Name, Value in pairs(PreservedFlags) do
            if Value ~= nil then
                if Name == "QuickPanelBind" then
                    Menu.Flags["Quick Panel Bind"] = Value
                else
                    Menu.Flags[Name] = Value
                end
            end
        end

        if type(PreservedSetters.QuickPanelBind) == "function" then
            Menu.Setters["Quick Panel Bind"] = PreservedSetters.QuickPanelBind
            Menu.DefaultFlagKnown["Quick Panel Bind"] = true
            Menu.DefaultFlags["Quick Panel Bind"] = CloneFlagValue(PreservedFlags.QuickPanelBind)
        end

        RagebotMode.Visible = false
        LegitbotMode.Visible = false
        Menu.CurrentPage = nil
        Menu.CurrentMode = nil
    end

    local function ApiEnsureSidebarPage(Name)
        local Existing = Menu.SidebarButtons[Name]
        if Existing then
            return Existing
        end
        local Count = 0
        for _ in pairs(Menu.SidebarButtons) do
            Count += 1
        end
        local Y = 146 + (Count * 64)
        local Button = Create("TextButton", {
            Parent = Sidebar,
            Position = UDim2.fromOffset(14, Y),
            Size = UDim2.fromOffset(60, 54),
            BackgroundColor3 = SidebarColor,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 5
        })
        Corner(Button, 8)
        local Scale = Create("UIScale", {
            Parent = Button,
            Scale = 1
        })
        local Marker = Create("Frame", {
            Parent = Sidebar,
            Position = UDim2.fromOffset(3, Y + 8),
            Size = UDim2.fromOffset(2, 36),
            BackgroundColor3 = Accent,
            BackgroundTransparency = 0,
            BorderSizePixel = 0,
            Visible = false,
            ZIndex = 8
        })
        Corner(Marker, 2)
        local MarkerGlow = Menu:AddSoftGlow(Marker, 8, 8, 0.62, true)
        local IconObject = Icon(
            Button,
            ApiState.PageIcons[Name] or "Gear",
            Name == "Combat" and UDim2.fromOffset(23, 23) or UDim2.fromOffset(17, 17),
            Name == "Combat" and UDim2.new(0.5, 0, 0, 17) or UDim2.new(0.5, 0, 0, 17),
            MutedText,
            7
)
        local Label = Create("TextLabel", {
            Parent = Button,
            Position = UDim2.fromOffset(2, 31),
            Size = UDim2.new(1, -4, 0, 15),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = Name,
            TextColor3 = MutedText,
            TextSize = 9,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 7
        })
        Existing = {
            Button = Button,
            Marker = Marker,
            MarkerGlow = MarkerGlow,
            Icon = IconObject,
            Label = Label,
            Scale = Scale,
            BaseY = Y
        }
        Menu.SidebarButtons[Name] = Existing
        Bind(Button.MouseEnter:Connect(function()
            if Menu.ActivePageName ~= Name then
                Tween(Button, 0.14, {BackgroundTransparency = 0.84, BackgroundColor3 = Color3.fromRGB(14, 23, 31)})
                Tween(Scale, 0.14, {Scale = 1.035})
                Tween(Label, 0.14, {TextColor3 = PrimaryText})
                Menu:SetIconColor(IconObject, PrimaryText, 0.14)
            end
        end))
        Bind(Button.MouseLeave:Connect(function()
            if Menu.ActivePageName ~= Name then
                Tween(Button, 0.14, {BackgroundTransparency = 1, BackgroundColor3 = SidebarColor})
                Tween(Scale, 0.14, {Scale = 1})
                Tween(Label, 0.14, {TextColor3 = MutedText})
                Menu:SetIconColor(IconObject, MutedText, 0.14)
            end
        end))
        Bind(Button.MouseButton1Down:Connect(function()
            Tween(Scale, 0.08, {Scale = 0.97})
        end))
        Bind(Button.MouseButton1Up:Connect(function()
            Tween(Scale, 0.12, {Scale = Menu.ActivePageName == Name and 1.025 or 1.035})
        end))
        Bind(Button.MouseButton1Click:Connect(function()
            ApiState.ActivePage = Name
            Menu.SelectPage(Name)
            ApiState:RefreshSubPageButtons(Name)
        end))
        return Existing
    end

    local function ApiGetPage(Name)
        local Page = Menu.Pages[Name]
        if not Page then
            Page = CreatePage(Name)
        end
        ApiEnsureSidebarPage(Name)
        if not ApiState.PageSlots[Name] then
            ApiState.PageSlots[Name] = {Left = 0, Right = 0, SubPages = {}, CurrentSubPage = nil}
        end
        return Page, ApiState.PageSlots[Name]
    end

    function ApiState:SelectSubPage(PageObject, Name)
        for SubPageName, SubPageObject in pairs(PageObject.SubPages) do
            local Selected = SubPageName == Name
            SubPageObject.Frame.Visible = Selected

            if SubPageObject.Button then
                Tween(SubPageObject.Button, 0.16, {
                    BackgroundTransparency = 1,
                    BackgroundColor3 = Topbar.BackgroundColor3,
                    TextColor3 = Selected and PrimaryText or MutedText
                })
            end

            if SubPageObject.Scale then
                Tween(SubPageObject.Scale, 0.16, {Scale = Selected and 1.01 or 1})
            end

            if SubPageObject.Indicator then
                SubPageObject.Indicator.Visible = Selected

                if Selected then
                    SubPageObject.Indicator.Size = UDim2.fromOffset(18, 2)
                    Tween(SubPageObject.Indicator, 0.18, {
                        Size = UDim2.fromOffset(28, 2),
                        BackgroundTransparency = 0
                    })
                end
            end
        end

        PageObject.ActiveSubPage = Name
    end

    function ApiState:RefreshSubPageButtons(PageName)
        if not self.WindowObject then
            return
        end
        self.ActivePage = PageName or self.ActivePage
        for Name, PageObject in pairs(self.WindowObject.Pages) do
            local Visible = Name == self.ActivePage
            for _, SubPageObject in pairs(PageObject.SubPages) do
                if SubPageObject.Button then
                    SubPageObject.Button.Visible = Visible
                end
            end
        end
    end

    local function ApiCreateLabel(Section, Data)
        local Name = tostring(ApiRead(Data, "Name", "Label"))
        local Row = CreateRow(Section.Body, 24)
        local Label = Create("TextLabel", {
            Parent = Row,
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSans,
            Text = Name,
            TextColor3 = PrimaryText,
            TextSize = 11,
            TextXAlignment = ApiRead(Data, "Alignment", "Left") == "Center" and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left,
            ZIndex = 8
        })
        RegisterControl(Section, Row, Name)
        local Object = {Row = Row, Label = Label}
        function Object:Set(Value)
            Label.Text = tostring(Value)
        end
        function Object:Colorpicker(ColorData)
            return ApiCreateColorpicker(Section, ColorData, Row)
        end
        function Object:Keybind(KeyData)
            return ApiCreateKeybind(Section, KeyData, Row)
        end
        return Object
    end

    function ApiCreateColorpicker(Section, Data, ExistingRow)
        Data = Data or {}
        local Name = tostring(ApiRead(Data, "Name", "Color"))
        local Flag = ApiNormalizeFlag(Data, Name)
        local Default = ApiRead(Data, "Default", Accent)
        local Callback = ApiRead(Data, "Callback")
        local Row = ExistingRow or CreateRow(Section.Body, 27)
        if not ExistingRow then
            Create("TextLabel", {
                Parent = Row,
                Size = UDim2.new(1, -34, 1, 0),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSans,
                Text = Name,
                TextColor3 = PrimaryText,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 8
            })
            RegisterControl(Section, Row, Name)
        end
        local Button = Create("TextButton", {
            Parent = Row,
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -1, 0.5, 0),
            Size = UDim2.fromOffset(13, 13),
            BackgroundColor3 = typeof(Default) == "Color3" and Default or Accent,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            ZIndex = 10
        })
        Corner(Button, 100)
        local BorderStroke = Stroke(Button, Color3.fromRGB(224, 224, 228), 0.16, 1)
        local Glow = Menu:AddSoftGlow(Button, 10, 8, 0.20, false)
        local Value = typeof(Default) == "Color3" and Default or Accent
        local Alpha = math.clamp(tonumber(ApiRead(Data, "Alpha", 1)) or 1, 0, 1)
        local Object = {Button = Button, Glow = Glow, Stroke = BorderStroke, Flag = Flag}
        Menu.Flags[Flag] = Value
        function Object:Set(NewValue, NewAlpha)
            if typeof(NewValue) ~= "Color3" then
                return
            end
            Value = NewValue
            if NewAlpha ~= nil then
                Alpha = math.clamp(tonumber(NewAlpha) or Alpha, 0, 1)
            end
            Menu.Flags[Flag] = NewValue
            Button.BackgroundColor3 = NewValue
            Button.BackgroundTransparency = 1 - Alpha
            if Glow then
                Glow.ImageColor3 = NewValue
                Glow.ImageTransparency = 0.28 - (Alpha * 0.10)
            end
            if type(Callback) == "function" then
                task.spawn(Callback, NewValue, Alpha)
            end
        end
        function Object:Get()
            return Value, Alpha
        end
        Menu.Setters[Flag] = function(NewValue)
            Object:Set(NewValue)
        end
        Bind(Button.MouseButton1Click:Connect(function()
            Menu.OpenColorPicker(Button, Value, Alpha, function(NewColor, NewAlpha)
                Object:Set(NewColor, NewAlpha)
            end, Glow, BorderStroke, false, nil, Flag)
        end))
        Bind(Button.MouseEnter:Connect(function()
            Tween(BorderStroke, 0.12, {Transparency = 0.08})
            if not (Menu.SettingsUI.ColorPickerContainer.Visible and Menu.SettingsUI.PickerAnchor == Button) and Glow then
                Tween(Glow, 0.12, {ImageTransparency = 0.20})
            end
        end))
        Bind(Button.MouseLeave:Connect(function()
            local Active = Menu.SettingsUI.ColorPickerContainer.Visible and Menu.SettingsUI.PickerAnchor == Button
            Tween(BorderStroke, 0.12, {Transparency = Active and 0.08 or 0.16})
            if not Active and Glow then
                Tween(Glow, 0.12, {ImageTransparency = 0.28 - (Alpha * 0.10)})
            end
        end))
        Object:Set(Value, Alpha)
        return Object
    end

    function ApiCreateKeybind(Section, Data, ExistingRow, TargetFlag, TargetName)
        Data = Data or {}

        local Name = tostring(ApiRead(Data, "Name", "Keybind"))
        local DeclaredFlag = ApiNormalizeFlag(Data, Name)
        local Flag = TargetFlag and tostring(TargetFlag) or tostring(DeclaredFlag)
        local Default = ApiRead(Data, "Default", "None")
        local Mode = tostring(ApiRead(Data, "Mode", "Toggle")) == "Hold" and "Hold" or "Toggle"
        local Callback = ApiRead(Data, "Callback")
        local GateFlag = ApiRead(Data, "EnabledFlag", ApiRead(Data, "GateFlag"))

        if Mode ~= "Hold" then
            GateFlag = nil
        elseif GateFlag ~= nil then
            GateFlag = tostring(GateFlag)
        end

        local Row = ExistingRow or CreateRow(Section.Body, 27)

        if not ExistingRow then
            Create("TextLabel", {
                Parent = Row,
                Size = UDim2.new(1, -34, 1, 0),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSans,
                Text = Name,
                TextColor3 = PrimaryText,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 8
            })
            RegisterControl(Section, Row, Name)
        end

        if not TargetFlag then
            Menu.Flags[Flag] = Menu.Flags[Flag] == true

            Menu.Setters[Flag] = function(Value)
                local State = Value == true
                Menu.Flags[Flag] = State

                if type(Callback) == "function" then
                    task.spawn(Callback, State)
                end

                if Menu.BindSystem.NotifyFlagChanged then
                    Menu.BindSystem.NotifyFlagChanged(Flag, State)
                end
            end
        end

        Menu.BindSystem.RegisterTarget(
            Flag,
            TargetName or Name,
            GateFlag,
            TargetFlag and DeclaredFlag or nil
)
        Menu.BindSystem.NormalizeStorage()

        local GearButton, GearIcon = CreateGear(
            Row,
            TargetFlag and -38 or -10,
            13,
            TargetName or Name,
            Flag,
            {Type = "Boolean", GateFlag = GateFlag}
)

        if typeof(Default) == "EnumItem" then
            local KeyType

            if Default.EnumType == Enum.KeyCode then
                KeyType = "KeyCode"
            elseif Default.EnumType == Enum.UserInputType then
                KeyType = "UserInputType"
            end

            if KeyType then
                KeyType,
                    DefaultName =
                    Menu.BindSystem.CanonicalBindKey(
                        KeyType,
                        Default.Name
)

                local Binds = Menu.BindSystem.GetControlBinds(Flag)
                local Exists = false

                for _, BindData in ipairs(Binds) do
                    if BindData.KeyType == KeyType and BindData.Key == DefaultName then
                        Exists = true
                        if BindData.Mode == "Hold" then
                            BindData.GateFlag = GateFlag
                        else
                            BindData.GateFlag = nil
                        end
                        break
                    end
                end

                if not Exists then
                    Binds[#Binds + 1] = {
                        Id = tostring(os.clock()) .. tostring(math.random(1000, 9999)),
                        KeyType = KeyType,
                        Key = DefaultName,
                        Modifiers = {Ctrl = false, Shift = false, Alt = false},
                        Display = Menu.BindSystem.BuildBindDisplay(DefaultName, {}),
                        Mode = Mode,
                        ShowInBinds = true,
                        GateFlag = GateFlag
                    }
                end

                if Menu.KeybindListController and Menu.KeybindListController.MarkDirty then
                    Menu.KeybindListController.MarkDirty()
                end
            end
        end

        return {
            Button = GearButton,
            Icon = GearIcon,
            Flag = Flag,
            Set = function(Value)
                local Setter = Menu.Setters[Flag]
                if Setter then
                    Setter(Value)
                end
            end,
            Get = function()
                return Menu.Flags[Flag]
            end
        }
    end

    local ApiSectionMethods = {}
    ApiSectionMethods.__index = ApiSectionMethods

    function ApiSectionMethods:Toggle(Data)
        Data = Data or {}
        local Control = CreateToggle(self.Section, tostring(ApiRead(Data, "Name", "Toggle")), ApiRead(Data, "Default", false), ApiNormalizeFlag(Data, ApiRead(Data, "Name", "Toggle")), {
            Gear = ApiRead(Data, "Gear", false),
            Warning = ApiRead(Data, "Warning", false),
            Disabled = ApiRead(Data, "Disabled", false),
            Callback = ApiRead(Data, "Callback")
        })
        function Control:Keybind(KeyData)
            if not self._BindGear then
                self._BindGear = ApiCreateKeybind(self._Section, KeyData, self._Row, self._Flag, self._Name)
            end
            return self
        end
        function Control:Colorpicker(ColorData)
            ApiCreateColorpicker(self._Section or self.Section or self, ColorData)
            return self
        end
        Control._Section = self.Section
        Control._Row = Control.Row
        Control._Flag = Control.Flag
        Control._Name = Control.Name
        return Control
    end

    function ApiSectionMethods:Slider(Data)
        Data = Data or {}
        local Step = tonumber(ApiRead(Data, "Step", ApiRead(Data, "Decimals", 1))) or 1
        local Decimals = ApiRead(Data, "Precision")
        return CreateSlider(self.Section, tostring(ApiRead(Data, "Name", "Slider")), tonumber(ApiRead(Data, "Min", 0)) or 0, tonumber(ApiRead(Data, "Max", 100)) or 100, tonumber(ApiRead(Data, "Default", 0)) or 0, ApiNormalizeFlag(Data, ApiRead(Data, "Name", "Slider")), {
            Step = Step,
            Decimals = Decimals,
            Prefix = ApiRead(Data, "Prefix", ""),
            Suffix = ApiRead(Data, "Suffix", ""),
            Box = ApiRead(Data, "Box", true),
            Gear = ApiRead(Data, "Gear", false),
            Disabled = ApiRead(Data, "Disabled", false),
            Callback = ApiRead(Data, "Callback")
        })
    end

    function ApiSectionMethods:RangeSlider(Data)
        Data = Data or {}
        local Name = tostring(ApiRead(Data, "Name", "Range"))
        local Minimum = tonumber(ApiRead(Data, "Min", 0)) or 0
        local Maximum = tonumber(ApiRead(Data, "Max", 100)) or 100
        local Default = ApiRead(Data, "Default", {Minimum, Maximum})
        local DefaultMinimum = type(Default) == "table" and tonumber(Default[1] or Default.Minimum or Default.Min) or Minimum
        local DefaultMaximum = type(Default) == "table" and tonumber(Default[2] or Default.Maximum or Default.Max) or Maximum
        local BaseFlag = tostring(ApiRead(Data, "Flag", ApiNormalizeFlag(Data, Name)))
        local MinimumFlag = tostring(ApiRead(Data, "MinFlag", BaseFlag .. " Minimum"))
        local MaximumFlag = tostring(ApiRead(Data, "MaxFlag", BaseFlag .. " Maximum"))
        local Step = tonumber(ApiRead(Data, "Step", ApiRead(Data, "Decimals", 1))) or 1
        local Decimals = ApiRead(Data, "Precision")
        return CreateDualSlider(self.Section, Name, Minimum, Maximum, DefaultMinimum or Minimum, DefaultMaximum or Maximum, MinimumFlag, MaximumFlag, {
            Step = Step,
            Decimals = Decimals,
            Prefix = ApiRead(Data, "Prefix", ""),
            Suffix = ApiRead(Data, "Suffix", ""),
            Gear = ApiRead(Data, "Gear", false),
            Disabled = ApiRead(Data, "Disabled", false),
            Callback = ApiRead(Data, "Callback")
        })
    end

    function ApiSectionMethods:Dropdown(Data)
        Data = Data or {}
        if ApiRead(Data, "Multi", ApiRead(Data, "Multiple", false)) then
            return CreateMultiDropdown(self.Section, tostring(ApiRead(Data, "Name", "Dropdown")), ApiRead(Data, "Items", ApiRead(Data, "Values", {})), ApiRead(Data, "Default", {}), ApiNormalizeFlag(Data, ApiRead(Data, "Name", "Dropdown")), {
                Gear = ApiRead(Data, "Gear", false),
                Disabled = ApiRead(Data, "Disabled", false),
                Max = ApiRead(Data, "Max"),
                AllowEmpty = ApiRead(Data, "AllowEmpty", true),
                Placeholder = ApiRead(Data, "Placeholder", "None"),
                Callback = ApiRead(Data, "Callback")
            })
        end
        return CreateDropdown(self.Section, tostring(ApiRead(Data, "Name", "Dropdown")), ApiRead(Data, "Items", ApiRead(Data, "Values", {})), ApiRead(Data, "Default"), ApiNormalizeFlag(Data, ApiRead(Data, "Name", "Dropdown")), {
            Gear = ApiRead(Data, "Gear", false),
            Disabled = ApiRead(Data, "Disabled", false),
            Callback = ApiRead(Data, "Callback")
        })
    end

    function ApiSectionMethods:MultiDropdown(Data)
        Data = Data or {}
        return CreateMultiDropdown(self.Section, tostring(ApiRead(Data, "Name", "Multi Dropdown")), ApiRead(Data, "Items", ApiRead(Data, "Values", {})), ApiRead(Data, "Default", {}), ApiNormalizeFlag(Data, ApiRead(Data, "Name", "Multi Dropdown")), {
