                TextSize = 10,
                ZIndex = 150
            })
            Corner(Button, 5)
            Stroke(Button, Border, 0.56, 1)

            Bind(Button.MouseEnter:Connect(function()
                Tween(Button, 0.12, {
                    BackgroundTransparency = 0.32,
                    TextColor3 = PrimaryText
                })
            end))

            Bind(Button.MouseLeave:Connect(function()
                Tween(Button, 0.12, {
                    BackgroundTransparency = 0.50,
                    TextColor3 = MutedText
                })
            end))

            Bind(Button.MouseButton1Click:Connect(function()
                local Selected = State.Selected
                local Callback = State[CallbackKey]
                if Selected and type(Callback) == "function" then
                    task.spawn(Callback, Selected)
                end
            end))

            return Button
        end

        MakeAction("Spectate", 0, 0, "Spectate")
        MakeAction("Unspectate", 0.5, 0, "Unspectate")

        local function NormalizeStatus(Status)
            Status = tostring(Status or "None")
            if Status == "Priority"
                or Status == "Whitelist"
                or Status == "Enemy"
            then
                return Status
            end
            return "None"
        end

        local function GetStatus(Player)
            if not Player then
                return "None"
            end

            if Player == LocalPlayer then
                return "Client"
            end

            return NormalizeStatus(
                Menu.PlayerStatuses[
                    tonumber(Player.UserId) or 0
                ]
)
        end

        local function CloseStatusDropdown()
            State.DropdownOpen = false
            StatusDropdown.Visible = false
            StatusExpandIndicator:SetOpened(false)
            ActionHolder.Position = UDim2.fromOffset(0, 215)
        end

        local RefreshRows
        local RefreshSelected
        local FriendCache = {}
        local FriendPending = {}

        local function QueueFriendCheck(Player)
            if not Player or Player == LocalPlayer then
                return
            end

            local UserId = tonumber(Player.UserId) or 0
            if UserId <= 0 or FriendCache[UserId] ~= nil or FriendPending[UserId] then
                return
            end

            FriendPending[UserId] = true

            task.spawn(function()
                local IsFriend = false
                local Success, Result = Library.Call(
                    LocalPlayer.IsFriendsWith,
                    LocalPlayer,
                    UserId
)

                if Success then
                    IsFriend = Result == true
                end

                FriendPending[UserId] = nil
                FriendCache[UserId] = IsFriend

                if Player.Parent == Players then
                    if RefreshRows then
                        task.defer(RefreshRows)
                    end
                    if State.Selected == Player and RefreshSelected then
                        RefreshSelected(false)
                    end
                end
            end)
        end

        local function IsCachedFriend(Player)
            if not Player or Player == LocalPlayer then
                return false
            end

            local UserId = tonumber(Player.UserId) or 0
            if FriendCache[UserId] == nil then
                QueueFriendCheck(Player)
                return false
            end

            return FriendCache[UserId] == true
        end

        local function GetPlayerPresentation(Player)
            local Status = GetStatus(Player)

            if Status == "Client" then
                return {
                    Status = Status,
                    Label = "Client",
                    Rank = 0,
                    Style = GetStatusStyle("Client"),
                    Highlight = true
                }
            end

            if Status == "Whitelist" then
                return {
                    Status = Status,
                    Label = "Whitelist",
                    Rank = 1,
                    Style = GetStatusStyle("Whitelist"),
                    Highlight = true
                }
            end

            if Status == "Priority" then
                return {
                    Status = Status,
                    Label = "Priority",
                    Rank = 2,
                    Style = GetStatusStyle("Priority"),
                    Highlight = true
                }
            end

            if Status == "Enemy" then
                return {
                    Status = Status,
                    Label = "Enemy",
                    Rank = 3,
                    Style = GetStatusStyle("Enemy"),
                    Highlight = true
                }
            end

            if IsCachedFriend(Player) then
                return {
                    Status = "None",
                    Label = "Friend",
                    Rank = 4,
                    Style = GetStatusStyle("Friend"),
                    Highlight = true
                }
            end

            return {
                Status = "None",
                Label = "None",
                Rank = 5,
                Style = GetStatusStyle("None"),
                Highlight = false
            }
        end

        local function SetStatus(Player, Status, Silent)
            if not Player or Player == LocalPlayer then
                return "Client"
            end

            Status = NormalizeStatus(Status)
            Menu.PlayerStatuses[
                tonumber(Player.UserId) or 0
            ] = Status

            if not Silent and type(State.StatusChanged) == "function" then
                task.spawn(State.StatusChanged, Player, Status)
            end

            if RefreshRows then RefreshRows() end
            if RefreshSelected then RefreshSelected(false) end
            return Status
        end

        local StatusOptionVisuals = {}

        local function UpdateStatusVisual(Status)
            local Style = GetStatusStyle(Status)

            StatusButton.Text = tostring(Status)
            StatusButton.TextColor3 = Style.Text

            for Name, Visual in pairs(StatusOptionVisuals) do
                local Active = Name == Status
                    or (Status == "Friend" and Name == "None")

                Visual.Text.TextColor3 =
                    Active
                    and PrimaryText
                    or MutedText

                Visual.Text.Font =
                    Active
                    and Enum.Font.BuilderSansBold
                    or Enum.Font.BuilderSansMedium

                Visual.Button.BackgroundTransparency =
                    Active
                    and 0.82
                    or 1
            end
        end

        for Index, Status in ipairs(StatusItems) do
            local Option = Create("TextButton", {
                Parent = StatusDropdown,
                Size = UDim2.new(1, 0, 0, 26),
                BackgroundColor3 = SurfaceAlt,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Text = "",
                LayoutOrder = Index,
                ZIndex = 161
            })

            local OptionText = Create("TextLabel", {
                Parent = Option,
                Position = UDim2.fromOffset(10, 0),
                Size = UDim2.new(1, -35, 1, 0),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSansMedium,
                Text = Status,
                TextColor3 = MutedText,
                TextSize = 9,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 162
            })

            StatusOptionVisuals[Status] = {
                Button = Option,
                Text = OptionText
            }

            Bind(Option.MouseEnter:Connect(function()
                Tween(Option, 0.08, {
                    BackgroundTransparency = 0.90
                })
                Tween(OptionText, 0.08, {
                    TextColor3 = PrimaryText
                })
            end))

            Bind(Option.MouseLeave:Connect(function()
                local Active =
                    State.Selected
                    and GetStatus(State.Selected) == Status

                Tween(Option, 0.08, {
                    BackgroundTransparency =
                        Active and 0.82 or 1
                })

                Tween(OptionText, 0.08, {
                    TextColor3 =
                        Active
                        and PrimaryText
                        or MutedText
                })
            end))

            Bind(Option.MouseButton1Click:Connect(function()
                if State.Selected and State.Selected ~= LocalPlayer then
                    SetStatus(State.Selected, Status, false)
                end
                CloseStatusDropdown()
            end))
        end

        local ThumbnailCache = {}
        local LocalThumbnail = nil

        if LocalPlayer then
            local UserId =
                tonumber(LocalPlayer.UserId)
                or 0

            local Direct =
                "rbxthumb://type=AvatarHeadShot&id="
                .. tostring(UserId)
                .. "&w=150&h=150"

            ThumbnailCache[UserId] = Direct

            task.spawn(function()
                local Success, Content =
                    Library.Call(
                        Players.GetUserThumbnailAsync,
                        Players,
                        UserId,
                        Enum.ThumbnailType.HeadShot,
                        Enum.ThumbnailSize.Size150x150
)

                if Success
                    and type(Content) == "string"
                    and Content ~= ""
                then
                    LocalThumbnail = Content
                    ThumbnailCache[UserId] = Content

                    if State.Selected == LocalPlayer then
                        Avatar.Image = Content
                        AvatarLoading.Visible = false
                    end
                end
            end)
        end

        local function LoadAvatar(Player)
            State.ThumbnailSerial += 1
            local Serial = State.ThumbnailSerial

            Avatar.Image = ""
            AvatarLoading.Visible = true

            if not Player then
                return
            end

            local UserId =
                tonumber(Player.UserId)
                or 0

            local Cached =
                ThumbnailCache[UserId]

            if Player == LocalPlayer then
                local SettingsAvatar =
                    Menu.SettingsUI
                    and Menu.SettingsUI.ProfileAvatar

                local SettingsImage =
                    SettingsAvatar
                    and SettingsAvatar.Image

                if type(SettingsImage) == "string"
                    and SettingsImage ~= ""
                then
                    Cached = SettingsImage
                    ThumbnailCache[UserId] = SettingsImage
                elseif type(LocalThumbnail) == "string"
                    and LocalThumbnail ~= ""
                then
                    Cached = LocalThumbnail
                end
            end

            if type(Cached) == "string"
                and Cached ~= ""
            then
                Avatar.Image = Cached
                AvatarLoading.Visible = false
                return
            end

            local Direct =
                "rbxthumb://type=AvatarHeadShot&id="
                .. tostring(UserId)
                .. "&w=150&h=150"

            Avatar.Image = Direct
            AvatarLoading.Visible = false

            task.spawn(function()
                local Success, Content =
                    Library.Call(
                        Players.GetUserThumbnailAsync,
                        Players,
                        UserId,
                        Enum.ThumbnailType.HeadShot,
                        Enum.ThumbnailSize.Size150x150
)

                if Success
                    and type(Content) == "string"
                    and Content ~= ""
                then
                    ThumbnailCache[UserId] =
                        Content

                    if Serial == State.ThumbnailSerial
                        and State.Selected == Player
                    then
                        Avatar.Image = Content
                        AvatarLoading.Visible = false
                    end
                end
            end)
        end

        RefreshSelected = function(LoadImage)
            local Player = State.Selected
            local HasPlayer =
                Player ~= nil
                and Player.Parent == Players

            EmptyLabel.Visible = not HasPlayer
            Profile.Visible = HasPlayer
            CloseStatusDropdown()

            if not HasPlayer then
                PlayerName.Text = ""
                PlayerInfo.Text = ""
                Avatar.Image = ""
                AvatarLoading.Visible = false
                return
            end

            local Presentation = GetPlayerPresentation(Player)

            PlayerName.Text =
                tostring(Player.DisplayName or Player.Name)
            PlayerName.TextColor3 = Presentation.Highlight
                and Presentation.Style.Text
                or PrimaryText

            if Player.DisplayName ~= Player.Name then
                PlayerInfo.Text =
                    "@"
                    .. tostring(Player.Name)
                    .. "  ·  "
                    .. tostring(Player.UserId)
            else
                PlayerInfo.Text =
                    tostring(Player.UserId)
            end

            UpdateStatusVisual(Presentation.Label)

            StatusButton.Active =
                Player ~= LocalPlayer

            StatusButton.AutoButtonColor = false

            if LoadImage ~= false then
                LoadAvatar(Player)
            end
        end

        local function SelectPlayer(Player)
            if Player and Player.Parent ~= Players then
                Player = nil
            end

            State.Selected = Player
            RefreshRows()
            RefreshSelected(true)
        end

        local function CreateRow(Player, Index)
            local UserId = tonumber(Player and Player.UserId) or 0
            if UserId <= 0 then
                return
            end

            local Existing = State.Rows[UserId]
            if Existing and Existing.Parent then
                Existing:Destroy()
            end

            local Selected =
                State.Selected == Player
            local Presentation = GetPlayerPresentation(Player)
            local Style = Presentation.Style

            local Row = Create("TextButton", {
                Parent = Scroll,
                Size = UDim2.new(1, -3, 0, 31),
                BackgroundColor3 = SurfaceAlt,
                BackgroundTransparency = Selected and 0.78 or 1,
                BorderSizePixel = 0,
                AutoButtonColor = false,
                Text = "",
                LayoutOrder = Index,
                ZIndex = 149
            })
            Corner(Row, 4)

            if Selected then
                Create("Frame", {
                    Parent = Row,
                    Position = UDim2.fromOffset(0, 5),
                    Size = UDim2.fromOffset(2, 21),
                    BackgroundColor3 = Accent,
                    BorderSizePixel = 0,
                    ZIndex = 152
                })
            end

            local MiniAvatarHolder = Create("Frame", {
                Parent = Row,
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 9, 0.5, 0),
                Size = UDim2.fromOffset(18, 18),
                BackgroundColor3 = SurfaceAlt,
                BackgroundTransparency = 0.20,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                ZIndex = 151
            })
            Corner(MiniAvatarHolder, 999)

            local MiniAvatar = Create("ImageLabel", {
                Parent = MiniAvatarHolder,
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Image = "rbxthumb://type=AvatarHeadShot&id="
                    .. tostring(Player.UserId)
                    .. "&w=48&h=48",
                ScaleType = Enum.ScaleType.Crop,
                ZIndex = 152
            })
            Corner(MiniAvatar, 999)

            Create("TextLabel", {
                Parent = Row,
                Position = UDim2.fromOffset(34, 0),
                Size = UDim2.new(1, -122, 1, 0),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSansMedium,
                Text = tostring(Player.DisplayName or Player.Name),
                TextColor3 = Presentation.Highlight
                    and Style.Text
                    or (Selected and PrimaryText or Color3.fromRGB(190, 200, 205)),
                TextSize = 9,
                TextTruncate = Enum.TextTruncate.AtEnd,
                TextXAlignment = Enum.TextXAlignment.Left,
                ZIndex = 151
            })

            Create("TextLabel", {
                Parent = Row,
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.fromOffset(70, 16),
                BackgroundTransparency = 1,
                Font = Enum.Font.BuilderSansMedium,
                Text = Presentation.Label,
                TextColor3 = Style.Text,
                TextSize = 8,
                TextXAlignment = Enum.TextXAlignment.Right,
                ZIndex = 151
            })

            Bind(Row.MouseEnter:Connect(function()
                if State.Selected ~= Player then
                    Tween(Row, 0.08, {
                        BackgroundTransparency = 0.90
                    })
                end
            end))

            Bind(Row.MouseLeave:Connect(function()
                if State.Selected ~= Player then
                    Tween(Row, 0.08, {
                        BackgroundTransparency = 1
                    })
                end
            end))

            Bind(Row.MouseButton1Click:Connect(function()
                SelectPlayer(Player)
            end))

            Row.Name = "PlayerRow_" .. tostring(UserId)
            State.Rows[UserId] = Row
        end

        RefreshRows = function()
            if State.Refreshing then
                State.RefreshQueued = true
                return
            end

            State.Refreshing = true
            State.RefreshGeneration += 1
            local Generation = State.RefreshGeneration

            for _, Child in ipairs(Scroll:GetChildren()) do
                if Child ~= RowLayout and Child:IsA("GuiObject") then
                    Child:Destroy()
                end
            end
            table.clear(State.Rows)

            local Query =
                string.lower(
                    tostring(State.Search or "")
)

            local List = Players:GetPlayers()

            for _, Player in ipairs(List) do
                QueueFriendCheck(Player)
            end

            table.sort(List, function(A, B)
                local APresentation = GetPlayerPresentation(A)
                local BPresentation = GetPlayerPresentation(B)

                if APresentation.Rank ~= BPresentation.Rank then
                    return APresentation.Rank < BPresentation.Rank
                end

                local ADisplay = string.lower(tostring(A.DisplayName or A.Name))
                local BDisplay = string.lower(tostring(B.DisplayName or B.Name))
                if ADisplay ~= BDisplay then
                    return ADisplay < BDisplay
                end

                return string.lower(A.Name) < string.lower(B.Name)
            end)

            CountLabel.Text =
                "Players ["
                .. tostring(#List)
                .. "]"

            local Index = 0
            local SeenUserIds = {}

            for _, Player in ipairs(List) do
                local UserId = tonumber(Player.UserId) or 0
                local Haystack =
                    string.lower(
                        tostring(Player.Name)
                        .. " "
                        .. tostring(Player.DisplayName)
)

                if UserId > 0
                    and not SeenUserIds[UserId]
                    and (Query == ""
                        or string.find(
                            Haystack,
                            Query,
                            1,
                            true
))
                then
                    SeenUserIds[UserId] = true
                    Index += 1
                    CreateRow(Player, Index)
                end
            end

            if Generation == State.RefreshGeneration then
                State.Refreshing = false
            end

            if State.RefreshQueued then
                State.RefreshQueued = false
                task.defer(RefreshRows)
            end
        end

        Bind(StatusButton.MouseButton1Click:Connect(function()
            if not State.Selected
                or State.Selected == LocalPlayer
            then
                return
            end

            State.DropdownOpen =
                not State.DropdownOpen

            StatusDropdown.Visible =
                State.DropdownOpen

            StatusExpandIndicator:SetOpened(
                State.DropdownOpen
)

            Tween(StatusButton, 0.10, {
                BackgroundTransparency =
                    State.DropdownOpen
                    and 0.28
                    or 0.42
            })

            ActionHolder.Position =
                State.DropdownOpen
                and UDim2.fromOffset(0, 316)
                or UDim2.fromOffset(0, 215)
        end))

        Bind(SearchBox:GetPropertyChangedSignal("Text"):Connect(function()
            State.Search = SearchBox.Text
            RefreshRows()
        end))

        Bind(Players.PlayerAdded:Connect(function()
            task.defer(RefreshRows)
        end))

        Bind(Players.PlayerRemoving:Connect(function(Player)
            local UserId = tonumber(Player.UserId) or 0
            Menu.PlayerStatuses[UserId] = nil
            FriendCache[UserId] = nil
            FriendPending[UserId] = nil

            if State.Selected == Player then
                State.Selected = nil
                RefreshSelected(true)
            end

            task.defer(RefreshRows)
        end))

        local Dragging = false
        local DragStart = Vector2.zero
        local DragPosition = Root.Position

        Bind(Header.InputBegan:Connect(function(Input)
            if Input.UserInputType == Enum.UserInputType.MouseButton1 then
                Dragging = true
                DragStart = UserInputService:GetMouseLocation()
                DragPosition = Root.Position
            end
        end))

        Bind(UserInputService.InputChanged:Connect(function(Input)
            if Dragging
                and Input.UserInputType == Enum.UserInputType.MouseMovement
            then
                local Delta =
                    UserInputService:GetMouseLocation()
                    - DragStart

                Root.Position =
                    UDim2.new(
                        DragPosition.X.Scale,
                        DragPosition.X.Offset + Delta.X,
                        DragPosition.Y.Scale,
                        DragPosition.Y.Offset + Delta.Y
)
            end
        end))

        Bind(UserInputService.InputEnded:Connect(function(Input)
            if Dragging
                and Input.UserInputType == Enum.UserInputType.MouseButton1
            then
                Dragging = false
                SavedPositions.PlayerList =
                    EncodePosition(Root.Position)
            end
        end))

        local Controller = {}

        function Controller:SetVisibility(Value)
            State.Visible = Value == true
            Menu.Flags.PlayerListVisible = State.Visible
            Root.Visible = State.Visible

            if RootGlow then
                RootGlow.Visible = Root.Visible
            end

            if Menu.QuickPanelController and Menu.QuickPanelController.Refresh then
                Menu.QuickPanelController.Refresh()
            end
        end

        function Controller:SetMenuVisible(Value)
            State.MenuVisible = true
            Root.Visible = State.Visible

            if RootGlow then
                RootGlow.Visible = Root.Visible
            end
        end

        function Controller:SetScale(Value)
            local Number = tonumber(Value) or 100
            if Number <= 2 then
                Number *= 100
            end
            Number = math.clamp(Number, 70, 135)
            State.Scale = Number / 100
            RootScale.Scale = State.Scale
            Menu.Flags.PlayerListScale = Number
            SavedPositions.PlayerListScale = Number
        end

        function Controller:GetStatus(Player)
            return GetStatus(Player)
        end

        function Controller:SetStatus(Player, Status)
            return SetStatus(Player, Status, false)
        end

        function Controller:SelectPlayer(Player)
            SelectPlayer(Player)
        end

        function Controller:Refresh()
            RefreshRows()
            RefreshSelected(false)
        end

        function Controller:Destroy()
            State.Visible = false
            State.RefreshQueued = false
            State.Refreshing = false
            State.RefreshGeneration += 1
            if RootGlow and RootGlow.Parent then
                RootGlow:Destroy()
            end
            if Root and Root.Parent then
                Root:Destroy()
            end
            Menu.PlayerListController = nil
        end

        Controller.Root = Root
        Controller.State = State

        Menu.PlayerListController = Controller

        RefreshRows()
        RefreshSelected(true)
        Controller:SetScale(State.Scale * 100)
        Controller:SetVisibility(State.Visible)

        return Controller
    end

    function Library:GetPlayerStatus(PlayerOrUserId)
        if typeof(PlayerOrUserId) == "Instance"
            and PlayerOrUserId:IsA("Player")
        then
            if PlayerOrUserId == Players.LocalPlayer then
                return "Client"
            end
            local UserId = tonumber(PlayerOrUserId.UserId) or 0
            local Value = tostring(Menu.PlayerStatuses[UserId] or "None")
            if Value == "Priority" or Value == "Whitelist" or Value == "Enemy" then
                return Value
            end
            return "None"
        end

        local UserId = tonumber(PlayerOrUserId)
        if not UserId then return "None" end
        if Players.LocalPlayer
            and UserId == Players.LocalPlayer.UserId
        then
            return "Client"
        end

        local Value = tostring(Menu.PlayerStatuses[UserId] or "None")
        if Value == "Priority" or Value == "Whitelist" or Value == "Enemy" then
            return Value
        end
        return "None"
    end

    function Library:SetPlayerStatus(PlayerOrUserId, Status)
        local Player = nil
        local UserId = nil

        if typeof(PlayerOrUserId) == "Instance"
            and PlayerOrUserId:IsA("Player")
        then
            Player = PlayerOrUserId
            UserId = tonumber(Player.UserId)
        else
            UserId = tonumber(PlayerOrUserId)
            if UserId then
                for _, Candidate in ipairs(Players:GetPlayers()) do
                    if Candidate.UserId == UserId then
                        Player = Candidate
                        break
                    end
                end
            end
        end

        if not UserId
            or Players.LocalPlayer
                and UserId == Players.LocalPlayer.UserId
        then
            return "Client"
        end

        Status = tostring(Status or "None")
        if Status ~= "Priority"
            and Status ~= "Whitelist"
            and Status ~= "Enemy"
        then
            Status = "None"
        end

        Menu.PlayerStatuses[UserId] = Status

        if Menu.PlayerListController then
            if Player
                and Menu.PlayerListController.SetStatus
            then
                return Menu.PlayerListController:SetStatus(Player, Status)
            end
            if Menu.PlayerListController.Refresh then
                Menu.PlayerListController:Refresh()
            end
        end

        return Status
    end

    function Library:PlayerList(Data)
        return CreateAtramentaPlayerList(Data)
    end

