    local MenuIconMap = {
        Combat = "crosshair",
        Visuals = "eye",
        Movement = "activity",
        World = "globe",
        Utility = "wrench",
        Settings = "settings",
        Players = "users",
        Cloud = "cloud",
        Config = "sliders",
        Misc = "boxes"
    }

    local NativeWindowObject = nil
    local NativeWindow = nil
    local NativeAccentRegistered = false

    local function InvokeCallback(Callback, ...)
        if type(Callback) == "function" then
            task.spawn(Callback, ...)
        end
    end

    local function RegisterNativeFlag(Flag, Default, Setter)
        Flag = tostring(Flag or "")
        if Flag == "" then return end
        Menu.Flags[Flag] = CloneFlagValue(Default)
        Menu.DefaultFlagKnown[Flag] = true
        Menu.DefaultFlags[Flag] = CloneFlagValue(Default)
        if type(Setter) == "function" then
            Menu.Setters[Flag] = Setter
        end
    end

    local function ApplyControlAliases(Control)
        if type(Control) ~= "table" then return Control end
        if type(Control.SetValue) == "function" and type(Control.Set) ~= "function" then
            Control.Set = function(Self, Value, ...)
                return Self:SetValue(Value, ...)
            end
        end
        if type(Control.GetValue) == "function" and type(Control.Get) ~= "function" then
            Control.Get = function(Self)
                return Self:GetValue()
            end
        end
        return Control
    end

    local function GetNativeSection(Self)
        return Self.Native or Self.Section
    end

    local function GetDropdownValues(Data)
        local Values = ApiRead(Data, "Items", ApiRead(Data, "Values", {}))
        if type(Values) ~= "table" then return {} end
        local Result = {}
        for _, Value in ipairs(Values) do
            if type(Value) == "table" then
                Result[#Result + 1] = tostring(Value.Name or Value.Text or Value.Value or Value[1] or "Item")
            else
                Result[#Result + 1] = tostring(Value)
            end
        end
        return Result
    end

    function ApiSubPageMethods:Section(Data)
        Data = Data or {}
        local SideValue = ApiRead(Data, "Side", nil)
        local Side
        if tonumber(SideValue) == 2 or tostring(SideValue):lower() == "right" then
            Side = "right"
        elseif tonumber(SideValue) == 1 or tostring(SideValue):lower() == "left" then
            Side = "left"
        else
            self.NextSide = self.NextSide == "left" and "right" or "left"
            Side = self.NextSide
        end
        local Native = self.Native:DrawSection({
            Name = tostring(ApiRead(Data, "Name", "Section")),
            Position = Side
        })
        return setmetatable({Section = Native, Native = Native}, ApiSectionMethods)
    end

    function ApiPageMethods:SubPage(Data)
        Data = Data or {}
        local Name = tostring(ApiRead(Data, "Name", "General"))
        if self.SubPages[Name] then return self.SubPages[Name] end
        local Native = self.Native:DrawTab({
            Name = Name,
            Type = tostring(ApiRead(Data, "Type", "Double")),
            EnableScrolling = ApiRead(Data, "EnableScrolling", true) ~= false
        })
        local Object = setmetatable({
            Name = Name,
            PageName = self.Name,
            Native = Native,
            Sections = {},
            NextSide = "right"
        }, ApiSubPageMethods)
        self.SubPages[Name] = Object
        if not self.FirstSubPage then
            self.FirstSubPage = Object
            self.ActiveSubPage = Name
        end
        return Object
    end

    function ApiPageMethods:Section(Data)
        if not self.FirstSubPage then
            self:SubPage({Name = "General"})
        end
        return self.FirstSubPage:Section(Data)
    end

    function ApiWindowMethods:Page(Data)
        Data = Data or {}
        local Name = tostring(ApiRead(Data, "Name", "Page"))
        if self.Pages[Name] then return self.Pages[Name] end
        local IconName = tostring(ApiRead(Data, "Icon", MenuIconMap[Name] or "circle")):lower()
        IconName = IconName:gsub("^lucide%-", "")
        local Native = self.Native:DrawContainerTab({Name = Name, Icon = IconName})
        local Object = setmetatable({Name = Name, Native = Native, SubPages = {}}, ApiPageMethods)
        self.Pages[Name] = Object
        self.FirstPage = self.FirstPage or Name
        return Object
    end

    function ApiSectionMethods:Toggle(Data)
        Data = Data or {}
        local NativeSection = GetNativeSection(self)
        local Name = tostring(ApiRead(Data, "Name", "Toggle"))
        local Flag = ApiNormalizeFlag(Data, Name)
        local Default = ApiRead(Data, "Default", false) == true
        local Callback = ApiRead(Data, "Callback")
        local Control
        Control = NativeSection:AddToggle({
            Name = Name,
            Default = Default,
            Flag = nil,
            Risky = ApiRead(Data, "Risky", ApiRead(Data, "Warning", false)) == true,
            Callback = function(Value)
                Value = Value == true
                Menu.Flags[Flag] = Value
                InvokeCallback(Callback, Value)
            end
        })
        ApplyControlAliases(Control)
        RegisterNativeFlag(Flag, Default, function(Value) Control:SetValue(Value == true) end)
        Control.Flag = Flag
        Control.Name = Name

        function Control:Keybind(KeyData)
            KeyData = KeyData or {}
            if not self.Link or type(self.Link.AddKeybind) ~= "function" then return self end
            local BindName = tostring(ApiRead(KeyData, "Name", Name .. " Bind"))
            local BindFlag = tostring(ApiRead(KeyData, "Flag", Flag .. " Bind"))
            local DefaultBind = ApiRead(KeyData, "Default", ApiRead(KeyData, "Key", nil))
            local BindCallback = ApiRead(KeyData, "Callback")
            local BindControl = self.Link:AddKeybind({
                Name = BindName,
                Default = DefaultBind,
                Flag = nil,
                Blacklist = ApiRead(KeyData, "Blacklist", {Enum.KeyCode.Unknown}),
                Callback = function(Value)
                    Menu.Flags[BindFlag] = Value
                    InvokeCallback(BindCallback, Value)
                end
            })
            ApplyControlAliases(BindControl)
            RegisterNativeFlag(BindFlag, DefaultBind, function(Value) BindControl:SetValue(Value) end)
            self.BindControl = BindControl
            return self
        end

        function Control:Colorpicker(ColorData)
            ColorData = ColorData or {}
            if not self.Link or type(self.Link.AddColorPicker) ~= "function" then return self end
            local ColorFlag = tostring(ApiRead(ColorData, "Flag", Flag .. " Color"))
            local DefaultColor = ApiRead(ColorData, "Default", Color3.new(1, 1, 1))
            local Transparency = tonumber(ApiRead(ColorData, "Transparency", 0)) or 0
            local ColorCallback = ApiRead(ColorData, "Callback")
            local ColorControl = self.Link:AddColorPicker({
                Default = DefaultColor,
                Transparency = Transparency,
                Flag = nil,
                Callback = function(Value, Alpha)
                    Menu.Flags[ColorFlag] = Value
                    InvokeCallback(ColorCallback, Value, Alpha)
                end
            })
            ApplyControlAliases(ColorControl)
            RegisterNativeFlag(ColorFlag, DefaultColor, function(Value) ColorControl:SetValue(Value, Transparency) end)
            self.ColorControl = ColorControl
            return self
        end

        return Control
    end

    function ApiSectionMethods:Slider(Data)
        Data = Data or {}
        local NativeSection = GetNativeSection(self)
        local Name = tostring(ApiRead(Data, "Name", "Slider"))
        local Flag = ApiNormalizeFlag(Data, Name)
        local Minimum = tonumber(ApiRead(Data, "Min", 0)) or 0
        local Maximum = tonumber(ApiRead(Data, "Max", 100)) or 100
        local Default = tonumber(ApiRead(Data, "Default", Minimum)) or Minimum
        local Callback = ApiRead(Data, "Callback")
        local Decimals = tonumber(ApiRead(Data, "Precision", ApiRead(Data, "Decimals", 0))) or 0
        local Suffix = tostring(ApiRead(Data, "Suffix", ApiRead(Data, "Type", "")) or "")
        local Control = NativeSection:AddSlider({
            Name = Name,
            Min = Minimum,
            Max = Maximum,
            Default = Default,
            Type = Suffix,
            Round = Decimals,
            Callback = function(Value)
                Menu.Flags[Flag] = Value
                InvokeCallback(Callback, Value)
            end
        })
        ApplyControlAliases(Control)
        RegisterNativeFlag(Flag, Default, function(Value) Control:SetValue(tonumber(Value) or Default) end)
        Control.Flag = Flag
        return Control
    end

    function ApiSectionMethods:RangeSlider(Data)
        Data = Data or {}
        local Name = tostring(ApiRead(Data, "Name", "Range"))
        local Minimum = tonumber(ApiRead(Data, "Min", 0)) or 0
        local Maximum = tonumber(ApiRead(Data, "Max", 100)) or 100
        local Defaults = ApiRead(Data, "Default", {Minimum, Maximum})
        local LowDefault = type(Defaults) == "table" and tonumber(Defaults[1] or Defaults.Min or Defaults.Minimum) or Minimum
        local HighDefault = type(Defaults) == "table" and tonumber(Defaults[2] or Defaults.Max or Defaults.Maximum) or Maximum
        LowDefault = LowDefault or Minimum
        HighDefault = HighDefault or Maximum
        local BaseFlag = tostring(ApiRead(Data, "Flag", Name))
        local LowFlag = tostring(ApiRead(Data, "MinFlag", BaseFlag .. " Minimum"))
        local HighFlag = tostring(ApiRead(Data, "MaxFlag", BaseFlag .. " Maximum"))
        local Callback = ApiRead(Data, "Callback")
        local Low = self:Slider({Name = Name .. " Min", Min = Minimum, Max = Maximum, Default = LowDefault, Flag = LowFlag, Precision = ApiRead(Data, "Precision", 0), Callback = function(Value)
            if Value > (tonumber(Menu.Flags[HighFlag]) or HighDefault) then
                Value = tonumber(Menu.Flags[HighFlag]) or HighDefault
                Menu.Flags[LowFlag] = Value
            end
            InvokeCallback(Callback, Value, Menu.Flags[HighFlag])
        end})
        local High = self:Slider({Name = Name .. " Max", Min = Minimum, Max = Maximum, Default = HighDefault, Flag = HighFlag, Precision = ApiRead(Data, "Precision", 0), Callback = function(Value)
            if Value < (tonumber(Menu.Flags[LowFlag]) or LowDefault) then
                Value = tonumber(Menu.Flags[LowFlag]) or LowDefault
                Menu.Flags[HighFlag] = Value
            end
            InvokeCallback(Callback, Menu.Flags[LowFlag], Value)
        end})
        return {
            Low = Low,
            High = High,
            Set = function(_, A, B)
                if A ~= nil then Menu.Setters[LowFlag](A) end
                if B ~= nil then Menu.Setters[HighFlag](B) end
            end,
            Get = function() return Menu.Flags[LowFlag], Menu.Flags[HighFlag] end
        }
    end

    function ApiSectionMethods:Dropdown(Data)
        Data = Data or {}
        local NativeSection = GetNativeSection(self)
        local Name = tostring(ApiRead(Data, "Name", "Dropdown"))
        local Flag = ApiNormalizeFlag(Data, Name)
        local Values = GetDropdownValues(Data)
        local Default = ApiRead(Data, "Default", Values[1])
        local Callback = ApiRead(Data, "Callback")
        local Control = NativeSection:AddDropdown({
            Name = Name,
            Default = Default,
            Values = Values,
            Multi = false,
            Flag = nil,
            Callback = function(Value)
                Menu.Flags[Flag] = Value
                InvokeCallback(Callback, Value)
            end
        })
        ApplyControlAliases(Control)
        RegisterNativeFlag(Flag, Default, function(Value) Control:SetValue(Value) end)
        Control.Flag = Flag
        Control.SetItems = function(Self, NewValues)
            local Clean = {}
            if type(NewValues) == "table" then
                for _, Value in ipairs(NewValues) do Clean[#Clean + 1] = tostring(type(Value) == "table" and (Value.Name or Value.Text or Value.Value or Value[1]) or Value) end
            end
            return Self:SetValues(Clean)
        end
        return Control
    end

    function ApiSectionMethods:MultiDropdown(Data)
        Data = Data or {}
        local NativeSection = GetNativeSection(self)
        local Name = tostring(ApiRead(Data, "Name", "Multi Dropdown"))
        local Flag = ApiNormalizeFlag(Data, Name)
        local Values = GetDropdownValues(Data)
        local Default = ApiRead(Data, "Default", {})
        local Callback = ApiRead(Data, "Callback")
        local Control = NativeSection:AddDropdown({
            Name = Name,
            Default = Default,
            Values = Values,
            Multi = true,
            Flag = nil,
            Callback = function(Value)
                Menu.Flags[Flag] = CloneFlagValue(Value)
                InvokeCallback(Callback, Value)
            end
        })
        ApplyControlAliases(Control)
        RegisterNativeFlag(Flag, Default, function(Value) Control:SetValue(type(Value) == "table" and Value or {}) end)
        Control.Flag = Flag
        Control.SetItems = function(Self, NewValues)
            local Clean = {}
            if type(NewValues) == "table" then
                for _, Value in ipairs(NewValues) do Clean[#Clean + 1] = tostring(type(Value) == "table" and (Value.Name or Value.Text or Value.Value or Value[1]) or Value) end
            end
            return Self:SetValues(Clean)
        end
        return Control
    end

    function ApiSectionMethods:FlagSelector(Data)
