    function ApiSectionMethods:Textbox(Data)
        Data = Data or {}
        local NativeSection = GetNativeSection(self)
        local Name = tostring(ApiRead(Data, "Name", "Textbox"))
        local Flag = ApiNormalizeFlag(Data, Name)
        local Default = tostring(ApiRead(Data, "Default", ""))
        local Callback = ApiRead(Data, "Callback")
        local Numeric = ApiRead(Data, "Numeric", false) == true
        local Control = NativeSection:AddTextBox({
            Name = Name,
            Default = Default,
            Placeholder = tostring(ApiRead(Data, "Placeholder", "")),
            Numeric = Numeric,
            Flag = nil,
            Callback = function(Value)
                local Result = Numeric and tonumber(Value) or Value
                if Result == nil then Result = Value end
                Menu.Flags[Flag] = Result
                InvokeCallback(Callback, Result)
            end
        })
        ApplyControlAliases(Control)
        RegisterNativeFlag(Flag, Numeric and (tonumber(Default) or 0) or Default, function(Value) Control:SetValue(Value) end)
        Control.Flag = Flag
        return Control
    end

