    function Library:Window(Data)
        Data = Data or {}
        Main.Visible = false
        Overlay.Visible = false
        InputBlocker.Visible = false
        ApiClearBuiltInContent()
        Main.Parent = nil

        if NativeWindowObject then
            return NativeWindowObject
        end

        Atramenta:ChangeHighlightColor(Accent)
        local WindowName = tostring(ApiRead(Data, "Name", "Atramenta.rip"))
        local Keybind = ApiRead(Data, "Keybind", "None")
        local Logo = ApiRead(Data, "Logo", LogoAsset or IconAsset or Atramenta.Logo)
        local Scale = ApiRead(Data, "Scale", UDim2.fromOffset(720, 560))

        NativeWindow = Atramenta.new({
            Name = WindowName,
            Keybind = Keybind,
            Logo = Logo,
            Scale = Scale,
            TextSize = tonumber(ApiRead(Data, "TextSize", 15)) or 15
        })
        NativeWindow:Update({WindowName = WindowName, Logo = Logo})

        local SettingsApi = NativeWindow.UserSettings:Create()
        SettingsApi:AddColorPicker({
            Name = "Accent",
            Default = Accent,
            Transparency = 0,
            Callback = function(Color)
                if typeof(Color) ~= "Color3" then return end
                UpdateAccentColor(Color)
                SaveAccentIfNeeded(Color)
                Atramenta:ChangeHighlightColor(Color)
            end
        })

        if not NativeAccentRegistered then
            NativeAccentRegistered = true
            RegisterAccentTarget(function(NewColor)
                Atramenta:ChangeHighlightColor(NewColor)
            end)
        end

        Menu.MainWindowController = {
            Native = NativeWindow,
            SetVisible = function(Self, State)
                State = State == true
                Menu.Visible = State
                if Self.Native then
                    Self.Native.IsOpen = State
                    Self.Native:Toggle(State)
                end
                Main.Visible = false
                Overlay.Visible = false
                InputBlocker.Visible = false
                if Menu.QuickPanelController and Menu.QuickPanelController.Refresh then
                    Menu.QuickPanelController.Refresh()
                end
            end,
            IsVisible = function()
                return Menu.Visible == true
            end
        }

        NativeWindowObject = setmetatable({Pages = {}, Native = NativeWindow}, ApiWindowMethods)
        ApiState.WindowObject = NativeWindowObject
        Menu.Visible = true
        Menu.MainWindowController:SetVisible(true)
        return NativeWindowObject
    end

