    local NotificationCardWidth = 390
    local NotificationCardHeight = 28
    local NotificationGap = 4
    local NotificationAccentTargets = setmetatable({}, {__mode = "k"})

    RegisterAccentTarget(function(NewColor)
        for Object in pairs(NotificationAccentTargets) do
            if Object and Object.Parent then
                Library.Call(function()
                    Object.BackgroundColor3 = NewColor
                end)
            else
                NotificationAccentTargets[Object] = nil
            end
        end
    end)

    local function FitNotificationText(Label, Minimum, Maximum)
        if not Label or not Label.Parent then return end
        Label.TextScaled = true
        Label.TextWrapped = false
        Label.TextTruncate = Enum.TextTruncate.None

        local Constraint = Label:FindFirstChildOfClass("UITextSizeConstraint")
        if not Constraint then
            Constraint = Create("UITextSizeConstraint", {
                Parent = Label,
                MinTextSize = Minimum or 7,
                MaxTextSize = Maximum or 11
            })
        else
            Constraint.MinTextSize = Minimum or 7
            Constraint.MaxTextSize = Maximum or 11
        end
    end

    function Library:SetNotificationLayout(Position, Scale)
        Menu.NotificationSettings = type(Menu.NotificationSettings) == "table" and Menu.NotificationSettings or {
            Position = "Top Right",
            Scale = 100
        }

        Menu.NotificationSettings.Position = tostring(Position or Menu.NotificationSettings.Position or "Top Right")
        Menu.NotificationSettings.Scale = math.clamp(tonumber(Scale) or Menu.NotificationSettings.Scale or 100, 60, 160)

        local Holder = Menu.NotificationHolder
        if not Holder or not Holder.Parent then return end

        local Name = Menu.NotificationSettings.Position
        local Horizontal = string.find(Name, "Left", 1, true) and "Left"
            or string.find(Name, "Center", 1, true) and "Center"
            or "Right"
        local Vertical = string.find(Name, "Bottom", 1, true) and "Bottom"
            or string.find(Name, "Middle", 1, true) and "Middle"
            or "Top"

        local X = Horizontal == "Left" and 0.018 or Horizontal == "Center" and 0.5 or 0.982
        local AnchorX = Horizontal == "Left" and 0 or Horizontal == "Center" and 0.5 or 1
        local Y = Vertical == "Top" and 0.045 or Vertical == "Middle" and 0.5 or 0.955
        local AnchorY = Vertical == "Top" and 0 or Vertical == "Middle" and 0.5 or 1

        Holder.AnchorPoint = Vector2.new(AnchorX, AnchorY)
        Holder.Position = UDim2.fromScale(X, Y)
        Holder.Size = UDim2.fromOffset(NotificationCardWidth, 700)

        local Layout = Holder:FindFirstChildOfClass("UIListLayout")
        if Layout then
            Layout.Padding = UDim.new(0, NotificationGap)
            Layout.HorizontalAlignment = Horizontal == "Left" and Enum.HorizontalAlignment.Left
                or Horizontal == "Center" and Enum.HorizontalAlignment.Center
                or Enum.HorizontalAlignment.Right
            Layout.VerticalAlignment = Vertical == "Top" and Enum.VerticalAlignment.Top
                or Vertical == "Middle" and Enum.VerticalAlignment.Center
                or Enum.VerticalAlignment.Bottom
        end

        local ScaleObject = Holder:FindFirstChild("AtramentaNotificationScale")
        if not ScaleObject then
            ScaleObject = Create("UIScale", {
                Parent = Holder,
                Name = "AtramentaNotificationScale",
                Scale = 1
            })
        end

        ScaleObject.Scale = Menu.NotificationSettings.Scale / 100
    end

    function Library:Notification(TitleOrData, DescriptionOrDuration, DurationOrColor, ModeValue)
        local Title
        local Description
        local Duration
        local Mode
        local LegacyColor

        if type(TitleOrData) == "table" then
            Title = tostring(TitleOrData.Title or TitleOrData.Name or "Notification")
            Description = tostring(TitleOrData.Description or TitleOrData.Message or "")
            Duration = tonumber(TitleOrData.Duration or TitleOrData.Time) or 4
            Mode = tostring(TitleOrData.Mode or TitleOrData.Type or "Success")
        elseif type(DescriptionOrDuration) == "number" then
            Description = tostring(TitleOrData or "Notification")
            Duration = tonumber(DescriptionOrDuration) or 4
            LegacyColor = typeof(DurationOrColor) == "Color3" and DurationOrColor or nil
            Mode = LegacyColor == Danger and "Danger" or "Success"
            Title = Mode == "Danger" and "Danger" or "Notification"
        else
            Title = tostring(TitleOrData or "Notification")
            Description = tostring(DescriptionOrDuration or "")
            Duration = tonumber(DurationOrColor) or 4
            Mode = tostring(ModeValue or "Success")
        end

        local NormalizedMode = string.lower(Mode)
        if NormalizedMode == "sucess" then NormalizedMode = "success" end
        if NormalizedMode ~= "success" and NormalizedMode ~= "warn" and NormalizedMode ~= "danger" then NormalizedMode = "success" end
        Duration = math.clamp(Duration, 0.5, 30)

        local ModeColor = NormalizedMode == "danger" and Color3.fromRGB(226, 78, 89)
            or NormalizedMode == "warn" and Color3.fromRGB(210, 165, 78)
            or Accent

        if LegacyColor then ModeColor = LegacyColor end

        local Environment = type(getgenv) == "function" and getgenv() or _G
        local GlobalState = rawget(Environment, "AtramentaNotificationState")

        if type(GlobalState) ~= "table" then
            GlobalState = {Last = {}}
            rawset(Environment, "AtramentaNotificationState", GlobalState)
        end

        GlobalState.Last = type(GlobalState.Last) == "table" and GlobalState.Last or {}

        local DedupeKey = string.lower(Title .. "\0" .. Description .. "\0" .. NormalizedMode)
        local CurrentTime = os.clock()
        local Previous = GlobalState.Last[DedupeKey]

        if type(Previous) == "table"
            and Previous.Frame
            and Previous.Frame.Parent
            and CurrentTime - (Previous.Time or 0) < 0.45
        then
            Previous.Time = CurrentTime
            Library:SetNotificationLayout()
            return Previous.Frame
        end

        Menu.NotificationSettings = type(Menu.NotificationSettings) == "table" and Menu.NotificationSettings or {
            Position = "Top Right",
            Scale = 100
        }

        if not Menu.NotificationHolder or not Menu.NotificationHolder.Parent then
            Menu.NotificationHolder = Create("Frame", {
                Parent = ScreenGui,
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -18, 0, 18),
                Size = UDim2.fromOffset(NotificationCardWidth, 700),
                BackgroundTransparency = 1,
                ZIndex = 258
            })

            Create("UIListLayout", {
                Parent = Menu.NotificationHolder,
                Padding = UDim.new(0, NotificationGap),
                HorizontalAlignment = Enum.HorizontalAlignment.Right,
                VerticalAlignment = Enum.VerticalAlignment.Top,
                SortOrder = Enum.SortOrder.LayoutOrder
            })

            Create("UIScale", {
                Parent = Menu.NotificationHolder,
                Name = "AtramentaNotificationScale",
                Scale = 1
            })
        end

        Library:SetNotificationLayout(Menu.NotificationSettings.Position, Menu.NotificationSettings.Scale)

        local Message = Title
        if Description ~= "" then Message = Message .. "  •  " .. Description end

        local NoticeWidth = NotificationCardWidth
        local NoticeHeight = NotificationCardHeight

        local Notice = Create("Frame", {
            Parent = Menu.NotificationHolder,
            Name = "AtramentaNotification",
            Size = UDim2.fromOffset(NotificationCardWidth, NotificationCardHeight),
            BackgroundColor3 = Color3.fromRGB(8, 10, 13),
            BackgroundTransparency = 0.08,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            ZIndex = 260
        })

        Corner(Notice, 4)
        local NoticeStroke = Stroke(
            Notice,
            Color3.fromRGB(34, 38, 44),
            0.14,
            1
)

        local AccentLine = Create("Frame", {
            Parent = Notice,
            Position = UDim2.fromOffset(0, 4),
            Size = UDim2.new(0, 2, 1, -8),
            BackgroundColor3 = ModeColor,
            BackgroundTransparency = 0.08,
            BorderSizePixel = 0,
            ZIndex = 262
        })

        Corner(AccentLine, 2)

        local MessageLabel = Create("TextLabel", {
            Parent = Notice,
            Position = UDim2.fromOffset(12, 4),
            Size = UDim2.new(1, -24, 1, -8),
            BackgroundTransparency = 1,
            Font = Enum.Font.BuilderSansMedium,
            Text = Message,
            TextColor3 = Color3.fromRGB(222, 225, 230),
            TextSize = 11,
            TextWrapped = false,
            TextTruncate = Enum.TextTruncate.None,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Center,
            ZIndex = 262
        })
        FitNotificationText(MessageLabel, 7, 11)

        local Track = Create("Frame", {
            Parent = Notice,
            Position = UDim2.new(0, 5, 1, -2),
            Size = UDim2.new(1, -10, 0, 1),
            BackgroundColor3 = Color3.fromRGB(29, 33, 38),
            BackgroundTransparency = 0.14,
            BorderSizePixel = 0,
            ZIndex = 261
        })

        local Progress = Create("Frame", {
            Parent = Track,
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = ModeColor,
            BackgroundTransparency = 0.05,
            BorderSizePixel = 0,
            ZIndex = 262
        })

        if NormalizedMode == "success" and not LegacyColor then
            NotificationAccentTargets[AccentLine] = true
            NotificationAccentTargets[Progress] = true
        end

        Notice:SetAttribute("AtramentaNotification", true)
        GlobalState.Last[DedupeKey] = {
            Time = CurrentTime,
            Frame = Notice
        }

        Notice.BackgroundTransparency = 1
        MessageLabel.TextTransparency = 1
        AccentLine.BackgroundTransparency = 1

        Tween(Notice, 0.13, {
            BackgroundTransparency = 0.04
        })

        Tween(MessageLabel, 0.13, {
            TextTransparency = 0
        })

        Tween(AccentLine, 0.13, {
            BackgroundTransparency = 0.04
        })

        TweenService:Create(
            Progress,
            TweenInfo.new(
                Duration,
                Enum.EasingStyle.Linear,
                Enum.EasingDirection.Out
),
            {
                Size = UDim2.new(0, 0, 1, 0)
            }
):Play()

        task.delay(Duration, function()
            if not Notice or not Notice.Parent then return end

            Tween(Notice, 0.16, {
                BackgroundTransparency = 1
            })

            Tween(MessageLabel, 0.16, {
                TextTransparency = 1
            })

            Tween(AccentLine, 0.16, {
                BackgroundTransparency = 1
            })

            if NoticeStroke then
                Tween(NoticeStroke, 0.16, {
                    Transparency = 1
                })
            end

            task.delay(0.17, function()
                if Notice and Notice.Parent then Notice:Destroy() end

                local Current = GlobalState.Last[DedupeKey]
                if type(Current) == "table" and Current.Frame == Notice then
                    GlobalState.Last[DedupeKey] = nil
                end
            end)
        end)

        return Notice
    end

    function Library:CombatLog(Data)
        Data = type(Data) == "table" and Data or {}

        local Kind =
            string.lower(
                tostring(
                    Data.Kind
                    or Data.Type
                    or "info"
)
)

        local Message =
            tostring(
                Data.Text
                or Data.Message
                or ""
)

        local Detail =
            tostring(
                Data.Detail
                or Data.Description
                or ""
)

        local Duration =
            math.clamp(
                tonumber(Data.Duration)
                    or 4.25,
                1.2,
                12
)

        local KindData = {
            hit = {
                Color = Color3.fromRGB(103, 203, 143),
                Icon = "Target"
            },
            kill = {
                Color = Color3.fromRGB(117, 219, 153),
                Icon = "Target"
            },
            miss = {
                Color = Color3.fromRGB(205, 169, 96),
                Icon = "Warning"
            },
            damage = {
                Color = Color3.fromRGB(205, 91, 102),
                Icon = "Shield"
            },
            nearmiss = {
                Color = Color3.fromRGB(100, 167, 208),
                Icon = "Eye"
            },
            info = {
                Color = Accent,
                Icon = "Lightning"
            }
        }

        local Style =
            KindData[Kind]
            or KindData.info

        local Environment =
            type(getgenv) == "function"
            and getgenv()
            or _G

        local GlobalState =
            rawget(
                Environment,
                "AtramentaCombatLogState"
)

        if type(GlobalState) ~= "table" then
            GlobalState = {
                Last = {},
                Serial = 0
            }

            rawset(
                Environment,
                "AtramentaCombatLogState",
                GlobalState
)
        end

        GlobalState.Last =
            type(GlobalState.Last) == "table"
            and GlobalState.Last
            or {}

        local FullText =
            "Atramenta  •  "
            .. Message

        if Detail ~= "" then
            FullText =
                FullText
                .. "  •  "
                .. Detail
        end

        local DedupeKey =
            Kind
            .. "\0"
            .. FullText

        local CurrentTime =
            os.clock()

        local Previous =
            GlobalState.Last[
                DedupeKey
            ]

        if type(Previous) == "table"
            and Previous.Root
            and Previous.Root.Parent
            and CurrentTime
                - (tonumber(Previous.Time) or 0)
                < 0.18
        then
            Previous.Time = CurrentTime
            return Previous.Root
        end

        if not Menu.CombatLogHolder
            or not Menu.CombatLogHolder.Parent
        then
            Menu.CombatLogHolder =
                Create("Frame", {
                    Parent = ScreenGui,
                    AnchorPoint =
                        Vector2.new(
                            1,
                            0
),
                    Position =
                        UDim2.new(
                            1,
                            -12,
                            0,
                            12
),
                    Size =
                        UDim2.fromOffset(
                            NotificationCardWidth,
                            700
),
                    BackgroundTransparency = 1,
                    ZIndex = 272
                })

            Create("UIListLayout", {
                Parent = Menu.CombatLogHolder,
                Padding = UDim.new(0, NotificationGap),
                HorizontalAlignment =
                    Enum.HorizontalAlignment.Right,
                VerticalAlignment =
                    Enum.VerticalAlignment.Top,
                SortOrder =
                    Enum.SortOrder.LayoutOrder
            })
        end

        GlobalState.Serial += 1

        local Font = Enum.Font.BuilderSansMedium
        local TextSize = 10
        local Width = NotificationCardWidth

        local Root =
            Create("Frame", {
                Parent = Menu.CombatLogHolder,
                Size =
                    UDim2.fromOffset(
                        NotificationCardWidth,
                        NotificationCardHeight
),
                BackgroundColor3 =
                    Color3.fromRGB(
                        10,
                        14,
                        17
),
                BackgroundTransparency = 0.24,
                BorderSizePixel = 0,
                LayoutOrder =
                    GlobalState.Serial,
                ClipsDescendants = true,
                ZIndex = 273
            })

        Corner(Root, 3)
        Stroke(
            Root,
            Border,
            0.62,
            1
)

        local AccentRail =
            Create("Frame", {
                Parent = Root,
                Position =
                    UDim2.fromOffset(
                        0,
                        4
),
                Size =
                    UDim2.new(
                        0,
                        2,
                        1,
                        -8
),
                BackgroundColor3 =
                    Style.Color,
                BackgroundTransparency = 0.08,
                BorderSizePixel = 0,
                ZIndex = 275
            })

        local IconHolder =
            Create("Frame", {
                Parent = Root,
                AnchorPoint =
                    Vector2.new(
                        0,
                        0.5
),
                Position =
                    UDim2.new(
                        0,
                        6,
                        0.5,
                        0
),
                Size =
                    UDim2.fromOffset(
                        18,
                        18
),
                BackgroundColor3 =
                    Style.Color,
                BackgroundTransparency = 0.88,
                BorderSizePixel = 0,
                ZIndex = 275
            })

        Corner(
            IconHolder,
            3
)

        Icon(
            IconHolder,
            Style.Icon,
            UDim2.fromOffset(
                9,
                9
),
            UDim2.fromScale(
                0.5,
                0.5
),
            Style.Color,
            276
)

        local Label =
            Create("TextLabel", {
                Parent = Root,
                Position =
                    UDim2.fromOffset(
                        29,
                        3
),
                Size =
                    UDim2.new(
                        1,
                        -36,
                        1,
                        -6
),
                BackgroundTransparency = 1,
                Font = Font,
                Text = FullText,
                TextColor3 =
                    Color3.fromRGB(
                        205,
                        213,
                        216
),
                TextSize = TextSize,
                TextWrapped = false,
                TextScaled = true,
                TextXAlignment =
                    Enum.TextXAlignment.Left,
                TextYAlignment =
                    Enum.TextYAlignment.Center,
                TextTruncate =
                    Enum.TextTruncate.None,
                ZIndex = 276
            })

        FitNotificationText(Label, 7, 10)

        Root.BackgroundTransparency = 1
        Label.TextTransparency = 1
        IconHolder.BackgroundTransparency = 1
        AccentRail.BackgroundTransparency = 1

        Tween(
            Root,
            0.11,
            {
                BackgroundTransparency = 0.24
            }
)

        Tween(
            Label,
            0.11,
            {
                TextTransparency = 0
            }
)

        Tween(
            IconHolder,
            0.11,
            {
                BackgroundTransparency = 0.88
            }
)

        Tween(
            AccentRail,
            0.11,
            {
                BackgroundTransparency = 0.08
            }
)

        GlobalState.Last[
            DedupeKey
        ] = {
            Root = Root,
            Time = CurrentTime
        }

        task.delay(
            Duration,
            function()
                if not Root
                    or not Root.Parent
                then
                    return
                end

                Tween(
                    Root,
                    0.13,
                    {
                        BackgroundTransparency = 1
                    }
)

                Tween(
                    Label,
                    0.13,
                    {
                        TextTransparency = 1
                    }
)

                Tween(
                    IconHolder,
                    0.13,
                    {
                        BackgroundTransparency = 1
                    }
)

                Tween(
                    AccentRail,
                    0.13,
                    {
                        BackgroundTransparency = 1
                    }
)

                task.delay(
                    0.14,
                    function()
                        if Root
                            and Root.Parent
                        then
                            Root:Destroy()
                        end

                        local Current =
                            GlobalState.Last[
                                DedupeKey
                            ]

                        if type(Current) == "table"
                            and Current.Root == Root
                        then
                            GlobalState.Last[
                                DedupeKey
                            ] = nil
                        end
                    end
)
            end
)

        return Root
    end

    function Library:ClearCombatLogs()
        if Menu.CombatLogHolder
            and Menu.CombatLogHolder.Parent
        then
            for _, Child in ipairs(
                Menu.CombatLogHolder:
                    GetChildren()
) do
                if Child:IsA("Frame") then
                    Child:Destroy()
                end
            end
        end

        local Environment =
            type(getgenv) == "function"
            and getgenv()
            or _G

        local GlobalState =
            rawget(
                Environment,
                "AtramentaCombatLogState"
)

        if type(GlobalState) == "table" then
            GlobalState.Last = {}
        end
    end

    function Library:GetConfig()
        if Menu.EspPreviewController and type(Menu.EspPreviewController.CommitLayout) == "function" then
            Library.Call(Menu.EspPreviewController.CommitLayout)
        end
        if Menu.BindSystem and type(Menu.BindSystem.NormalizeStorage) == "function" then
            Library.Call(Menu.BindSystem.NormalizeStorage)
        end

        local Seen = {}

        local function IsFiniteNumber(Value)
            return type(Value) == "number" and Value == Value and Value > -math.huge and Value < math.huge
        end

        local function EncodeValue(Value, Depth)
            Depth = Depth or 0
            if Depth > 8 then return nil end

            local ValueType = typeof(Value)
            if ValueType == "Color3" then
                return {__type = "Color3", R = Value.R, G = Value.G, B = Value.B}
            elseif ValueType == "EnumItem" then
                return {__type = "EnumItem", EnumType = tostring(Value.EnumType), Name = Value.Name}
            elseif ValueType == "Vector2" then
                return {__type = "Vector2", X = Value.X, Y = Value.Y}
            elseif ValueType == "Vector3" then
                return {__type = "Vector3", X = Value.X, Y = Value.Y, Z = Value.Z}
            elseif ValueType == "UDim2" then
                return {
                    __type = "UDim2",
                    XScale = Value.X.Scale,
                    XOffset = Value.X.Offset,
                    YScale = Value.Y.Scale,
                    YOffset = Value.Y.Offset
                }
            elseif type(Value) == "boolean" or type(Value) == "string" then
                return Value
            elseif type(Value) == "number" then
                return IsFiniteNumber(Value) and Value or nil
            elseif type(Value) ~= "table" then
                return nil
            end

            if Seen[Value] then return nil end
            Seen[Value] = true

            local IsArray = true
            local Count = 0
            local MaximumIndex = 0
            for Key in pairs(Value) do
                Count += 1
                if type(Key) ~= "number" or Key < 1 or Key % 1 ~= 0 then
                    IsArray = false
                    break
                end
                if Key > MaximumIndex then MaximumIndex = Key end
            end
            IsArray = IsArray and Count == MaximumIndex

            local Result = {}
            if IsArray then
                for Index = 1, MaximumIndex do
                    local EncodedItem = EncodeValue(Value[Index], Depth + 1)
                    if EncodedItem ~= nil then
                        Result[#Result + 1] = EncodedItem
                    end
                end
            else
                for Key, Item in pairs(Value) do
                    local KeyType = type(Key)
                    if KeyType == "string" or KeyType == "number" then
                        local EncodedItem = EncodeValue(Item, Depth + 1)
                        if EncodedItem ~= nil then
                            Result[tostring(Key)] = EncodedItem
                        end
                    end
                end
            end

            Seen[Value] = nil
            return Result
        end

        local ConfigExcludedFlags = {
            AccentAlpha = true
        }

        local Encoded = {}
        for Name, Value in pairs(self.Flags or {}) do
            local ConfigName = tostring(Name)
            if ConfigExcludedFlags[ConfigName] ~= true then
                local Success, EncodedValue = Library.Call(EncodeValue, Value, 0)
                if Success and EncodedValue ~= nil then
                    Encoded[ConfigName] = EncodedValue
                end
            end
        end
        local BindsSuccess, EncodedBinds = Library.Call(EncodeValue, SavedPositions.ControlBinds or {}, 0)
        if BindsSuccess and EncodedBinds ~= nil then
            Encoded.__AtramentaControlBinds = EncodedBinds
        end

        local InterfaceState = {
            BackgroundDim = Menu.Flags.BackgroundDim,
            AnimationSpeed = Menu.Flags.AnimationSpeed,
            MenuScale = Menu.Flags.MenuScale,
            PlayerListScale = Menu.Flags.PlayerListScale or SavedPositions.PlayerListScale,
            EspPreviewScale = Menu.Flags.EspPreviewScale or SavedPositions.EspPreviewScale,
            HideWatermark = SavedPositions.HideWatermark,
            WatermarkScale = SavedPositions.WatermarkScale,
            HideKeybinds = SavedPositions.HideKeybinds,
            KeybindListScale = SavedPositions.KeybindListScale
        }
        local InterfaceSuccess, EncodedInterface = Library.Call(EncodeValue, InterfaceState, 0)
        if InterfaceSuccess and EncodedInterface ~= nil then
            Encoded.__AtramentaInterface = EncodedInterface
        end

        local Success, Source = Library.Call(HttpService.JSONEncode, HttpService, Encoded)
        if Success and type(Source) == "string" then
            return Source
        end

        local SafeEncoded = {}
        for Name, Value in pairs(Encoded) do
            SafeEncoded[Name] = Value
            local TestSuccess = Library.Call(HttpService.JSONEncode, HttpService, SafeEncoded)
            if not TestSuccess then
                SafeEncoded[Name] = nil
            end
        end

        local FallbackSuccess, FallbackSource = Library.Call(HttpService.JSONEncode, HttpService, SafeEncoded)
        return FallbackSuccess and FallbackSource or "{}"
    end

    function Library:LoadConfig(Source)
        local Success, Decoded = Library.Call(HttpService.JSONDecode, HttpService, tostring(Source or "{}"))
        if not Success or type(Decoded) ~= "table" then return false end

        Menu.ConfigLoadGeneration = (tonumber(Menu.ConfigLoadGeneration) or 0) + 1
        local Generation = Menu.ConfigLoadGeneration
        Menu.ConfigApplying = true

        ClosePopup()
        if CloseGearMenus then CloseGearMenus() end
        if SetPickerOpen then SetPickerOpen(false) end
        Menu.QuickPanelBindCapture = false

        if Menu.RefreshDropdownIndicators then Menu.RefreshDropdownIndicators(true) end

        local function DecodeValue(Value, Depth)
            Depth = Depth or 0
            if Depth > 8 or type(Value) ~= "table" then return Value end

            if Value.__type == "Color3" then
                return Color3.new(tonumber(Value.R) or 0, tonumber(Value.G) or 0, tonumber(Value.B) or 0)
            elseif Value.__type == "EnumItem" then
                local EnumName = tostring(Value.EnumType or ""):match("Enum%.(.+)")
                local EnumType = EnumName and Enum[EnumName]
                return EnumType and EnumType[Value.Name] or Value.Name
            elseif Value.__type == "Vector2" then
                return Vector2.new(tonumber(Value.X) or 0, tonumber(Value.Y) or 0)
            elseif Value.__type == "Vector3" then
                return Vector3.new(tonumber(Value.X) or 0, tonumber(Value.Y) or 0, tonumber(Value.Z) or 0)
            elseif Value.__type == "UDim2" then
                return UDim2.new(
                    tonumber(Value.XScale) or 0,
                    tonumber(Value.XOffset) or 0,
                    tonumber(Value.YScale) or 0,
                    tonumber(Value.YOffset) or 0
)
            end

            local Result = {}
            for Key, Item in pairs(Value) do Result[Key] = DecodeValue(Item, Depth + 1) end
            return Result
        end

        local LoadedBinds = Decoded.__AtramentaControlBinds
        Decoded.__AtramentaControlBinds = nil
        local LoadedInterface = Decoded.__AtramentaInterface
        Decoded.__AtramentaInterface = nil

        Decoded.AccentAlpha = nil

        local DecodedFlags = {}
        for Name, Value in pairs(Decoded) do
            if tostring(Name) ~= "AccentAlpha" then
                DecodedFlags[tostring(Name)] = DecodeValue(Value, 0)
            end
        end

        for Name in pairs(Menu.LastConfigFlags or {}) do
            if Name ~= "AccentAlpha" and DecodedFlags[Name] == nil and Menu.DefaultFlagKnown[Name] ~= true then
                if type(self.Setters[Name]) == "function" then
                    Library.Call(function() self:SetFlag(Name, nil) end)
                else
                    self.Flags[Name] = nil
                end
            end
        end

        Menu.LastConfigFlags = Menu.LastConfigFlags or {}
        table.clear(Menu.LastConfigFlags)
        for Name in pairs(DecodedFlags) do Menu.LastConfigFlags[Name] = true end

        local Applied = {}

        for Flag in pairs(Menu.DefaultFlagKnown) do
            local Desired
            if DecodedFlags[Flag] ~= nil then
                Desired = CloneFlagValue(DecodedFlags[Flag])
            else
                Desired = CloneFlagValue(Menu.DefaultFlags[Flag])
            end

            Applied[Flag] = true

            if not FlagValuesEqual(self.Flags[Flag], Desired) then
                Library.Call(function() self:SetFlag(Flag, Desired) end)
            end
        end

        for Name, Value in pairs(DecodedFlags) do
            if not Applied[Name] and not FlagValuesEqual(self.Flags[Name], Value) then
                Library.Call(function() self:SetFlag(Name, CloneFlagValue(Value)) end)
            end
        end

        local NextBinds = LoadedBinds ~= nil and DecodeValue(LoadedBinds, 0) or {}
        if type(NextBinds) ~= "table" then NextBinds = {} end

        if not FlagValuesEqual(SavedPositions.ControlBinds or {}, NextBinds) then
            SavedPositions.ControlBinds = CloneFlagValue(NextBinds)

            if Menu.BindSystem and type(Menu.BindSystem.GetControlBinds) == "function" then
                for Flag in pairs(NextBinds) do Menu.BindSystem.GetControlBinds(Flag) end
            end

            if Menu.BindSystem and type(Menu.BindSystem.NormalizeStorage) == "function" then
                Menu.BindSystem.NormalizeStorage()
            end
        end

        local Interface = LoadedInterface ~= nil and DecodeValue(LoadedInterface, 0) or {}
        if type(Interface) ~= "table" then Interface = {} end

        local function ApplyInterfaceControl(Control, Value)
            if Value == nil or type(Control) ~= "table" or type(Control.Set) ~= "function" then return end
            Library.Call(Control.Set, Value)
        end

        ApplyInterfaceControl(Menu.SettingsUI.BackgroundDimToggle, Interface.BackgroundDim)
        ApplyInterfaceControl(Menu.SettingsUI.AnimationSpeedSlider, Interface.AnimationSpeed)
        ApplyInterfaceControl(Menu.SettingsUI.MenuScaleSlider, Interface.MenuScale)
        ApplyInterfaceControl(Menu.SettingsUI.PlayerListSizeSlider, Interface.PlayerListScale)
        ApplyInterfaceControl(Menu.SettingsUI.EspPreviewSizeSlider, Interface.EspPreviewScale)
        ApplyInterfaceControl(Menu.SettingsUI.HideWatermarkToggle, Interface.HideWatermark)
        ApplyInterfaceControl(Menu.SettingsUI.WatermarkSizeSlider, Interface.WatermarkScale)
        ApplyInterfaceControl(Menu.SettingsUI.HideKeybindsToggle, Interface.HideKeybinds)
        ApplyInterfaceControl(Menu.SettingsUI.KeybindListSizeSlider, Interface.KeybindListScale)

        Menu.Flags.AccentAlpha = AccentAlpha

        if Menu.KeybindListController and Menu.KeybindListController.MarkDirty then
            Menu.KeybindListController.MarkDirty()
        end

        local function RefreshLoadedUI()
            if Generation ~= Menu.ConfigLoadGeneration then return end

            if Menu.RefreshDropdownIndicators then Menu.RefreshDropdownIndicators(true) end

            UpdateAccentColor(Accent)

            if Menu.ConfigsUI then
                if Menu.ConfigsUI.AddIcon and Menu.ConfigsUI.AddIcon.Sync then Menu.ConfigsUI.AddIcon.Sync(Accent) end
                if Menu.ConfigsUI.RemoveIcon and Menu.ConfigsUI.RemoveIcon.Sync then Menu.ConfigsUI.RemoveIcon.Sync(Accent) end
            end

            if Menu.EspPreviewController and Menu.EspPreviewController.RefreshFromFlags then
                Menu.EspPreviewController.RefreshFromFlags()
            end
            if Menu.KeybindListController and Menu.KeybindListController.Refresh then Menu.KeybindListController.Refresh() end
            if Menu.QuickPanelController and Menu.QuickPanelController.Refresh then Menu.QuickPanelController.Refresh() end
            if Menu.PlayerListController and Menu.PlayerListController.Refresh then Menu.PlayerListController:Refresh() end
        end

        RefreshLoadedUI()

        task.defer(function()
            if Generation == Menu.ConfigLoadGeneration then RefreshLoadedUI() end
        end)

        task.delay(0.08, function()
            if Generation == Menu.ConfigLoadGeneration then RefreshLoadedUI() end
        end)

        Menu.ConfigApplying = false
        SavePositions()
        return true
    end

    function Library:RefreshConfigsList(Listbox)
        local Items = {}
        local Folder = self.Folders and self.Folders.Configs
        if type(Folder) == "string" and type(listfiles) == "function" and isfolder(Folder) then
            local Success, Files = Library.Call(listfiles, Folder)
            if Success and type(Files) == "table" then
                for _, File in ipairs(Files) do
                    local Name = tostring(File):match("([^/\\]+)$")
                    if Name and Name:sub(-5):lower() == ".json" then table.insert(Items, Name) end
                end
            end
        end
        table.sort(Items)
        if type(Listbox) == "table" and type(Listbox.SetItems) == "function" then Listbox:SetItems(Items) end
        return Items
    end

    Library.Folders = Library.Folders or {}
    Library.Folders.Root = Library.Folders.Root or "Atramenta.rip"
    Library.Folders.Configs = Library.Folders.Configs or (Library.Folders.Root .. "/Configs")
    if type(isfolder) == "function" and type(makefolder) == "function" then
        if not isfolder(Library.Folders.Root) then Library.Call(makefolder, Library.Folders.Root) end
        if not isfolder(Library.Folders.Configs) then Library.Call(makefolder, Library.Folders.Configs) end
    end

    return Library
    end

    return Menu:InstallPublicApi()
end

local function ResolveRuntime()
    if Runtime then
        return Runtime
    end
    Runtime = BuildRuntime()
    Library.Flags = Runtime.Flags
    Library.Setters = Runtime.Setters
    Library.Folders = Runtime.Folders or Library.Folders
    return Runtime
end

function Library:Window(Data)
    local ActiveRuntime = ResolveRuntime()
    local Window = ActiveRuntime:Window(Data)
    ActiveRuntime:SetVisible(true)
    return Window
end

function Library:SetVisible(State)
    ResolveRuntime():SetVisible(State)
end

function Library:Toggle()
    ResolveRuntime():Toggle()
end

function Library:GetFlag(Name)
    if not Runtime then
        return self.Flags[Name]
    end
    return Runtime:GetFlag(Name)
end

function Library:SetFlag(Name, Value)
    ResolveRuntime():SetFlag(Name, Value)
end

function Library:Notification(...)
    return ResolveRuntime():Notification(...)
end

function Library:SetNotificationLayout(...)
    return ResolveRuntime():SetNotificationLayout(...)
end

function Library:CombatLog(...)
    return ResolveRuntime():CombatLog(...)
end

function Library:ClearCombatLogs(...)
    return ResolveRuntime():ClearCombatLogs(...)
end

function Library:AntiAimIndicator(...)
    return ResolveRuntime():AntiAimIndicator(...)
end

function Library:Watermark(...)
    return ResolveRuntime():Watermark(...)
end

function Library:KeybindList(...)
    return ResolveRuntime():KeybindList(...)
end

function Library:QuickPanel(...)
    return ResolveRuntime():QuickPanel(...)
end

function Library:PlayerList(...)
    return ResolveRuntime():PlayerList(...)
end

function Library:GetPlayerStatus(...)
    return ResolveRuntime():GetPlayerStatus(...)
end

function Library:SetPlayerStatus(...)
    return ResolveRuntime():SetPlayerStatus(...)
end

function Library:GetConfig(...)
    return ResolveRuntime():GetConfig(...)
end

function Library:LoadConfig(...)
    return ResolveRuntime():LoadConfig(...)
end

function Library:RefreshConfigsList(...)
    return ResolveRuntime():RefreshConfigsList(...)
end

function Library:Destroy()
    if Runtime then
        Runtime:Destroy()
        Runtime = nil
        self.Flags = {}
        self.Setters = {}
    end
end

Library.window = Library.Window
Library.setvisible = Library.SetVisible
Library.toggle = Library.Toggle
Library.getflag = Library.GetFlag
Library.setflag = Library.SetFlag
Library.notification = Library.Notification
Library.setnotificationlayout = Library.SetNotificationLayout
Library.NotificationSkinVersion = 345
Library.FlagSelectorVersion = 1
Library.combatlog = Library.CombatLog
Library.clearcombatlogs = Library.ClearCombatLogs
Library.antiaimindicator = Library.AntiAimIndicator
Library.playerlist = Library.PlayerList
Library.getplayerstatus = Library.GetPlayerStatus
Library.setplayerstatus = Library.SetPlayerStatus
Library.destroy = Library.Destroy

return Library
